(window.__qhadithX=window.__qhadithX||{})[4]={"1":[{"c":"Sahih Muslim","r":"Hadith 1017a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1017a","x":"Mundhir b. Jarir reported on the authority of his father:\n\nWhile we were in the company of the Messenger of Allah (ﷺ) in the early hours of the morning, some people came there (who) were barefooted, naked, wearing striped woollen clothes, or cloaks, with their swords hung (around their necks). Most of them, nay, all of them, belonged to the tribe of Mudar. The colour of the face of the Messenger of Allah (ﷺ) underwent a change when he saw them in poverty. He then entered (his house) and came out and commanded Bilal (to pronounce Adhan). He pronounced Adhan and Iqima, and he (the Holy Prophet) observed prayer (along with his Companion) and then addressed (them reciting verses of the Holy Qur'an): '\" 0 people, fear your Lord, Who created you from a single being\" to the end of the verse,\" Allah is ever a Watcher over you\" (iv. 1). (He then recited) a verse of Sura Hashr:\" Fear Allah. and let every soul consider that which it sends forth for the morrow and fear Allah\" (lix. 18). (Then the audience began to vie with one another in giving charity.) Some donated a dinar, others a dirham, still others clothes, some donated a sa' of wheat, some a sa' of dates; till he (the Holy Prophet) said: (Bring) even if it is half a date. Then a person from among the Ansar came there with a money bag which his hands could scarcely lift; in fact, they could not (lift). Then the people followed continuously, till I saw two heaps of eatables and clothes, and I saw the face of the Messenger (ﷺ) glistening, like gold (on account of joy). The Messenger of Allah (ﷺ) said: He who sets a good precedent in Islam, there is a reward for him for this (act of goodness) and reward of that also who acted according to it subsequently, without any deduction from their rewards; and he who sets in Islam an evil precedent, there is upon him the burden of that, and the burden of him also who acted upon it subsequently, without any deduction from their burden.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَوْنِ، بْنِ أَبِي جُحَيْفَةَ عَنِ الْمُنْذِرِ بْنِ جَرِيرٍ، عَنْ أَبِيهِ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي صَدْرِ النَّهَارِ قَالَ فَجَاءَهُ قَوْمٌ حُفَاةٌ عُرَاةٌ مُجْتَابِي النِّمَارِ أَوِ الْعَبَاءِ مُتَقَلِّدِي السُّيُوفِ عَامَّتُهُمْ مِنْ مُضَرَ بَلْ كُلُّهُمْ مِنْ مُضَرَ فَتَمَعَّرَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم لِمَا رَأَى بِهِمْ مِنَ الْفَاقَةِ فَدَخَلَ ثُمَّ خَرَجَ فَأَمَرَ بِلاَلاً فَأَذَّنَ وَأَقَامَ فَصَلَّى ثُمَّ خَطَبَ فَقَالَ ‏\"‏ ‏{‏ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ‏}‏ إِلَى آخِرِ الآيَةِ ‏{‏ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا‏}‏ وَالآيَةَ الَّتِي فِي الْحَشْرِ ‏{‏ اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ‏}‏ تَصَدَّقَ رَجُلٌ مِنْ دِينَارِهِ مِنْ دِرْهَمِهِ مِنْ ثَوْبِهِ مِنْ صَاعِ بُرِّهِ مِنْ صَاعِ تَمْرِهِ - حَتَّى قَالَ - وَلَوْ بِشِقِّ تَمْرَةٍ ‏\"‏ ‏.‏ قَالَ فَجَاءَ رَجُلٌ مِنَ الأَنْصَارِ بِصُرَّةٍ كَادَتْ كَفُّهُ تَعْجِزُ عَنْهَا بَلْ قَدْ عَجَزَتْ - قَالَ - ثُمَّ تَتَابَعَ النَّاسُ حَتَّى رَأَيْتُ كَوْمَيْنِ مِنْ طَعَامٍ وَثِيَابٍ حَتَّى رَأَيْتُ وَجْهَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَتَهَلَّلُ كَأَنَّهُ مُذْهَبَةٌ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَىْءٌ وَمَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَوْزَارِهِمْ شَىْءٌ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1017c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1017c","x":"Mundhir b. Jarir narrated on the authority of his father:\n\nWhen we were sitting in the company of the Messenger of Allah (ﷺ). There came people dressed in striped woollen clothes, and the rest of the hadith in the same, and there (it is also mentioned):\" He observed the Zuhr prayer and then climbed up a small pulpit, praised Allah, lauded Him, and then said: Verily Allah in His Book has revealed: 'O people, fear your Lord, ' etc.\" (iv. 1).","ar":"حَدَّثَنِي عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ، وَأَبُو كَامِلٍ وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ الأُمَوِيُّ قَالُوا حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنِ الْمُنْذِرِ بْنِ جَرِيرٍ، عَنْ أَبِيهِ، قَالَ كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَأَتَاهُ قَوْمٌ مُجْتَابِي النِّمَارِ وَسَاقُوا الْحَدِيثَ بِقِصَّتِهِ وَفِيهِ فَصَلَّى الظُّهْرَ ثُمَّ صَعِدَ مِنْبَرًا صَغِيرًا فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏\"‏ أَمَّا بَعْدُ فَإِنَّ اللَّهَ أَنْزَلَ فِي كِتَابِهِ ‏{‏ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ‏}‏ الآيَةَ ‏\"‏ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 171","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-171","x":"Jarir bin 'Abdullah (May Allah be pleased with him) reported:\n\nWe were with Messenger of Allah (ﷺ) shortly after dawn when there came to him some people clad in woollen rags, or covered with sleeveless blankets; and with swords hanging down from their necks. Most of them rather, all of them, belonged to the Mudar tribe. The face of the Prophet (ﷺ) changed when he saw them starving. Then he went into his house and came out; then he commanded Bilal (May Allah be pleased with him) to proclaim Adhan (call to prayers). So he proclaimed Adhan and recited Iqamah and the Prophet (ﷺ) led the Salat. Then he delivered a Khutbah saying, \"O mankind! Be dutiful to your Rubb, Who created you from a single person (Adam), and from him (Adam) He created his wife (Eve), and from them both He created many men and women; and fear Allah through Whom you demand your (natural) rights, and do not sever the relations of kinship. Surely, Allah is Ever an All-Watcher over you.\" (4:1) He also recited the Ayah which is in the end of Surat Al-Hashr: \"O you who believe! Fear Allah and keep your duty to Him. And let every one look what he has sent forth for the tomorrow\". (59:18). Thereafter, every man gave in charity Dinar, Dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date\". Then a man of the Ansar came with a bag which was difficult for him to hold in his hand. Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes. I noticed that the face of Messenger of Allah (ﷺ) was glowing like that of the bright moon or glittering gold. Then he (ﷺ) said, \"Whosoever introduces a good practice in Islam, there is for him its reward and the reward of those who act upon it after him without anything being diminished from their rewards. And whosoever introduces an evil practice in Islam, will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden\"[Muslim].","ar":"عن أبي عمرو، جرير بن عبد الله، رضي الله عنه ، قال‏:‏ كنا في صدر النهار عند رسول الله، صلى الله عليه وسلم، فجاءه قوم عراة مجتابي النمار، أو العباء، متقلدي السيوف، عامتهم من مضر، بل كلهم من مضر؛ فتمعر وجه رسول الله، صلى الله عليه وسلم، لما رأى بهم من الفاقة؛ فدخل ثم خرج، فأمر بلالاً فأذن وأقام، فصلى ثم خطب؛ فقال‏:‏ ‏{‏يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة‏}‏ إلى آخر الآية‏:‏ ‏{‏إن الله كان عليكم رقيبا‏}‏، والآية الأخرى التي في آخر الحشر‏:‏ ‏{‏يا أيها الذين آمنوا اتقوا الله ولتنظر نفس ما قدمت لغد‏}‏ تصدق رجل من ديناره من درهمه من ثوبه من صاع بره من صاع تمره _حتى قال _ ولو بشق تمرة ‏,‏فجاء رجل من الأنصار بصرة كادت كفه تعجز عنها، بل قد عجزت، ثم تتابع الناس حتى رأيت كومين من طعام وثياب، حتى رأيت وجه رسول الله، صلى الله عليه وسلم، يتهلل كأنه مذهبة، فقال رسول الله، صلى الله عليه وسلم، ‏\n\n\"‏ من سن في الإسلام سنة حسنة فله أجرها، وأجر من عمل بها من بعده من غير أن يقنص من أجورهم شيء، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعده من غير أن ينقص من أوزارهم شيء‏\"\n\n‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏","v":[]}],"2":[{"c":"Sahih Bukhari","r":"Hadith 2763","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2763","x":"Narrated Az-Zuhri:\n\n`Urwa bin Az-Zubair said that he asked `Aisha about the meaning of the Qur'anic Verse:-- \"And if you fear that you will not deal fairly with the orphan girls then marry (other) women of your choice.\" (4.2-3) Aisha said, \"It is about a female orphan under the guardianship of her guardian who is inclined towards her because of her beauty and wealth, and likes to marry her with a Mahr less than what is given to women of her standard. So they (i.e. guardians) were forbidden to marry the orphans unless they paid them a full appropriate Mahr (otherwise) they were ordered to marry other women instead of them. Later on the people asked Allah's Messenger (ﷺ) about it. So Allah revealed the following Verse:-- \"They ask your instruction (O Muhammad!) regarding women. Say: Allah instructs you regarding them...\" (4.127) and in this Verse Allah indicated that if the orphan girl was beautiful and wealthy, her guardian would have the desire to marry her without giving her an appropriate Mahr equal to what her peers could get, but if she was undesirable for lack of beauty or wealth, then he would not marry her, but seek to marry some other woman instead of her. So, since he did not marry her when he had no inclination towards her, he had not the right to marry her when he had an interest in her, unless he treated her justly by giving her a full Mahr and securing all her rights.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ كَانَ عُرْوَةُ بْنُ الزُّبَيْرِ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ قَالَتْ عَائِشَةُ ثُمَّ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ قَالَتْ فَبَيَّنَ اللَّهُ فِي هَذِهِ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ جَمَالٍ وَمَالٍ رَغِبُوا فِي نِكَاحِهَا، وَلَمْ يُلْحِقُوهَا بِسُنَّتِهَا بِإِكْمَالِ الصَّدَاقِ، فَإِذَا كَانَتْ مَرْغُوبَةً عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ تَرَكُوهَا وَالْتَمَسُوا غَيْرَهَا مِنَ النِّسَاءِ، قَالَ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا إِلاَّ أَنْ يُقْسِطُوا لَهَا الأَوْفَى مِنَ الصَّدَاقِ وَيُعْطُوهَا حَقَّهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2766","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2766","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"Avoid the seven great destructive sins.\" The people enquire, \"O Allah's Messenger (ﷺ)! What are they? \"He said, \"To join others in worship along with Allah, to practice sorcery, to kill the life which Allah has forbidden except for a just cause, (according to Islamic law), to eat up Riba (usury), to eat up an orphan's wealth, to give back to the enemy and fleeing from the battlefield at the time of fighting, and to accuse, chaste women, who never even think of anything touching chastity and are good believers.","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ ثَوْرِ بْنِ زَيْدٍ الْمَدَنِيِّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ ‏\"‏‏.‏ قَالُوا يَا رَسُولَ اللَّهِ، وَمَا هُنَّ قَالَ ‏\"‏ الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ ‏\"‏‏.‏","v":[]}],"3":[{"c":"Sunan Abu Dawud","r":"Hadith 2073","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2073","x":"Rabi' b. Saburah reported on the authority of his father:\n\nThe Messenger of Allah (ﷺ) prohibited temporary marriage with women.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ رَبِيعِ بْنِ سَبْرَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم حَرَّمَ مُتْعَةَ النِّسَاءِ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2494","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2494","x":"Narrated `Urwa bin Az-Zubair:\n\nThat he had asked `Aisha about the meaning of the Statement of Allah: \"If you fear that you shall not Be able to deal justly With the orphan girls, then Marry (Other) women of your choice Two or three or four.\" (4.3) She said, \"O my nephew! This is about the orphan girl who lives with her guardian and shares his property. Her wealth and beauty may tempt him to marry her without giving her an adequate Mahr (bridal-money) which might have been given by another suitor. So, such guardians were forbidden to marry such orphan girls unless they treated them justly and gave them the most suitable Mahr; otherwise they were ordered to marry any other woman.\" `Aisha further said, \"After that verse the people again asked the Prophet (about the marriage with orphan 'girls), so Allah revealed the following verses:-- 'They ask your instruction Concerning the women. Say: Allah Instructs you about them And about what is Recited unto you In the Book, concerning The orphan girls to whom You give not the prescribed portions and yet whom you Desire to marry...\" (4.127) What is meant by Allah's Saying:-- 'And about what is Recited unto you is the former verse which goes:-- 'If you fear that you shall not Be able to deal justly With the orphan girls, then Marry (other) women of your choice.' (4.3) `Aisha said, \"Allah's saying in the other verse:--'Yet whom you desire to marry' (4.127) means the desire of the guardian to marry an orphan girl under his supervision when she has not much property or beauty (in which case he should treat her justly). The guardians were forbidden to marry their orphan girls possessing property and beauty without being just to them, as they generally refrain from marrying them (when they are neither beautiful nor wealthy).","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ الْعَامِرِيُّ الأُوَيْسِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ وَقَالَ اللَّيْثُ حَدَّثَنِي يُونُسُ عَنِ ابْنِ شِهَابٍ قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ عَنْ قَوْلِ اللَّهِ تَعَالَى ‏{‏وَإِنْ خِفْتُمْ‏}‏ إِلَى ‏{‏وَرُبَاعَ‏}‏‏.‏ فَقَالَتْ يَا ابْنَ أُخْتِي هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا تُشَارِكُهُ فِي مَالِهِ، فَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا، فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا، فَيُعْطِيهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ، فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ وَيَبْلُغُوا بِهِنَّ أَعْلَى سُنَّتِهِنَّ مِنَ الصَّدَاقِ، وَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ ثُمَّ إِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى قَوْلِهِ ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ وَالَّذِي ذَكَرَ اللَّهُ أَنَّهُ يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ الآيَةُ الأُولَى الَّتِي قَالَ فِيهَا ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ فِي الآيَةِ الأُخْرَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ يَعْنِي هِيَ رَغْبَةُ أَحَدِكُمْ لِيَتِيمَتِهِ الَّتِي تَكُونُ فِي حَجْرِهِ، حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ، فَنُهُوا أَنْ يَنْكِحُوا مَا رَغِبُوا فِي مَالِهَا وَجَمَالِهَا مِنْ يَتَامَى النِّسَاءِ إِلاَّ بِالْقِسْطِ مِنْ، أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2581","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2581","x":"Narrated `Urwa from `Aisha:\n\nThe wives of Allah's Messenger (ﷺ) were in two groups. One group consisted of `Aisha, Hafsa, Safiyya and Sauda; and the other group consisted of Um Salama and the other wives of Allah's Messenger (ﷺ). The Muslims knew that Allah's Messenger (ﷺ) loved `Aisha, so if any of them had a gift and wished to give to Allah's Messenger (ﷺ), he would delay it, till Allah's Messenger (ﷺ) had come to `Aisha's home and then he would send his gift to Allah's Messenger (ﷺ) in her home. The group of Um Salama discussed the matter together and decided that Um Salama should request Allah's Messenger (ﷺ) to tell the people to send their gifts to him in whatever wife's house he was. Um Salama told Allah's Messenger (ﷺ) of what they had said, but he did not reply. Then they (those wives) asked Um Salama about it. She said, \"He did not say anything to me.\" They asked her to talk to him again. She talked to him again when she met him on her day, but he gave no reply. When they asked her, she replied that he had given no reply. They said to her, \"Talk to him till he gives you a reply.\" When it was her turn, she talked to him again. He then said to her, \"Do not hurt me regarding Aisha, as the Divine Inspirations do not come to me on any of the beds except that of Aisha.\" On that Um Salama said, \"I repent to Allah for hurting you.\" Then the group of Um Salama called Fatima, the daughter of Allah's Messenger (ﷺ) and sent her to Allah's Messenger (ﷺ) to say to him, \"Your wives request to treat them and the daughter of Abu Bakr on equal terms.\" Then Fatima conveyed the message to him. The Prophet (ﷺ) said, \"O my daughter! Don't you love whom I love?\" She replied in the affirmative and returned and told them of the situation. They requested her to go to him again but she refused. They then sent Zainab bint Jahsh who went to him and used harsh words saying, \"Your wives request you to treat them and the daughter of Ibn Abu Quhafa on equal terms.\" On that she raised her voice and abused `Aisha to her face so much so that Allah's Messenger (ﷺ) looked at `Aisha to see whether she would retort. `Aisha started replying to Zainab till she silenced her. The Prophet (ﷺ) then looked at `Aisha and said, \"She is really the daughter of Abu Bakr.\"","ar":"حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ نِسَاءَ، رَسُولِ اللَّهِ صلى الله عليه وسلم كُنَّ حِزْبَيْنِ فَحِزْبٌ فِيهِ عَائِشَةُ وَحَفْصَةُ وَصَفِيَّةُ وَسَوْدَةُ، وَالْحِزْبُ الآخَرُ أُمُّ سَلَمَةَ وَسَائِرُ نِسَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَكَانَ الْمُسْلِمُونَ قَدْ عَلِمُوا حُبَّ رَسُولِ اللَّهِ صلى الله عليه وسلم عَائِشَةَ، فَإِذَا كَانَتْ عِنْدَ أَحَدِهِمْ هَدِيَّةٌ يُرِيدُ أَنْ يُهْدِيَهَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم أَخَّرَهَا، حَتَّى إِذَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي بَيْتِ عَائِشَةَ بَعَثَ صَاحِبُ الْهَدِيَّةِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فِي بَيْتِ عَائِشَةَ، فَكَلَّمَ حِزْبُ أُمِّ سَلَمَةَ، فَقُلْنَ لَهَا كَلِّمِي رَسُولَ اللَّهِ صلى الله عليه وسلم يُكَلِّمُ النَّاسَ، فَيَقُولُ مَنْ أَرَادَ أَنْ يُهْدِيَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم هَدِيَّةً فَلْيُهْدِهِ إِلَيْهِ حَيْثُ كَانَ مِنْ بُيُوتِ نِسَائِهِ، فَكَلَّمَتْهُ أُمُّ سَلَمَةَ بِمَا قُلْنَ، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا‏.‏ فَقَالَتْ مَا قَالَ لِي شَيْئًا‏.‏ فَقُلْنَ لَهَا فَكَلِّمِيهِ‏.‏ قَالَتْ فَكَلَّمَتْهُ حِينَ دَارَ إِلَيْهَا أَيْضًا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا‏.‏ فَقَالَتْ مَا قَالَ لِي شَيْئًا‏.‏ فَقُلْنَ لَهَا كَلِّمِيهِ حَتَّى يُكَلِّمَكِ‏.‏ فَدَارَ إِلَيْهَا فَكَلَّمَتْهُ‏.‏ فَقَالَ لَهَا ‏\"‏ لاَ تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّ الْوَحْىَ لَمْ يَأْتِنِي، وَأَنَا فِي ثَوْبِ امْرَأَةٍ إِلاَّ عَائِشَةَ ‏\"‏‏.‏ قَالَتْ فَقَالَتْ أَتُوبُ إِلَى اللَّهِ مِنْ أَذَاكَ يَا رَسُولَ اللَّهِ‏.‏ ثُمَّ إِنَّهُنَّ دَعَوْنَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَرْسَلْنَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم تَقُولُ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ أَبِي بَكْرٍ‏.‏ فَكَلَّمَتْهُ‏.‏ فَقَالَ ‏\"‏ يَا بُنَيَّةُ، أَلاَ تُحِبِّينَ مَا أُحِبُّ ‏\"‏‏.‏ قَالَتْ بَلَى‏.‏ فَرَجَعَتْ إِلَيْهِنَّ، فَأَخْبَرَتْهُنَّ‏.‏ فَقُلْنَ ارْجِعِي إِلَيْهِ‏.‏ فَأَبَتْ أَنْ تَرْجِعَ، فَأَرْسَلْنَ زَيْنَبَ بِنْتَ جَحْشٍ، فَأَتَتْهُ فَأَغْلَظَتْ، وَقَالَتْ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ ابْنِ أَبِي قُحَافَةَ‏.‏ فَرَفَعَتْ صَوْتَهَا، حَتَّى تَنَاوَلَتْ عَائِشَةَ‏.‏ وَهْىَ قَاعِدَةٌ، فَسَبَّتْهَا حَتَّى إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَيَنْظُرُ إِلَى عَائِشَةَ هَلْ تَكَلَّمُ قَالَ فَتَكَلَّمَتْ عَائِشَةُ تَرُدُّ عَلَى زَيْنَبَ، حَتَّى أَسْكَتَتْهَا‏.‏ قَالَتْ فَنَظَرَ النَّبِيُّ صلى الله عليه وسلم إِلَى عَائِشَةَ، وَقَالَ ‏\"‏ إِنَّهَا بِنْتُ أَبِي بَكْرٍ ‏\"‏‏.‏ قَالَ الْبُخَارِيُّ الْكَلاَمُ الأَخِيرُ قِصَّةُ فَاطِمَةَ يُذْكَرُ عَنْ هِشَامِ بْنِ عُرْوَةَ عَنْ رَجُلٍ عَنِ الزُّهْرِيِّ عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ‏.‏ وَقَالَ أَبُو مَرْوَانَ عَنْ هِشَامٍ عَنْ عُرْوَةَ كَانَ النَّاسُ يَتَحَرَّوْنَ بِهَدَايَاهُمْ يَوْمَ عَائِشَةَ‏.‏ وَعَنْ هِشَامٍ عَنْ رَجُلٍ مِنْ قُرَيْشٍ، وَرَجُلٍ مِنَ الْمَوَالِي، عَنِ الزُّهْرِيِّ عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ قَالَتْ عَائِشَةُ كُنْتُ عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَاسْتَأْذَنَتْ فَاطِمَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2763","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2763","x":"Narrated Az-Zuhri:\n\n`Urwa bin Az-Zubair said that he asked `Aisha about the meaning of the Qur'anic Verse:-- \"And if you fear that you will not deal fairly with the orphan girls then marry (other) women of your choice.\" (4.2-3) Aisha said, \"It is about a female orphan under the guardianship of her guardian who is inclined towards her because of her beauty and wealth, and likes to marry her with a Mahr less than what is given to women of her standard. So they (i.e. guardians) were forbidden to marry the orphans unless they paid them a full appropriate Mahr (otherwise) they were ordered to marry other women instead of them. Later on the people asked Allah's Messenger (ﷺ) about it. So Allah revealed the following Verse:-- \"They ask your instruction (O Muhammad!) regarding women. Say: Allah instructs you regarding them...\" (4.127) and in this Verse Allah indicated that if the orphan girl was beautiful and wealthy, her guardian would have the desire to marry her without giving her an appropriate Mahr equal to what her peers could get, but if she was undesirable for lack of beauty or wealth, then he would not marry her, but seek to marry some other woman instead of her. So, since he did not marry her when he had no inclination towards her, he had not the right to marry her when he had an interest in her, unless he treated her justly by giving her a full Mahr and securing all her rights.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ كَانَ عُرْوَةُ بْنُ الزُّبَيْرِ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ قَالَتْ عَائِشَةُ ثُمَّ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ قَالَتْ فَبَيَّنَ اللَّهُ فِي هَذِهِ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ جَمَالٍ وَمَالٍ رَغِبُوا فِي نِكَاحِهَا، وَلَمْ يُلْحِقُوهَا بِسُنَّتِهَا بِإِكْمَالِ الصَّدَاقِ، فَإِذَا كَانَتْ مَرْغُوبَةً عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ تَرَكُوهَا وَالْتَمَسُوا غَيْرَهَا مِنَ النِّسَاءِ، قَالَ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا إِلاَّ أَنْ يُقْسِطُوا لَهَا الأَوْفَى مِنَ الصَّدَاقِ وَيُعْطُوهَا حَقَّهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4573","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4573","x":"Narrated Aisha:\n\nThere was an orphan (girl) under the care of a man. He married her and she owned a date palm (garden). He married her just because of that and not because he loved her. So the Divine Verse came regarding his case: \"If you fear that you shall not be able to deal justly with the orphan girls...\" (4.3) The sub-narrator added: I think he (i.e. another sub-narrator) said, \"That orphan girl was his partner in that datepalm (garden) and in his property.\"","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا هِشَامٌ، عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ رَجُلاً، كَانَتْ لَهُ يَتِيمَةٌ فَنَكَحَهَا، وَكَانَ لَهَا عَذْقٌ، وَكَانَ يُمْسِكُهَا عَلَيْهِ، وَلَمْ يَكُنْ لَهَا مِنْ نَفْسِهِ شَىْءٌ فَنَزَلَتْ فِيهِ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏ أَحْسِبُهُ قَالَ كَانَتْ شَرِيكَتَهُ فِي ذَلِكَ الْعَذْقِ وَفِي مَالِهِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4574","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4574","x":"Narrated `Urwa bin Az-Zubair:\n\nThat he asked `Aisha regarding the Statement of Allah: \"If you fear that you shall not be able to deal justly with the orphan girls...\" (4.3) She said, \"O son of my sister! An Orphan girl used to be under the care of a guardian with whom she shared property. Her guardian, being attracted by her wealth and beauty, would intend to marry her without giving her a just Mahr, i.e. the same Mahr as any other person might give her (in case he married her). So such guardians were forbidden to do that unless they did justice to their female wards and gave them the highest Mahr their peers might get. They were ordered (by Allah, to marry women of their choice other than those orphan girls.\" `Aisha added,\" The people asked Allah's Messenger (ﷺ) his instructions after the revelation of this Divine Verse whereupon Allah revealed: \"They ask your instruction regarding women \" (4.127) `Aisha further said, \"And the Statement of Allah: \"And yet whom you desire to marry.\" (4.127) as anyone of you refrains from marrying an orphan girl (under his guardianship) when she is lacking in property and beauty.\" `Aisha added, \"So they were forbidden to marry those orphan girls for whose wealth and beauty they had a desire unless with justice, and that was because they would refrain from marrying them if they were lacking in property and beauty.\"","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحِ بْنِ كَيْسَانَ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِ اللَّهِ، تَعَالَى ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏‏.‏ فَقَالَتْ يَا ابْنَ أُخْتِي، هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، تَشْرَكُهُ فِي مَالِهِ وَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا، فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا، بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا، فَيُعْطِيَهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ، فَنُهُوا عَنْ أَنْ يَنْكِحُوهُنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ، وَيَبْلُغُوا لَهُنَّ أَعْلَى سُنَّتِهِنَّ فِي الصَّدَاقِ، فَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ وَإِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ تَعَالَى فِي آيَةٍ أُخْرَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ رَغْبَةُ أَحَدِكُمْ عَنْ يَتِيمَتِهِ حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ قَالَتْ فَنُهُوا أَنْ يَنْكِحُوا عَنْ مَنْ رَغِبُوا فِي مَالِهِ وَجَمَالِهِ فِي يَتَامَى النِّسَاءِ، إِلاَّ بِالْقِسْطِ، مِنْ أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ إِذَا كُنَّ قَلِيلاَتِ الْمَالِ وَالْجَمَالِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5064","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5064","x":"Narrated 'Urwa:\n\nthat he asked `Aisha about the Statement of Allah: 'If you fear that you shall not be able to deal justly with the orphan girls, then marry (other) women of your choice, two or three or four; but if you fear that you shall not be able to deal justly (with them), then only one, or (the captives) that your right hands possess. That will be nearer to prevent you from doing injustice.' (4.3) `Aisha said, \"O my nephew! (This Verse has been revealed in connection with) an orphan girl under the guardianship of her guardian who is attracted by her wealth and beauty and intends to marry her with a Mahr less than what other women of her standard deserve. So they (such guardians) have been forbidden to marry them unless they do justice to them and give them their full Mahr, and they are ordered to marry other women instead of them.\"","ar":"حَدَّثَنَا عَلِيٌّ، سَمِعَ حَسَّانَ بْنَ إِبْرَاهِيمَ، عَنْ يُونُسَ بْنِ يَزِيدَ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِهِ تَعَالَى ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاَثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَنْ لاَ تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ ذَلِكَ أَدْنَى أَنْ لاَ تَعُولُوا‏}‏‏.‏ قَالَتْ يَا ابْنَ أُخْتِي، الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي مَالِهَا وَجَمَالِهَا، يُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ صَدَاقِهَا، فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فَيُكْمِلُوا الصَّدَاقَ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5092","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5092","x":"Narrated 'Urwa:\n\nthat he asked `Aisha regarding the Verse: 'If you fear that you shall not be able to deal justly with the orphans (4.3) She said, \"O my nephew! This Verse refers to the orphan girl who is under the guardianship of her guardian who likes her beauty and wealth and wishes to (marry her and) curtails her Mahr. Such guardians have been forbidden to marry them unless they do justice by giving them their full Mahr, and they have been ordered to marry other than them. The people asked for the verdict of Allah's Messenger (ﷺ) after that, so Allah revealed: 'They ask your instruction concerning the women... whom you desire to marry.' (4.127) So Allah revealed to them that if the orphan girl had beauty and wealth, they desired to marry her and for her family status. They can only marry them if they give them their full Mahr. And if they had no desire to marry them because of their lack of wealth and beauty, they would leave them and marry other women. So, as they used to leave them, when they had no interest, in them, they were forbidden to marry them when they had such interest, unless they treated them justly and gave them their full Mahr Apostle said, 'If at all there is evil omen, it is in the horse, the woman and the house.\" a lady is to be warded off. And the Statement of Allah: 'Truly, among your wives and your children, there are enemies for you (i.e may stop you from the obedience of Allah)' (64.14)","ar":"حَدَّثَنِي يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُرْوَةُ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏ قَالَتْ يَا ابْنَ أُخْتِي هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَنْتَقِصَ صَدَاقَهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ إِلاَّ أَنْ يُقْسِطُوا فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ، قَالَتْ وَاسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ ذَلِكَ، فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ فَأَنْزَلَ اللَّهُ لَهُمْ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ جَمَالٍ وَمَالٍ رَغِبُوا فِي نِكَاحِهَا وَنَسَبِهَا فِي إِكْمَالِ الصَّدَاقِ، وَإِذَا كَانَتْ مَرْغُوبَةً عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ تَرَكُوهَا وَأَخَذُوا غَيْرَهَا مِنَ النِّسَاءِ، قَالَتْ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا إِلاَّ أَنْ يُقْسِطُوا لَهَا وَيُعْطُوهَا حَقَّهَا الأَوْفَى فِي الصَّدَاقِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5098","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5098","x":"Narrated Aisha\":\n\n(regarding) the Verse: 'And if you fear that you shall not be able to deal justly with the orphans...' (4.3) It is about the orphan girl who is in the custody of a man who is her guardian, and he intends to marry her because of her wealth, but he treats her badly and does not manage her property fairly and honestly. Such a man should marry women of his liking other than her, two or three or four. 'Prohibited to you (for marriage) are:...your foster-mothers (who suckled you).' (4.23) Marriage is prohibited between persons having a foster suckling relationship corresponding to a blood relationship which renders marriage unlawful.","ar":"حَدَّثَنَا مُحَمَّدٌ، أَخْبَرَنَا عَبْدَةُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ، تُقْسِطُوا فِي الْيَتَامَى‏}‏‏.‏ قَالَتِ الْيَتِيمَةُ تَكُونُ عِنْدَ الرَّجُلِ وَهْوَ وَلِيُّهَا، فَيَتَزَوَّجُهَا عَلَى مَالِهَا، وَيُسِيءُ صُحْبَتَهَا، وَلاَ يَعْدِلُ فِي مَالِهَا، فَلْيَتَزَوَّجْ مَا طَابَ لَهُ مِنَ النِّسَاءِ سِوَاهَا مَثْنَى وَثُلاَثَ وَرُبَاعَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5139","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5139","x":"Narrated `Abdur-Rahman bin Yazid and Majammi bin Yazid:\n\nThe same,Hadith above: A man called Khidam married a daughter of his (to somebody) against her consent. 'If you fear that you shall not be able to deal justly with the orphan girls then marry (other) women of your choice.' (4.3) And if somebody says to the guardian (of a woman), \"Marry me to soand- so,\" and the guardian remained silent or said to him, \"What have you got?\" And the other said, \"I have so much and so much (Mahr),\" or kept quiet, and then the guardian said, \"I have married her to you,\" then the marriage is valid (legal). This narration was told by Sahl on the authority of the Prophet.","ar":"حَدَّثَنَا إِسْحَاقُ، أَخْبَرَنَا يَزِيدُ، أَخْبَرَنَا يَحْيَى، أَنَّ الْقَاسِمَ بْنَ مُحَمَّدٍ، حَدَّثَهُ أَنَّ عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ وَمُجَمِّعَ بْنَ يَزِيدَ حَدَّثَاهُ أَنَّ رَجُلاً يُدْعَى خِذَامًا أَنْكَحَ ابْنَةً لَهُ‏.‏ نَحْوَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5140","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5140","x":"Narrated 'Urwa bin Az-Zubair:\n\nthat he asked `Aisha, saying to her, \"O Mother! (In what connection was this Verse revealed): 'If you fear that you shall not be able to deal justly with orphan girls (to the end of the verse) that your right hands possess?\" (4.3) Aisha said, \"O my nephew! It was about the female orphan under the protection of her guardian who was interested in her beauty and wealth and wanted to marry her with a little or reduced Mahr. So such guardians were forbidden to marry female orphans unless they deal with them justly and give their full Mahr; and they were ordered to marry women other than them.\"`Aisha added, \"(Later) the people asked Allah's Messenger (ﷺ), for instructions, and then Allah revealed: 'They ask your instruction concerning the women... And yet whom you desire to marry.' (4.127) So Allah revealed to them in this Verse that-if a female orphan had wealth and beauty, they desired to marry her and were interested in her noble descent and the reduction of her Mahr; but if she was not desired by them because of her lack in fortune and beauty they left her and married some other woman. So, as they used to leave her when they had no interest in her, they had no right to marry her if they had the desire to do so, unless they deal justly with her and gave her a full amount of Mahr.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ،‏.‏ وَقَالَ اللَّيْثُ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ قَالَ لَهَا يَا أُمَّتَاهْ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏ إِلَى ‏{‏مَا مَلَكَتْ أَيْمَانُكُمْ‏}‏ قَالَتْ عَائِشَةُ يَا ابْنَ أُخْتِي هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَنْتَقِصَ مِنْ صَدَاقِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ‏.‏ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ، قَالَتْ عَائِشَةُ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ ذَلِكَ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى ‏{‏وَتَرْغَبُونَ‏}‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ لَهُمْ فِي هَذِهِ الآيَةِ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ مَالٍ وَجَمَالٍ، رَغِبُوا فِي نِكَاحِهَا وَنَسَبِهَا وَالصَّدَاقِ، وَإِذَا كَانَتْ مَرْغُوبًا عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ، تَرَكُوهَا وَأَخَذُوا غَيْرَهَا مِنَ النِّسَاءِ ـ قَالَتْ ـ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا، فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا، إِلاَّ أَنْ يُقْسِطُوا لَهَا وَيُعْطُوهَا حَقَّهَا الأَوْفَى مِنَ الصَّدَاقِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6965","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6965","x":"Narrated `Urwa:\n\nThat he asked `Aisha regarding the Verse: 'If you fear that you shall not be able to deal justly with the orphan girls, marry (other) women of your choice.' (4.3) `Aisha said, \"It is about an orphan girl under the custody of her guardian who being attracted by her wealth and beauty wants to marry her with Mahr less than other women of her status. So such guardians were forbidden to marry them unless they treat them justly by giving them their full Mahr. Then the people sought the verdict of Allah's Apostle for such cases, whereupon Allah revealed: 'They ask your instruction concerning women..' (4.127) (The sub-narrator then mentioned the Hadith.)","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، حَدَّثَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ كَانَ عُرْوَةُ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏‏.‏ قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي مَالِهَا وَجَمَالِهَا، فَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، ثُمَّ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدُ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ فَذَكَرَ الْحَدِيثَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3018a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3018a","x":"'Urwa b. Zubair reported that he asked 'A'isha about the words of Allah:\n\n\" If you fear that you will not be able to maintain equity amongst the orphan girls, then marry (those) you like from amongst the women two, three or four.\" She said: O, the son of my sister, the orphan girl is one who is under the patronage of her guardian and she shares with him in his property and her property and beauty fascinate him and her guardian makes up his mind to marry her without giving her due share of the wedding money and is not prepared (to pay so much amount) which anyone else is prepared to pay and so Allah has forbidden to marry these girls but in case when equity is observed as regards the wedding money and they are prepared to pay them the full amount of the wedding money and Allah commanded to marry other women besides them according to the liking of their heart. 'Urwa reported that 'A'isha said that people began to seek verdict from Allah's Messenger (ﷺ) after the revelation of this verse about them (orphan girls) and Allah, the Exalted and Glorious, revealed this verse:\" They asked thee verdict about women; say: Allah gives verdict to you in regard to them and what is recited to you in the Book about orphan woman, whom you give not what is ordained for them while you like to marry them\" (iv. 126). She said: The wording of Allah\" what is recited to you\" in the Book means the first verse, i. e.\" if you fear that you may not be able to observe equity in case of an orphan woman, marry what you like in case of woman\" (iv. 3). 'A'isha said: (And as for this verse [iv. 126], i. e. and you intend\" to marry one of them from amongst the orphan girls\" it pertains to one who is in charge (of orphans) having small amount of wealth and less beauty and they have been forbidden that they should marry what they like of her wealth and beauty out of the orphan girls, but with equity, because of their disliking for them.","ar":"حَدَّثَنِي أَبُو الطَّاهِرِ، أَحْمَدُ بْنُ عَمْرِو بْنِ سَرْحٍ وَحَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ - قَالَ أَبُو الطَّاهِرِ حَدَّثَنَا وَقَالَ، حَرْمَلَةُ أَخْبَرَنَا - ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِ اللَّهِ، ‏{‏ وَإِنْ خِفْتُمْ أَنْ لاَ، تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاَثَ وَرُبَاعَ‏}‏ قَالَتْ يَا ابْنَ أُخْتِي هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا تُشَارِكُهُ فِي مَالِهِ فَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا فَيُعْطِيَهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ وَيَبْلُغُوا بِهِنَّ أَعْلَى سُنَّتِهِنَّ مِنَ الصَّدَاقِ وَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ ثُمَّ إِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فِيهِنَّ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ فِي يَتَامَى النِّسَاءِ اللاَّتِي لاَ تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ ‏.‏ قَالَتْ وَالَّذِي ذَكَرَ اللَّهُ تَعَالَى أَنَّهُ يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ الآيَةُ الأُولَى الَّتِي قَالَ اللَّهُ فِيهَا ‏{‏ وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ ‏.‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ فِي الآيَةِ الأُخْرَى ‏{‏ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ رَغْبَةَ أَحَدِكُمْ عَنِ الْيَتِيمَةِ الَّتِي تَكُونُ فِي حَجْرِهِ حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ فَنُهُوا أَنْ يَنْكِحُوا مَا رَغِبُوا فِي مَالِهَا وَجَمَالِهَا مِنْ يَتَامَى النِّسَاءِ إِلاَّ بِالْقِسْطِ مِنْ أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ ‏.‏","v":[]}],"6":[{"c":"Sahih Bukhari","r":"Hadith 2212","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2212","x":"Narrated Hisham bin `Urwa from his father:\n\nwho heard Aisha saying, \"The Holy Verse; 'Whoever amongst the guardians is rich, he should take no wages (from the property of the orphans) but If he is poor, let him have for himself what is just and reasonable (according to his labors)' (4.6) was revealed concerning the guardian of the orphans who looks after them and manages favorably their financial affairs; If the guardian Is poor, he could have from It what Is just and reasonable, (according to his labors).","ar":"حَدَّثَنِي إِسْحَاقُ، حَدَّثَنَا ابْنُ نُمَيْرٍ، أَخْبَرَنَا هِشَامٌ، وَحَدَّثَنِي مُحَمَّدٌ، قَالَ سَمِعْتُ عُثْمَانَ بْنَ فَرْقَدٍ، قَالَ سَمِعْتُ هِشَامَ بْنَ عُرْوَةَ، يُحَدِّثُ عَنْ أَبِيهِ، أَنَّهُ سَمِعَ عَائِشَةَ ـ رضى الله عنها ـ تَقُولُ ‏{‏وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ‏}‏ أُنْزِلَتْ فِي وَالِي الْيَتِيمِ الَّذِي يُقِيمُ عَلَيْهِ، وَيُصْلِحُ فِي مَالِهِ، إِنْ كَانَ فَقِيرًا أَكَلَ مِنْهُ بِالْمَعْرُوفِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2765","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2765","x":"Narrated `Aisha:\n\nThe following Verse:-- \"If a guardian is well-off, let him claim no remuneration (i.e. wages), but if he is poor, let him have for himself what is just and reasonable.\" (4.6) was revealed in connection with the guardian of an orphan, and it means that if he is poor he can have for himself (from the orphan's wealth) what is just and reasonable according to the orphan's share of the inheritance.","ar":"حَدَّثَنَا عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ‏}‏‏.‏ قَالَتْ أُنْزِلَتْ فِي وَالِي الْيَتِيمِ أَنْ يُصِيبَ مِنْ مَالِهِ إِذَا كَانَ مُحْتَاجًا بِقَدْرِ مَالِهِ بِالْمَعْرُوفِ‏.‏","v":[]}],"10":[{"c":"Sunan Abu Dawud","r":"Hadith 2877","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2877","x":"Narrated Buraidah:\n\nA woman came to the Messenger of Allah (ﷺ) and said: I donated my slave-girl to my mother, but she died and left the slave-girl. He said: Your reward became due, and she came back to you in inheritance. She said: She died while a month's fasting was due from her. Would it be sufficient or be taken as completed if I fast on her behalf ? He said: Yes. She said: She also did not perform Hajj. Would it be sufficient or be taken completed if I perform (Hajj) on her behalf ? He said: Yes.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَطَاءٍ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، بُرَيْدَةَ أَنَّ امْرَأَةً، أَتَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَتْ كُنْتُ تَصَدَّقْتُ عَلَى أُمِّي بِوَلِيدَةٍ وَإِنَّهَا مَاتَتْ وَتَرَكَتْ تِلْكَ الْوَلِيدَةَ ‏.‏ قَالَ ‏\"‏ قَدْ وَجَبَ أَجْرُكِ وَرَجَعَتْ إِلَيْكِ فِي الْمِيرَاثِ ‏\"‏ ‏.‏ قَالَتْ وَإِنَّهَا مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ أَفَيُجْزِئُ - أَوْ يَقْضِي - عَنْهَا أَنْ أَصُومَ عَنْهَا قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قَالَتْ وَإِنَّهَا لَمْ تَحُجَّ أَفَيُجْزِئُ - أَوْ يَقْضِي - عَنْهَا أَنْ أَحُجَّ عَنْهَا قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 40, Hadith 1502","u":"https://quranx.com/Hadith/Malik/In-Book/Book-40/Hadith-1502","x":"Malik related to me that he heard that Umar ibn Abd al-Aziz gave a judgement about the mudabbar who did an injury. He said, \"The master must surrender what he owns of him to the injured person. He is made to serve the injured person and recompense (in the form of service) is taken from him as the blood-money of the injury. If he completes that before his master dies, he reverts to his master.\" Malik said, \"The generally agreed on way of doing things in our community about a mudabbar who does an injury and then his master dies and the master has no property except him is that the third (allowed to be bequeathed) is freed, and then the blood-money for the in jury is divided into thirds. A third of the blood-money is against the third of him which was set free, and two-thirds are against the two-thirds which the heirs have. If they wish, they surrender what they have of him to the party with the injury, and if they wish, they give the injured person two-thirds of the blood-money and keep their portion of the slave. That is because that injury is a criminal action by the slave and it is not a debt against the master by which whatever setting free and tadbir the master had done would be abrogated. If there were a debt to people held against the master of the slave, as well as the criminal action of the slave, part of the mudabbar would be sold in proportion to the blood-money of the injury and according to the debt. Then one would begin with the blood-money which was for the criminal action of the slave and it would be paid from the price of the slave. Then the debt of his master would be paid, and then one would look at what remained after that of the slave. His third would b be set free, and two-thirds of him would belong to the heirs. That is because the criminal action of the slave is more important than the debt of his master. That is because, if the man dies and leaves a mudabbar slave whose value is one hundred and fifty dinars, and the slave strikes a free man on the head with a blow that lays open the skull, and the blood-money is fifty dinars, and the master of the slave has a debt of fifty dinars, one begins with the fifty dinars which are the blood-money of the head wound, and it is paid from the price of the slave. Then the debt of the master is paid. Then one looks at what remains of the slave, and a third of him is set free and two-thirds of him remain for the heirs. The blood-money is more pressing against his person than the debt of his master. The debt of his master is more pressing than the tadbir which is a bequest from the third of the property of the deceased. None of the tadbir is permitted while the master of the mudabbar has a debt which is not paid. It is a bequest. That is because Allah, the Blessed, the Exalted, said, 'After any bequest that is made or any debt.' \" (Sura 4 ayat 10) Malik said, \"If there is enough in the third property that the deceased can bequeath to free all the mudabbar, he is freed and the blood-money due from his criminal action is held as a debt against him which follows him after he is set free even if that blood-money is the full blood-money. It is not a debt on the master.\" Malik spoke about a mudabbar who injured a man and his master surrendered him to the injured party, and then the master died and had a debt and did not leave any property other than the mudabbar, and the heirs said, \"We surrender the mudabbar to the party,\" whilst the creditor said, \"My debt exceeds that.\" Malik said that if the creditor's debt did exceed that at all, he was more entitled to it and it was taken from the one who owed the debt, according to what the creditor was owed in excess of the blood-money of the injury. If his debt did not exceed it at all, he did not take the slave. Malik spoke about a mudabbar who did an injury and had property, and his master refused to ransom him. He said, \"The injured party takes the property of the mudabbar for the blood-money of his injury. If there is enough to pay it, the injured party is paid in full for the blood-money of his injury and the mudabbar is returned to his master. If there is not enough to pay it, he takes it from the blood-money and uses the mudabbar for what remains of the blood-money.\"","ar":"حَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، قَضَى فِي الْمُدَبَّرِ إِذَا جَرَحَ أَنَّ لِسَيِّدِهِ أَنْ يُسَلِّمَ مَا يَمْلِكُ مِنْهُ إِلَى الْمَجْرُوحِ فَيَخْتَدِمُهُ الْمَجْرُوحُ وَيُقَاصُّهُ بِجِرَاحِهِ مِنْ دِيَةِ جَرْحِهِ فَإِنْ أَدَّى قَبْلَ أَنْ يَهْلِكَ سَيِّدُهُ رَجَعَ إِلَى سَيِّدِهِ ‏.‏ قَالَ مَالِكٌ وَالأَمْرُ عِنْدَنَا فِي الْمُدَبَّرِ إِذَا جَرَحَ ثُمَّ هَلَكَ سَيِّدُهُ وَلَيْسَ لَهُ مَالٌ غَيْرُهُ أَنَّهُ يُعْتَقُ ثُلُثُهُ ثُمَّ يُقْسَمُ عَقْلُ الْجَرْحِ أَثْلاَثًا فَيَكُونُ ثُلُثُ الْعَقْلِ عَلَى الثُّلُثِ الَّذِي عَتَقَ مِنْهُ وَيَكُونُ ثُلُثَاهُ عَلَى الثُّلُثَيْنِ اللَّذَيْنِ بِأَيْدِي الْوَرَثَةِ إِنْ شَاءُوا أَسْلَمُوا الَّذِي لَهُمْ مِنْهُ إِلَى صَاحِبِ الْجَرْحِ وَإِنْ شَاءُوا أَعْطَوْهُ ثُلُثَىِ الْعَقْلِ وَأَمْسَكُوا نَصِيبَهُمْ مِنَ الْعَبْدِ وَذَلِكَ أَنَّ عَقْلَ ذَلِكَ الْجَرْحِ إِنَّمَا كَانَتْ جِنَايَتُهُ مِنَ الْعَبْدِ وَلَمْ تَكُنْ دَيْنًا عَلَى السَّيِّدِ فَلَمْ يَكُنْ ذَلِكَ الَّذِي أَحْدَثَ الْعَبْدُ بِالَّذِي يُبْطِلُ مَا صَنَعَ السَّيِّدُ مِنْ عِتْقِهِ وَتَدْبِيرِهِ فَإِنْ كَانَ عَلَى سَيِّدِ الْعَبْدِ دَيْنٌ لِلنَّاسِ مَعَ جِنَايَةِ الْعَبْدِ بِيعَ مِنَ الْمُدَبَّرِ بِقَدْرِ عَقْلِ الْجَرْحِ وَقَدْرِ الدَّيْنِ ثُمَّ يُبَدَّأُ بِالْعَقْلِ الَّذِي كَانَ فِي جِنَايَةِ الْعَبْدِ فَيُقْضَى مِنْ ثَمَنِ الْعَبْدِ ثُمَّ يُقْضَى دَيْنُ سَيِّدِهِ ثُمَّ يُنْظَرُ إِلَى مَا بَقِيَ بَعْدَ ذَلِكَ مِنَ الْعَبْدِ فَيَعْتِقُ ثُلُثُهُ وَيَبْقَى ثُلُثَاهُ لِلْوَرَثَةِ وَذَلِكَ أَنَّ جِنَايَةَ الْعَبْدِ هِيَ أَوْلَى مِنْ دَيْنِ سَيِّدِهِ وَذَلِكَ أَنَّ الرَّجُلَ إِذَا هَلَكَ وَتَرَكَ عَبْدًا مُدَبَّرًا قِيمَتُهُ خَمْسُونَ وَمِائَةُ دِينَارٍ وَكَانَ الْعَبْدُ قَدْ شَجَّ رَجُلاً حُرًّا مُوضِحَةً عَقْلُهَا خَمْسُونَ دِينَارًا وَكَانَ عَلَى سَيِّدِ الْعَبْدِ مِنَ الدَّيْنِ خَمْسُونَ دِينَارًا ‏.‏ قَالَ مَالِكٌ فَإِنَّهُ يُبْدَأُ بِالْخَمْسِينَ دِينَارًا الَّتِي فِي عَقْلِ الشَّجَّةِ فَتُقْضَى مِنْ ثَمَنِ الْعَبْدِ ثُمَّ يُقْضَى دَيْنُ سَيِّدِهِ ثُمَّ يُنْظَرُ إِلَى مَا بَقِيَ مِنَ الْعَبْدِ فَيَعْتِقُ ثُلُثُهُ وَيَبْقَى ثُلُثَاهُ لِلْوَرَثَةِ فَالْعَقْلُ أَوْجَبُ فِي رَقَبَتِهِ مِنْ دَيْنِ سَيِّدِهِ وَدَيْنُ سَيِّدِهِ أَوْجَبُ مِنَ التَّدْبِيرِ الَّذِي إِنَّمَا هُوَ وَصِيَّةٌ فِي ثُلُثِ مَالِ الْمَيِّتِ فَلاَ يَنْبَغِي أَنْ يَجُوزَ شَىْءٌ مِنَ التَّدْبِيرِ وَعَلَى سَيِّدِ الْمُدَبَّرِ دَيْنٌ لَمْ يُقْضَ وَإِنَّمَا هُوَ وَصِيَّةٌ وَذَلِكَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ ‏{‏مِنْ بَعْدِ وَصِيَّةٍ يُوصَى بِهَا أَوْ دَيْنٍ‏}‏ ‏.‏ قَالَ مَالِكٌ فَإِنْ كَانَ فِي ثُلُثِ الْمَيِّتِ مَا يَعْتِقُ فِيهِ الْمُدَبَّرُ كُلُّهُ عَتَقَ وَكَانَ عَقْلُ جِنَايَتِهِ دَيْنًا عَلَيْهِ يُتَّبَعُ بِهِ بَعْدَ عِتْقِهِ وَإِنْ كَانَ ذَلِكَ الْعَقْلُ الدِّيَةَ كَامِلَةً وَذَلِكَ إِذَا لَمْ يَكُنْ عَلَى سَيِّدِهِ دَيْنٌ ‏.‏ وَقَالَ مَالِكٌ فِي الْمُدَبَّرِ إِذَا جَرَحَ رَجُلاً فَأَسْلَمَهُ سَيِّدُهُ إِلَى الْمَجْرُوحِ ثُمَّ هَلَكَ سَيِّدُهُ وَعَلَيْهِ دَيْنٌ وَلَمْ يَتْرُكْ مَالاً غَيْرَهُ فَقَالَ الْوَرَثَةُ نَحْنُ نُسَلِّمُهُ إِلَى صَاحِبِ الْجُرْحِ ‏.‏ وَقَالَ صَاحِبُ الدَّيْنِ أَنَا أَزِيدُ عَلَى ذَلِكَ إِنَّهُ إِذَا زَادَ الْغَرِيمُ شَيْئًا فَهُوَ أَوْلَى بِهِ وَيُحَطُّ عَنِ الَّذِي عَلَيْهِ الدَّيْنُ قَدْرُ مَا زَادَ الْغَرِيمُ عَلَى دِيَةِ الْجَرْحِ فَإِنْ لَمْ يَزِدْ شَيْئًا لَمْ يَأْخُذِ الْعَبْدَ ‏.‏ وَقَالَ مَالِكٌ فِي الْمُدَبَّرِ إِذَا جَرَحَ وَلَهُ مَالٌ فَأَبَى سَيِّدُهُ أَنْ يَفْتَدِيَهُ فَإِنَّ الْمَجْرُوحَ يَأْخُذُ مَالَ الْمُدَبَّرِ فِي دِيَةِ جُرْحِهِ فَإِنْ كَانَ فِيهِ وَفَاءٌ اسْتَوْفَى الْمَجْرُوحُ دِيَةَ جُرْحِهِ وَرَدَّ الْمُدَبَّرَ إِلَى سَيِّدِهِ وَإِنْ لَمْ يَكُنْ فِيهِ وَفَاءٌ اقْتَضَاهُ مِنْ دِيَةِ جُرْحِهِ وَاسْتَعْمَلَ الْمُدَبَّرَ بِمَا بَقِيَ لَهُ مِنْ دِيَةِ جُرْحِهِ ‏.‏","v":[]}],"11":[{"c":"Sunan Abu Dawud","r":"Hadith 2875","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2875","x":"'Umair, A Companion of the Prophet (ﷺ) said:\n\nA man asked him (the Prophet): Messenger of Allah, what are the grave sins? He replied: They are nine. He then mentioned the tradition to the same effect. This version adds: \"And disobedience to the Muslim parents, and to violate the sacred House, your qiblah (direction of prayer), in your life and after death.","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ يَعْقُوبَ الْجُوزَجَانِيُّ، حَدَّثَنَا مُعَاذُ بْنُ هَانِئٍ، حَدَّثَنَا حَرْبُ بْنُ شَدَّادٍ، حَدَّثَنَا يَحْيَى بْنُ أَبِي كَثِيرٍ، عَنْ عَبْدِ الْحَمِيدِ بْنِ سِنَانٍ، عَنْ عُبَيْدِ بْنِ عُمَيْرٍ، عَنْ أَبِيهِ، أَنَّهُ حَدَّثَهُ - وَكَانَتْ، لَهُ صُحْبَةٌ - أَنَّ رَجُلاً، سَأَلَهُ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْكَبَائِرُ فَقَالَ ‏\"‏ هُنَّ تِسْعٌ ‏\"‏ ‏.‏ فَذَكَرَ مَعْنَاهُ زَادَ ‏\"‏ وَعُقُوقُ الْوَالِدَيْنِ الْمُسْلِمَيْنِ وَاسْتِحْلاَلُ الْبَيْتِ الْحَرَامِ قِبْلَتِكُمْ أَحْيَاءً وَأَمْوَاتًا ‏\"‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2897","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2897","x":"Al-Hasan reported that Umar asked:\n\nWhich of your knows what share the Messenger of Allah (ﷺ) had given to the grandfather from the estate? Ma'qil ibn Yasar said: The Messenger of Allah (ﷺ) gave him a sixth. He asked: Along with whom? He replied: I do not know. He said: You do not know; what is the use then?","ar":"حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، عَنْ خَالِدٍ، عَنْ يُونُسَ، عَنِ الْحَسَنِ، أَنَّ عُمَرَ، قَالَ أَيُّكُمْ يَعْلَمُ مَا وَرَّثَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْجَدَّ فَقَالَ مَعْقِلُ بْنُ يَسَارٍ أَنَا وَرَّثَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم السُّدُسَ ‏.‏ قَالَ مَعَ مَنْ قَالَ لاَ أَدْرِي ‏.‏ قَالَ لاَ دَرَيْتَ فَمَا تُغْنِي إِذًا ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2747","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2747","x":"Narrated Ibn `Abbas:\n\nThe custom (in old days) was that the property of the deceased would be inherited by his offspring; as for the parents (of the deceased), they would inherit by the will of the deceased. Then Allah cancelled from that custom whatever He wished and fixed for the male double the amount inherited by the female, and for each parent a sixth (of the whole legacy) and for the wife an eighth or a fourth and for the husband a half or a fourth.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، عَنْ وَرْقَاءَ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَ الْمَالُ لِلْوَلَدِ، وَكَانَتِ الْوَصِيَّةُ لِلْوَالِدَيْنِ، فَنَسَخَ اللَّهُ مِنْ ذَلِكَ مَا أَحَبَّ، فَجَعَلَ لِلذَّكَرِ مِثْلَ حَظِّ الأُنْثَيَيْنِ، وَجَعَلَ لِلأَبَوَيْنِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسَ، وَجَعَلَ لِلْمَرْأَةِ الثُّمُنَ وَالرُّبْعَ، وَلِلزَّوْجِ الشَّطْرَ وَالرُّبُعَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4577","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4577","x":"Narrated Jabir:\n\nThe Prophet (ﷺ) and Abu Bakr came on foot to pay me a visit (during my illness) at Banu Salama's (dwellings). The Prophet (ﷺ) found me unconscious, so he asked for water and performed the ablution from it and sprinkled some water over it. I came to my senses and said, \"O Allah's Messenger (ﷺ)! What do you order me to do as regards my wealth?\" So there was revealed:-- \"Allah commands you as regards your children's (inheritance):\" (4.11)","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، حَدَّثَنَا هِشَامٌ، أَنَّ ابْنَ جُرَيْجٍ، أَخْبَرَهُمْ قَالَ أَخْبَرَنِي ابْنُ مُنْكَدِرٍ، عَنْ جَابِرٍ ـ رضى الله عنه ـ قَالَ عَادَنِي النَّبِيُّ صلى الله عليه وسلم وَأَبُو بَكْرٍ فِي بَنِي سَلِمَةَ مَاشِيَيْنِ فَوَجَدَنِي النَّبِيُّ صلى الله عليه وسلم لاَ أَعْقِلُ، فَدَعَا بِمَاءٍ فَتَوَضَّأَ مِنْهُ، ثُمَّ رَشَّ عَلَىَّ، فَأَفَقْتُ فَقُلْتُ مَا تَأْمُرُنِي أَنْ أَصْنَعَ فِي مَالِي يَا رَسُولَ اللَّهِ فَنَزَلَتْ ‏{‏يُوصِيكُمُ اللَّهُ فِي أَوْلاَدِكُمْ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 174b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-174b","x":"Al-Shaibani narrated on the authority of Zirr who narrated it on this authority of Abdullah that the (words of Allah):\n\n\" The heart belied not what he saw\" (al Qur'an, Iiii. 11) imply that he saw Gabriel (peace be upon him) and he had six hundred wings.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنِ الشَّيْبَانِيِّ، عَنْ زِرٍّ، عَنْ عَبْدِ اللَّهِ، قَالَ ‏{‏ مَا كَذَبَ الْفُؤَادُ مَا رَأَى‏}‏ قَالَ رَأَى جِبْرِيلَ - عَلَيْهِ السَّلاَمُ - لَهُ سِتُّمِائَةِ جَنَاحٍ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 176b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-176b","x":"It is narrated on the authority of Ibn Abbas that the words:\n\n\" The heart belied not what he saw\" (al-Qur'an, Iiii. 11) and\" Certainly he saw Him in another descent\" (al-Qur'an, Iiii. 13) imply that he saw him twice with his heart.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو سَعِيدٍ الأَشَجُّ جَمِيعًا عَنْ وَكِيعٍ، - قَالَ الأَشَجُّ حَدَّثَنَا وَكِيعٌ، - حَدَّثَنَا الأَعْمَشُ، عَنْ زِيَادِ بْنِ الْحُصَيْنِ أَبِي جَهْمَةَ، عَنْ أَبِي الْعَالِيَةِ، عَنِ ابْنِ عَبَّاسٍ، قَالَ ‏{‏ مَا كَذَبَ الْفُؤَادُ مَا رَأَى‏}‏ ‏{‏ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى‏}‏ قَالَ رَآهُ بِفُؤَادِهِ مَرَّتَيْنِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3015","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3015","x":"Narrated Jabir bin 'Abdullah:\n\n\"I was ill, so the Messenger of Allah (ﷺ) came to visit me, and I was unconscious. When I awoke, I said: 'How do you order me regarding my wealth?' He did not answer me until Allah revealed: Allah commands you regarding your children's (inheritance): to the male, a portion equal to that of two females (4:11).\" Jãbir bin 'Abdulläh narrated from the Prophet similarly. And in the narration of Al-Fadl bin As-Sabbäh (a narrator in the chain) there is more than this stated.","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا يَحْيَى بْنُ آدَمَ، حَدَّثَنَا ابْنُ عُيَيْنَةَ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، قَالَ سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي وَقَدْ أُغْمِيَ عَلَىَّ فَلَمَّا أَفَقْتُ قُلْتُ كَيْفَ أَقْضِي فِي مَالِي فَسَكَتَ عَنِّي حَتَّى نَزَلَتْ ‏:‏ ‏(‏ يُوصِيكُمُ اللَّهُ فِي أَوْلاَدِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنْثَيَيْنِ ‏)‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَى غَيْرُ وَاحِدٍ عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏.‏ حَدَّثَنَا الْفَضْلُ بْنُ الصَّبَّاحِ الْبَغْدَادِيُّ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ الْمُنْكَدِرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ وَفِي حَدِيثِ الْفَضْلِ بْنِ الصَّبَّاحِ كَلاَمٌ أَكْثَرُ مِنْ هَذَا ‏.‏","v":[]}],"12":[{"c":"Sahih Bukhari","r":"Hadith 2747","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2747","x":"Narrated Ibn `Abbas:\n\nThe custom (in old days) was that the property of the deceased would be inherited by his offspring; as for the parents (of the deceased), they would inherit by the will of the deceased. Then Allah cancelled from that custom whatever He wished and fixed for the male double the amount inherited by the female, and for each parent a sixth (of the whole legacy) and for the wife an eighth or a fourth and for the husband a half or a fourth.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، عَنْ وَرْقَاءَ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَ الْمَالُ لِلْوَلَدِ، وَكَانَتِ الْوَصِيَّةُ لِلْوَالِدَيْنِ، فَنَسَخَ اللَّهُ مِنْ ذَلِكَ مَا أَحَبَّ، فَجَعَلَ لِلذَّكَرِ مِثْلَ حَظِّ الأُنْثَيَيْنِ، وَجَعَلَ لِلأَبَوَيْنِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسَ، وَجَعَلَ لِلْمَرْأَةِ الثُّمُنَ وَالرُّبْعَ، وَلِلزَّوْجِ الشَّطْرَ وَالرُّبُعَ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 23, Hadith 2728","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-23/Hadith-2728","x":"It was narrated from Muhammad bin Munkadir that he heard Jabir bin ‘Abdullah say:\n\n\"I fell sick and the Messenger of Allah (ﷺ) came to visit me, he and Abu Bakr with him, and they came walking. I had lost consciousness, so the Messenger of Allah (ﷺ) performed ablution and poured some of the water of his ablution over me. I said: ‘O Messenger of Allah, what should I do? How should I decide about my wealth?’ Until the Verse of inheritance was revealed at the end of An-Nisa’: \"If the man or woman whose inheritance is in question has left neither ascendants or descendents.\" [4:12] And: \"They ask you for a legal verdict. Say: ‘Allah directs (thus) about those who leave neither descendants nor ascendants as heirs.’\" [4:176]","ar":"حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا سُفْيَانُ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي هُوَ وَأَبُو بَكْرٍ مَعَهُ وَهُمَا مَاشِيَانِ وَقَدْ أُغْمِيَ عَلَىَّ فَتَوَضَّأَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَصَبَّ عَلَىَّ مِنْ وَضُوئِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَصْنَعُ كَيْفَ أَقْضِي فِي مَالِي حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ فِي آخِرِ النِّسَاءِ ‏{وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلاَلَةً‏}‏ الآيَةَ وَ ‏{يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ}‏ الآيَةَ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 27, Hadith 1083","u":"https://quranx.com/Hadith/Malik/In-Book/Book-27/Hadith-1083","x":"Yahya related to me from Malik from Zayd ibn Aslam that Umar ibn al-Khattab asked the Messenger of Allah, may Allah bless him and grant him peace, about someone who died without parents or offspring, and the Messenger of Allah, may Allah bless him and grant him peace, said to him, \"The ayat which was sent down in the summer at the end of the Surat an-Nisa (Sura 4) is enoughfor you.\" Malik said, \"The generally agreed on way of doing things among us, in which there is no dispute, and which I saw the people of knowledge in our city doing, is that the person who leaves neither parent or offspring can be of two types. As for the kind described in the ayat which was sent down at the beginning of the Surat an-Nisa in which Allah, the Blessed, the Exalted! said, 'If a man or a woman has no direct heir, but has a brother or a sister by the mother, each of the two has a sixth. If there are more than that, they share equally in a third.' (Sura 4 ayat 12) This heirless one does not have heirs among his mother's siblings since there are no children or parents. As for the other kind described in the ayat which comes at the end of the Surat an-Nisa, Allah, the Blessed, the Exalted, said in it, 'They will ask you for a decision. Say, \"Allah gives you a decision about the indirect heirs. If a man perishes having no children, but he has a sister, she shall receive a half of what he leaves, and he is her heir if she has no children. If there are two sisters, they shall receive two-thirds of what he leaves. If there are brothers and sisters, the male shall receive the portion of two females. Allah makes clear to you that you might not go astray. Allah has knowledge of everything\" ' \" (Sura 4 ayat 176). Malik said, \"If this person without direct heirs (parents) or children has siblings by the father, they inherit with the grandfather from the person without direct heirs. The grandfather inherits with the siblings because he is more entitled to the inheritance than them. That is because he inherits a sixth with the male children of the deceased when the siblings do not inherit anything with the male children of the deceased. How can he not be like one of them when he takes a sixth with the children of the deceased? How can he not take a third with the siblings while the brother's sons take a third with them? The grandfather is the one who overshadows the half-siblings by the mother and keeps them from inheriting. He is more entitled to what they have because they are omitted for his sake. If the grandfather did not take that third, the half-siblings by the mother would take it and would take what does not return to the half-siblings by the father. The half-siblings by the mother are more entitled to that third than the half-siblings by the father while the grandfather is more entitled to that than the half- siblings by the mother.\"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنِ الْكَلاَلَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ يَكْفِيكَ مِنْ ذَلِكَ الآيَةُ الَّتِي أُنْزِلَتْ فِي الصَّيْفِ آخِرَ سُورَةِ النِّسَاءِ ‏\"\n\n‏ ‏.‏","v":[]}],"13":[{"c":"Sahih Muslim","r":"Hadith 175","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-175","x":"It is narrated on the authority of Abu Huraira that the (words of Allah):\n\n\" And certainly he saw him in another descent\" (al-Qur'an, Iiii. 13) imply that he saw Gabriel.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ عَبْدِ الْمَلِكِ، عَنْ عَطَاءٍ، عَنْ أَبِي هُرَيْرَةَ، ‏{‏ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى‏}‏ قَالَ رَأَى جِبْرِيلَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 176b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-176b","x":"It is narrated on the authority of Ibn Abbas that the words:\n\n\" The heart belied not what he saw\" (al-Qur'an, Iiii. 11) and\" Certainly he saw Him in another descent\" (al-Qur'an, Iiii. 13) imply that he saw him twice with his heart.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو سَعِيدٍ الأَشَجُّ جَمِيعًا عَنْ وَكِيعٍ، - قَالَ الأَشَجُّ حَدَّثَنَا وَكِيعٌ، - حَدَّثَنَا الأَعْمَشُ، عَنْ زِيَادِ بْنِ الْحُصَيْنِ أَبِي جَهْمَةَ، عَنْ أَبِي الْعَالِيَةِ، عَنِ ابْنِ عَبَّاسٍ، قَالَ ‏{‏ مَا كَذَبَ الْفُؤَادُ مَا رَأَى‏}‏ ‏{‏ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى‏}‏ قَالَ رَآهُ بِفُؤَادِهِ مَرَّتَيْنِ ‏.‏","v":[]}],"15":[{"c":"Sunan Abu Dawud","r":"Hadith 4427","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4427","x":"Narrated Abdullah ibn Abbas:\n\nThe Prophet (ﷺ) said to Ma'iz ibn Malik: Perhaps you kissed, or squeezed, or looked. He said: No. He then said: Did you have intercourse with her? He said: Yes. On the (reply) he (the Prophet) gave order that he should be stoned to death. The narrator did not mention \"on the authority of Ibn 'Abbas\". This is Wahb's version.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا جَرِيرٌ، حَدَّثَنِي يَعْلَى، عَنْ عِكْرِمَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم ح وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ وَعُقْبَةُ بْنُ مُكْرَمٍ قَالاَ حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ حَدَّثَنَا أَبِي قَالَ سَمِعْتُ يَعْلَى بْنَ حَكِيمٍ يُحَدِّثُ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لِمَاعِزِ بْنِ مَالِكٍ ‏\"‏ لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ ‏\"‏ ‏.‏ قَالَ لاَ ‏.‏ قَالَ ‏\"‏ أَفَنِكْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ ‏.‏ وَلَمْ يَذْكُرْ مُوسَى عَنِ ابْنِ عَبَّاسٍ وَهَذَا لَفْظُ وَهْبٍ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4428","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4428","x":"Narrated AbuHurayrah:\n\nA man of the tribe of Aslam came to the Prophet (ﷺ) and testified four times against himself that he had had illicit intercourse with a woman, while all the time the Prophet (ﷺ) was turning away from him. Then when he confessed a fifth time, he turned round and asked: Did you have intercourse with her? He replied: Yes. He asked: Have you done it so that your sexual organ penetrated hers? He replied: Yes. He asked: Have you done it like a collyrium stick when enclosed in its case and a rope in a well? He replied: Yes. He asked: Do you know what fornication is? He replied: Yes. I have done with her unlawfully what a man may lawfully do with his wife. He then asked: What do you want from what you have said? He said: I want you to purify me. So he gave orders regarding him and he was stoned to death. Then the Prophet (ﷺ) heard one of his companions saying to another: Look at this man whose fault was concealed by Allah but who would not leave the matter alone, so that he was stoned like a dog. He said nothing to them but walked on for a time till he came to the corpse of an ass with its legs in the air. He asked: Where are so and so? They said: Here we are, Messenger of Allah (ﷺ)! He said: Go down and eat some of this ass's corpse. They replied: Messenger of Allah! Who can eat any of this? He said: The dishonour you have just shown to your brother is more serious than eating some of it. By Him in Whose hand my soul is, he is now among the rivers of Paradise and plunging into them.","ar":"حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّ عَبْدَ الرَّحْمَنِ بْنَ الصَّامِتِ ابْنَ عَمِّ أَبِي هُرَيْرَةَ، أَخْبَرَهُ أَنَّهُ، سَمِعَ أَبَا هُرَيْرَةَ، يَقُولُ جَاءَ الأَسْلَمِيُّ إِلَى نَبِيِّ اللَّهِ صلى الله عليه وسلم فَشَهِدَ عَلَى نَفْسِهِ أَنَّهُ أَصَابَ امْرَأَةً حَرَامًا أَرْبَعَ مَرَّاتٍ كُلُّ ذَلِكَ يُعْرِضُ عَنْهُ النَّبِيُّ صلى الله عليه وسلم فَأَقْبَلَ فِي الْخَامِسَةِ فَقَالَ ‏\"‏ أَنِكْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ حَتَّى غَابَ ذَلِكَ مِنْكَ فِي ذَلِكَ مِنْهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ كَمَا يَغِيبُ الْمِرْوَدُ فِي الْمُكْحُلَةِ وَالرِّشَاءُ فِي الْبِئْرِ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ فَهَلْ تَدْرِي مَا الزِّنَا ‏\"‏ ‏.‏ قَالَ نَعَمْ أَتَيْتُ مِنْهَا حَرَامًا مَا يَأْتِي الرَّجُلُ مِنِ امْرَأَتِهِ حَلاَلاً ‏.‏ قَالَ ‏\"‏ فَمَا تُرِيدُ بِهَذَا الْقَوْلِ ‏\"‏ ‏.‏ قَالَ أُرِيدُ أَنْ تُطَهِّرَنِي ‏.‏ فَأَمَرَ بِهِ فَرُجِمَ فَسَمِعَ النَّبِيُّ صلى الله عليه وسلم رَجُلَيْنِ مِنْ أَصْحَابِهِ يَقُولُ أَحَدُهُمَا لِصَاحِبِهِ انْظُرْ إِلَى هَذَا الَّذِي سَتَرَ اللَّهُ عَلَيْهِ فَلَمْ تَدَعْهُ نَفْسُهُ حَتَّى رُجِمَ رَجْمَ الْكَلْبِ ‏.‏ فَسَكَتَ عَنْهُمَا ثُمَّ سَارَ سَاعَةً حَتَّى مَرَّ بِجِيفَةِ حِمَارٍ شَائِلٍ بِرِجْلِهِ فَقَالَ ‏\"‏ أَيْنَ فُلاَنٌ وَفُلاَنٌ ‏\"‏ ‏.‏ فَقَالاَ نَحْنُ ذَانِ يَا رَسُولَ اللَّهِ ‏.‏ قَالَ ‏\"‏ انْزِلاَ فَكُلاَ مِنْ جِيفَةِ هَذَا الْحِمَارِ ‏\"‏ ‏.‏ فَقَالاَ يَا نَبِيَّ اللَّهِ مَنْ يَأْكُلُ مِنْ هَذَا قَالَ ‏\"‏ فَمَا نِلْتُمَا مِنْ عِرْضِ أَخِيكُمَا آنِفًا أَشَدُّ مِنْ أَكْلٍ مِنْهُ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهُ الآنَ لَفِي أَنْهَارِ الْجَنَّةِ يَنْقَمِسُ فِيهَا ‏\"‏ ‏.‏","v":[]}],"16":[{"c":"Sunan Abu Dawud","r":"Hadith 4427","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4427","x":"Narrated Abdullah ibn Abbas:\n\nThe Prophet (ﷺ) said to Ma'iz ibn Malik: Perhaps you kissed, or squeezed, or looked. He said: No. He then said: Did you have intercourse with her? He said: Yes. On the (reply) he (the Prophet) gave order that he should be stoned to death. The narrator did not mention \"on the authority of Ibn 'Abbas\". This is Wahb's version.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا جَرِيرٌ، حَدَّثَنِي يَعْلَى، عَنْ عِكْرِمَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم ح وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ وَعُقْبَةُ بْنُ مُكْرَمٍ قَالاَ حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ حَدَّثَنَا أَبِي قَالَ سَمِعْتُ يَعْلَى بْنَ حَكِيمٍ يُحَدِّثُ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لِمَاعِزِ بْنِ مَالِكٍ ‏\"‏ لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ ‏\"‏ ‏.‏ قَالَ لاَ ‏.‏ قَالَ ‏\"‏ أَفَنِكْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ ‏.‏ وَلَمْ يَذْكُرْ مُوسَى عَنِ ابْنِ عَبَّاسٍ وَهَذَا لَفْظُ وَهْبٍ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 173","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-173","x":"It is narrated on the authority of Abdullah (b. Umar) that when the Messenger of Allah (ﷺ) was taken for the Night journey, he was taken to Sidrat-ul-Muntaha, which is situated on the sixth heaven, where terminates everything that ascends from the earth and is held there, and where terminates every- thing that descends from above it and is held there. (It is with reference to this that) Allah said:\n\n\" When that which covers covered the lote-tree\" (al-Qur'an, Iiii. 16). He (the narrator) said: (It was) gold moths. He (the narrator further) said: The Messenger of Allah (ﷺ) was given three (things): he was given five prayers, be was given the concluding verses of Sura al-Baqara, and remission of serious Sins for those among his Ummah who associate not anything with Allah","ar":"وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا مَالِكُ بْنُ مِغْوَلٍ، ح وَحَدَّثَنَا ابْنُ نُمَيْرٍ، وَزُهَيْرُ بْنُ حَرْبٍ، جَمِيعًا عَنْ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، - وَأَلْفَاظُهُمْ مُتَقَارِبَةٌ - قَالَ ابْنُ نُمَيْرٍ حَدَّثَنَا أَبِي، حَدَّثَنَا مَالِكُ بْنُ مِغْوَلٍ، عَنِ الزُّبَيْرِ بْنِ عَدِيٍّ، عَنْ طَلْحَةَ، عَنْ مُرَّةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَمَّا أُسْرِيَ بِرَسُولِ اللَّهِ صلى الله عليه وسلم انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ إِلَيْهَا يَنْتَهِي مَا يُعْرَجُ بِهِ مِنَ الأَرْضِ فَيُقْبَضُ مِنْهَا وَإِلَيْهَا يَنْتَهِي مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا قَالَ ‏{‏ إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَى‏}‏ قَالَ فَرَاشٌ مِنْ ذَهَبٍ ‏.‏ قَالَ فَأُعْطِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم ثَلاَثًا أُعْطِيَ الصَّلَوَاتِ الْخَمْسَ وَأُعْطِيَ خَوَاتِيمَ سُورَةِ الْبَقَرَةِ وَغُفِرَ لِمَنْ لَمْ يُشْرِكْ بِاللَّهِ مِنْ أُمَّتِهِ شَيْئًا الْمُقْحِمَاتُ ‏.‏","v":[]}],"19":[{"c":"Sunan Abu Dawud","r":"Hadith 2094","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2094","x":"The aforesaid tradition has also been transmitted through a different chain of narrators by Muhammad bin ‘Amr. This version adds \"If she weeps or keeps silence\". The narrator added the word \"weeps\". Abu Dawud said:\n\nThe word \"weeps\" is not guarded. This is a misunderstanding of the tradition on the part of the narrator Ibn Idris or Muhammad b. al-'Ata. Abu Dawud said: This tradition has also been narrated by Abu 'Amr Dhakwan on the authority of 'Aishah who said: A virgin is ashamed of speaking, Messenger of Allah. He said: Her silence is her acceptance.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا ابْنُ إِدْرِيسَ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، بِهَذَا الْحَدِيثِ بِإِسْنَادِهِ زَادَ فِيهِ قَالَ ‏\"‏ فَإِنْ بَكَتْ أَوْ سَكَتَتْ ‏\"‏ ‏.‏ زَادَ ‏\"‏ بَكَتْ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَلَيْسَ ‏\"‏ بَكَتْ ‏\"‏ ‏.‏ بِمَحْفُوظٍ وَهُوَ وَهَمٌ فِي الْحَدِيثِ الْوَهَمُ مِنِ ابْنِ إِدْرِيسَ أَوْ مِنْ مُحَمَّدِ بْنِ الْعَلاَءِ ‏.‏ قَالَ أَبُو دَاوُدَ وَرَوَاهُ أَبُو عَمْرٍو ذَكْوَانُ عَنْ عَائِشَةَ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ الْبِكْرَ تَسْتَحِي أَنْ تَتَكَلَّمَ ‏.‏ قَالَ ‏\"‏ سُكَاتُهَا إِقْرَارُهَا ‏\"‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2095","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2095","x":"Narrated Abdullah ibn Umar:\n\nThe Prophet (ﷺ) said: Consult women about (the marriage of) their daughters.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُعَاوِيَةُ بْنُ هِشَامٍ، عَنْ سُفْيَانَ، عَنْ إِسْمَاعِيلَ بْنِ أُمَيَّةَ، حَدَّثَنِي الثِّقَةُ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ آمِرُوا النِّسَاءَ فِي بَنَاتِهِنَّ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4579","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4579","x":"Narrated Ibn `Abbas:\n\nregarding the Divine Verse: \"O you who believe! You are forbidden to inherit women against their will, and you should not treat them with harshness that you may take back part of the (Mahr) dower you have given them.\" (4.19) (Before this revelation) if a man died, his relatives used to have the right to inherit his wife, and one of them could marry her if he would, or they would give her in marriage if they wished, or, if they wished, they would not give her in marriage at all, and they would be more entitled to dispose her, than her own relatives. So the above Verse was revealed in this connection.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ مُقَاتِلٍ، حَدَّثَنَا أَسْبَاطُ بْنُ مُحَمَّدٍ، حَدَّثَنَا الشَّيْبَانِيُّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ،‏.‏ قَالَ الشَّيْبَانِيُّ وَذَكَرَهُ أَبُو الْحَسَنِ السُّوَائِيُّ وَلاَ أَظُنُّهُ ذَكَرَهُ إِلاَّ عَنِ ابْنِ عَبَّاسٍ، ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا وَلاَ تَعْضُلُوهُنَّ لِتَذْهَبُوا بِبَعْضِ مَا آتَيْتُمُوهُنَّ‏}‏ قَالَ كَانُوا إِذَا مَاتَ الرَّجُلُ كَانَ أَوْلِيَاؤُهُ أَحَقَّ بِامْرَأَتِهِ، إِنْ شَاءَ بَعْضُهُمْ تَزَوَّجَهَا، وَإِنْ شَاءُوا زَوَّجُوهَا، وَإِنْ شَاءُوا لَمْ يُزَوِّجُوهَا، فَهُمْ أَحَقُّ بِهَا مِنْ أَهْلِهَا، فَنَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6948","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6948","x":"Narrated Ibn `Abbas:\n\nRegarding the Qur'anic Verse: 'O you who believe! You are forbidden to inherit women against their will.' (4.19) The custom (in the Pre-lslamic Period) was that if a man died, his relatives used to have the right to inherit his wife, and if one of them wished, he could marry her, or they could marry her to somebody else, or prevent her from marrying if they wished, for they had more right to dispose of her than her own relatives. Therefore this Verse was revealed concerning this matter.","ar":"حَدَّثَنَا حُسَيْنُ بْنُ مَنْصُورٍ، حَدَّثَنَا أَسْبَاطُ بْنُ مُحَمَّدٍ، حَدَّثَنَا الشَّيْبَانِيُّ، سُلَيْمَانُ بْنُ فَيْرُوزَ عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ،‏.‏ قَالَ الشَّيْبَانِيُّ وَحَدَّثَنِي عَطَاءٌ أَبُو الْحَسَنِ السُّوَائِيُّ،، وَلاَ أَظُنُّهُ إِلاَّ ذَكَرَهُ عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا‏}‏ الآيَةَ قَالَ كَانُوا إِذَا مَاتَ الرَّجُلُ كَانَ أَوْلِيَاؤُهُ أَحَقَّ بِامْرَأَتِهِ، إِنْ شَاءَ بَعْضُهُمْ تَزَوَّجَهَا، وَإِنْ شَاءُوا زَوَّجَهَا، وَإِنْ شَاءُوا لَمْ يُزَوِّجْهَا، فَهُمْ أَحَقُّ بِهَا مِنْ أَهْلِهَا، فَنَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ‏.‏","v":[]}],"23":[{"c":"Sahih Bukhari","r":"Hadith 5098","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5098","x":"Narrated Aisha\":\n\n(regarding) the Verse: 'And if you fear that you shall not be able to deal justly with the orphans...' (4.3) It is about the orphan girl who is in the custody of a man who is her guardian, and he intends to marry her because of her wealth, but he treats her badly and does not manage her property fairly and honestly. Such a man should marry women of his liking other than her, two or three or four. 'Prohibited to you (for marriage) are:...your foster-mothers (who suckled you).' (4.23) Marriage is prohibited between persons having a foster suckling relationship corresponding to a blood relationship which renders marriage unlawful.","ar":"حَدَّثَنَا مُحَمَّدٌ، أَخْبَرَنَا عَبْدَةُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ، تُقْسِطُوا فِي الْيَتَامَى‏}‏‏.‏ قَالَتِ الْيَتِيمَةُ تَكُونُ عِنْدَ الرَّجُلِ وَهْوَ وَلِيُّهَا، فَيَتَزَوَّجُهَا عَلَى مَالِهَا، وَيُسِيءُ صُحْبَتَهَا، وَلاَ يَعْدِلُ فِي مَالِهَا، فَلْيَتَزَوَّجْ مَا طَابَ لَهُ مِنَ النِّسَاءِ سِوَاهَا مَثْنَى وَثُلاَثَ وَرُبَاعَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5105","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5105","x":"Ibn 'Abbas further said, \"Seven types of marriages are unlawful because of blood relations, and seven because of marriage relations.\" Then Ibn 'Abbas recited the Verse:\n\n\"Forbidden for you (for marriages) are your mothers...\" (4:23). 'Abdullah bin Ja'far married the daughter and wife of 'Ali at the same time (they were step-daughter and mother). Ibn Sirin said, \"There is no harm in that.\" But Al-Hasan Al-Basri disapproved of it at first, but then said that there was no harm in it. Al-Hasan bin Al-Hasan bin 'Ali married two of his cousins in one night. Ja'far bin Zaid disapproved of that because of it would bring hatred (between the two cousins), but it is not unlawful, as Allah said, \"Lawful to you are all others [beyond those (mentioned)]. (4:24). Ibn 'Abbas said: \"If somebody commits illegal sexual intercourse with his wife's sister, his wife does not become unlawful for him.\" And narrated Abu Ja'far, \"If a person commits homosexuality with a boy, then the mother of that boy is unlawful for him to marry.\" Narrated Ibn 'Abbas, \"If one commits illegal sexual intercourse with his mother in law, then his married relation to his wife does not become unlawful.\" Abu Nasr reported to have said that Ibn 'Abbas in the above case, regarded his marital relation to his wife unlawful, but Abu Nasr is not known well for hearing Hadith from Ibn 'Abbas. Imran bin Hussain, Jabir b. Zaid, Al-Hasan and some other Iraqi's, are reported to have judged that his marital relations to his wife would be unlawful. In the above case Abu Hurairah said, \"The marital relation to one's wife does not become unlawful except if one as had sexual intercourse (with her mother).\" Ibn Al-Musaiyab, 'Urwa, and Az-Zuhri allows such person to keep his wife. 'Ali said, \"His marital relations to his wife does not become unlawful.\"","ar":"وَقَالَ لَنَا أَحْمَدُ بْنُ حَنْبَلٍ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ سُفْيَانَ، حَدَّثَنِي حَبِيبٌ، عَنْ سَعِيدٍ، عَنِ ابْنِ عَبَّاسٍ، حَرُمَ مِنَ النَّسَبِ سَبْعٌ، وَمِنَ الصِّهْرِ سَبْعٌ‏.‏ ثُمَّ قَرَأَ ‏{‏حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ‏}‏ الآيَةَ‏.‏ وَجَمَعَ عَبْدُ اللَّهِ بْنُ جَعْفَرٍ بَيْنَ ابْنَةِ عَلِيٍّ وَامْرَأَةِ عَلِيٍّ‏.‏ وَقَالَ ابْنُ سِيرِينَ لاَ بَأْسَ بِهِ‏.‏ وَكَرِهَهُ الْحَسَنُ مَرَّةً ثُمَّ قَالَ لاَ بَأْسَ بِهِ‏.‏ وَجَمَعَ الْحَسَنُ بْنُ الْحَسَنِ بْنِ عَلِيٍّ بَيْنَ ابْنَتَىْ عَمٍّ فِي لَيْلَةٍ، وَكَرِهَهُ جَابِرُ بْنُ زَيْدٍ لِلْقَطِيعَةِ، وَلَيْسَ فِيهِ تَحْرِيمٌ لِقَوْلِهِ تَعَالَى ‏{‏وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ‏}‏ وَقَالَ عِكْرِمَةُ عَنِ ابْنِ عَبَّاسٍ إِذَا زَنَى بِأُخْتِ امْرَأَتِهِ لَمْ تَحْرُمْ عَلَيْهِ امْرَأَتُهُ‏.‏ وَيُرْوَى عَنْ يَحْيَى الْكِنْدِيِّ عَنِ الشَّعْبِيِّ وَأَبِي جَعْفَرٍ، فِيمَنْ يَلْعَبُ بِالصَّبِيِّ إِنْ أَدْخَلَهُ فِيهِ، فَلاَ يَتَزَوَّجَنَّ أُمَّهُ، وَيَحْيَى هَذَا غَيْرُ مَعْرُوفٍ، لَمْ يُتَابَعْ عَلَيْهِ‏.‏ وَقَالَ عِكْرِمَةُ عَنِ ابْنِ عَبَّاسٍ إِذَا زَنَى بِهَا لَمْ تَحْرُمْ عَلَيْهِ امْرَأَتُهُ‏.‏ وَيُذْكَرُ عَنْ أَبِي نَصْرٍ أَنَّ ابْنَ عَبَّاسٍ حَرَّمَهُ‏.‏ وَأَبُو نَصْرٍ هَذَا لَمْ يُعْرَفْ بِسَمَاعِهِ مِنِ ابْنِ عَبَّاسٍ‏.‏ وَيُرْوَى عَنْ عِمْرَانَ بْنِ حُصَيْنٍ وَجَابِرِ بْنِ زَيْدٍ وَالْحَسَنِ وَبَعْضِ أَهْلِ الْعِرَاقِ تَحْرُمُ عَلَيْهِ‏.‏ وَقَالَ أَبُو هُرَيْرَةَ لاَ تَحْرُمُ حَتَّى يُلْزِقَ بِالأَرْضِ يَعْنِي يُجَامِعَ‏.‏ وَجَوَّزَهُ ابْنُ الْمُسَيَّبِ وَعُرْوَةُ وَالزُّهْرِيُّ‏.‏ وَقَالَ الزُّهْرِيُّ قَالَ عَلِيٌّ لاَ تَحْرُمُ‏.‏ وَهَذَا مُرْسَلٌ‏.‏","v":[]}],"24":[{"c":"Sunan Abu Dawud","r":"Hadith 2160","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2160","x":"'Amr b. Shu'aib on his father's authority said that his grandfather (Abdullah ibn Amr ibn al-'As) reported the Prophet (ﷺ) said:\n\nIf one of you marries a woman or buys a slave, he should say: \"O Allah, I ask You for the good in her, and in the disposition You have given her; I take refuge in You from the evil in her, and in the disposition You have given her.\" When he buys a camel, he should take hold of the top of its hump and say the same kind of thing. Abu Dawud said: Abu Sa'id added the following words in his version: He should then tale hold of her forelock and pray for blessing in the case of a woman or a slave.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَعَبْدُ اللَّهِ بْنُ سَعِيدٍ، قَالاَ حَدَّثَنَا أَبُو خَالِدٍ، - يَعْنِي سُلَيْمَانَ بْنَ حَيَّانَ - عَنِ ابْنِ عَجْلاَنَ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً أَوِ اشْتَرَى خَادِمًا فَلْيَقُلِ اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ زَادَ أَبُو سَعِيدٍ ‏\"‏ ثُمَّ لْيَأْخُذْ بِنَاصِيَتِهَا وَلْيَدْعُ بِالْبَرَكَةِ ‏\"‏ ‏.‏ فِي الْمَرْأَةِ وَالْخَادِمِ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 371","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-371","x":"Narrated `Abdul `Aziz:\n\nAnas said, 'When Allah's Messenger (ﷺ) invaded Khaibar, we offered the Fajr prayer there (early in the morning) when it was still dark. The Prophet (ﷺ) rode and Abu Talha rode too and I was riding behind Abu Talha. The Prophet (ﷺ) passed through the lane of Khaibar quickly and my knee was touching the thigh of the Prophet (ﷺ). He uncovered his thigh and I saw the whiteness of the thigh of the Prophet. When he entered the town, he said, 'Allahu Akbar! Khaibar is ruined. Whenever we approach near a (hostile) nation (to fight) then evil will be the morning of those who have been warned.' He repeated this thrice. The people came out for their jobs and some of them said, 'Muhammad (has come).' (Some of our companions added, \"With his army.\") We conquered Khaibar, took the captives, and the booty was collected. Dihya came and said, 'O Allah's Prophet! Give me a slave girl from the captives.' The Prophet said, 'Go and take any slave girl.' He took Safiya bint Huyai. A man came to the Prophet (ﷺ) and said, 'O Allah's Messenger (ﷺ)s! You gave Safiya bint Huyai to Dihya and she is the chief mistress of the tribes of Quraidha and An-Nadir and she befits none but you.' So the Prophet (ﷺ) said, 'Bring him along with her.' So Dihya came with her and when the Prophet (ﷺ) saw her, he said to Dihya, 'Take any slave girl other than her from the captives.' Anas added: The Prophet (ﷺ) then manumitted her and married her.\" Thabit asked Anas, \"O Abu Hamza! What did the Prophet (ﷺ) pay her (as Mahr)?\" He said, \"Her self was her Mahr for he manumitted her and then married her.\" Anas added, \"While on the way, Um Sulaim dressed her for marriage (ceremony) and at night she sent her as a bride to the Prophet (ﷺ). So the Prophet was a bridegroom and he said, 'Whoever has anything (food) should bring it.' He spread out a leather sheet (for the food) and some brought dates and others cooking butter. (I think he (Anas) mentioned As-Sawaq). So they prepared a dish of Hais (a kind of meal). And that was Walima (the marriage banquet) of Allah's Messenger (ﷺ).\"","ar":"حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ ابْنُ عُلَيَّةَ، قَالَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم غَزَا خَيْبَرَ، فَصَلَّيْنَا عِنْدَهَا صَلاَةَ الْغَدَاةِ بِغَلَسٍ، فَرَكِبَ نَبِيُّ اللَّهِ صلى الله عليه وسلم وَرَكِبَ أَبُو طَلْحَةَ، وَأَنَا رَدِيفُ أَبِي طَلْحَةَ، فَأَجْرَى نَبِيُّ اللَّهِ صلى الله عليه وسلم فِي زُقَاقِ خَيْبَرَ، وَإِنَّ رُكْبَتِي لَتَمَسُّ فَخِذَ نَبِيِّ اللَّهِ صلى الله عليه وسلم، ثُمَّ حَسَرَ الإِزَارَ عَنْ فَخِذِهِ حَتَّى إِنِّي أَنْظُرُ إِلَى بَيَاضِ فَخِذِ نَبِيِّ اللَّهِ صلى الله عليه وسلم، فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ ‏\"‏ اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏\"‏‏.‏ قَالَهَا ثَلاَثًا‏.‏ قَالَ وَخَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ فَقَالُوا مُحَمَّدٌ ـ قَالَ عَبْدُ الْعَزِيزِ وَقَالَ بَعْضُ أَصْحَابِنَا ـ وَالْخَمِيسُ‏.‏ يَعْنِي الْجَيْشَ، قَالَ فَأَصَبْنَاهَا عَنْوَةً، فَجُمِعَ السَّبْىُ، فَجَاءَ دِحْيَةُ فَقَالَ يَا نَبِيَّ اللَّهِ، أَعْطِنِي جَارِيَةً مِنَ السَّبْىِ‏.‏ قَالَ ‏\"‏ اذْهَبْ فَخُذْ جَارِيَةً ‏\"‏‏.‏ فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَىٍّ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ يَا نَبِيَّ اللَّهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَىٍّ سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ، لاَ تَصْلُحُ إِلاَّ لَكَ‏.‏ قَالَ ‏\"‏ ادْعُوهُ بِهَا ‏\"‏‏.‏ فَجَاءَ بِهَا، فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صلى الله عليه وسلم قَالَ ‏\"‏ خُذْ جَارِيَةً مِنَ السَّبْىِ غَيْرَهَا ‏\"‏‏.‏ قَالَ فَأَعْتَقَهَا النَّبِيُّ صلى الله عليه وسلم وَتَزَوَّجَهَا‏.‏ فَقَالَ لَهُ ثَابِتٌ يَا أَبَا حَمْزَةَ، مَا أَصْدَقَهَا قَالَ نَفْسَهَا، أَعْتَقَهَا وَتَزَوَّجَهَا، حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أُمُّ سُلَيْمٍ فَأَهْدَتْهَا لَهُ مِنَ اللَّيْلِ، فَأَصْبَحَ النَّبِيُّ صلى الله عليه وسلم عَرُوسًا فَقَالَ ‏\"‏ مَنْ كَانَ عِنْدَهُ شَىْءٌ فَلْيَجِئْ بِهِ ‏\"‏‏.‏ وَبَسَطَ نِطَعًا، فَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ ـ قَالَ وَأَحْسِبُهُ قَدْ ذَكَرَ السَّوِيقَ ـ قَالَ فَحَاسُوا حَيْسًا، فَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1905","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1905","x":"Narrated 'Alqama:\n\nWhile I was walking with `Abdullah he said, \"We were in the company of the Prophet (ﷺ) and he said, 'He who can afford to marry should marry, because it will help him refrain from looking at other women, and save his private parts from committing illegal sexual relation; and he who cannot afford to marry is advised to fast, as fasting will diminish his sexual power.\"","ar":"حَدَّثَنَا عَبْدَانُ، عَنْ أَبِي حَمْزَةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، قَالَ بَيْنَا أَنَا أَمْشِي، مَعَ عَبْدِ اللَّهِ ـ رضى الله عنه ـ فَقَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\n\n\"‏ مَنِ اسْتَطَاعَ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّهُ لَهُ وِجَاءٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2052","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2052","x":"Narrated `Abdullah bin Abu Mulaika:\n\n`Uqba bin Al-Harith said that a black woman came and claimed that she had suckled both of them (i.e. `Uqba and his wife). So, he mentioned that to the Prophet (ﷺ) who turned his face from him and smiled and said, \"How (can you keep your wife), and it was said (that both of you were suckled by the same woman)?\" His wife was the daughter of Abu Ihab-al-Tamimi.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي حُسَيْنٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ، عَنْ عُقْبَةَ بْنِ الْحَارِثِ ـ رضى الله عنه ـ أَنَّ امْرَأَةً، سَوْدَاءَ جَاءَتْ، فَزَعَمَتْ أَنَّهَا أَرْضَعَتْهُمَا، فَذَكَرَ لِلنَّبِيِّ فَأَعْرَضَ عَنْهُ، وَتَبَسَّمَ النَّبِيُّ صلى الله عليه وسلم‏.‏ قَالَ ‏\n\n\"‏ كَيْفَ وَقَدْ قِيلَ ‏\"\n\n‏‏.‏ وَقَدْ كَانَتْ تَحْتَهُ ابْنَةُ أَبِي إِهَابٍ التَّمِيمِيِّ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2228","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2228","x":"Narrated Anas:\n\nAmongst the captives was Safiya. First she was given to Dihya Al-Kalbi and then to the Prophet.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ كَانَ فِي السَّبْىِ صَفِيَّةُ، فَصَارَتْ إِلَى دَحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ إِلَى النَّبِيِّ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2235","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2235","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) came to Khaibar and when Allah made him victorious and he conquered the town by breaking the enemy's defense, the beauty of Safiya bint Huyai bin Akhtab was mentioned to him and her husband had been killed while she was a bride. Allah's Messenger (ﷺ) selected her for himself and he set out in her company till he reached Sadd-ar-Rawha' where her menses were over and he married her. Then Hais (a kind of meal) was prepared and served on a small leather sheet (used for serving meals). Allah's Messenger (ﷺ) then said to me, \"Inform those who are around you (about the wedding banquet).\" So that was the marriage banquet given by Allah's Messenger (ﷺ) for (his marriage with) Safiya. After that we proceeded to Medina and I saw that Allah's Messenger (ﷺ) was covering her with a cloak while she was behind him. Then he would sit beside his camel and let Safiya put her feet on his knees to ride (the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمَ النَّبِيُّ صلى الله عليه وسلم خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا، وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الرَّوْحَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ، حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2541","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2541","x":"Narrated Ibn `Aun:\n\nI wrote a letter to Nafi` and Nafi` wrote in reply to my letter that the Prophet (ﷺ) had suddenly attacked Bani Mustaliq without warning while they were heedless and their cattle were being watered at the places of water. Their fighting men were killed and their women and children were taken as captives; the Prophet (ﷺ) got Juwairiya on that day. Nafi` said that Ibn `Umar had told him the above narration and that Ibn `Umar was in that army.","ar":"حَدَّثَنَا عَلِيُّ بْنُ الْحَسَنِ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا ابْنُ عَوْنٍ، قَالَ كَتَبْتُ إِلَى نَافِعٍ فَكَتَبَ إِلَىَّ أَنَّ النَّبِيَّ صلى الله عليه وسلم أَغَارَ عَلَى بَنِي الْمُصْطَلِقِ وَهُمْ غَارُّونَ وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ، فَقَتَلَ مُقَاتِلَتَهُمْ، وَسَبَى ذَرَارِيَّهُمْ، وَأَصَابَ يَوْمَئِذٍ جُوَيْرِيَةَ‏.‏ حَدَّثَنِي بِهِ عَبْدُ اللَّهِ بْنُ عُمَرَ، وَكَانَ فِي ذَلِكَ الْجَيْشِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2542","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2542","x":"Narrated Ibn Muhairiz:\n\nI saw Abu Sa`id and asked him about coitus interruptus. Abu Sa`id said, \"We went with Allah's Apostle, in the Ghazwa of Bani Al-Mustaliq and we captured some of the 'Arabs as captives, and the long separation from our wives was pressing us hard and we wanted to practice coitus interruptus. We asked Allah's Messenger (ﷺ) (whether it was permissible). He said, \"It is better for you not to do so. No soul, (that which Allah has) destined to exist, up to the Day of Resurrection, but will definitely come, into existence.\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنِ ابْنِ مُحَيْرِيزٍ، قَالَ رَأَيْتُ أَبَا سَعِيدٍ ـ رضى الله عنه ـ فَسَأَلْتُهُ فَقَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي غَزْوَةِ بَنِي الْمُصْطَلِقِ فَأَصَبْنَا سَبْيًا مِنْ سَبْىِ الْعَرَبِ، فَاشْتَهَيْنَا النِّسَاءَ فَاشْتَدَّتْ عَلَيْنَا الْعُزْبَةُ وَأَحْبَبْنَا الْعَزْلَ، فَسَأَلْنَا رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\n\n\"‏ مَا عَلَيْكُمْ أَنْ لاَ تَفْعَلُوا، مَا مِنْ نَسَمَةٍ كَائِنَةٍ إِلَى يَوْمِ الْقِيَامَةِ إِلاَّ وَهْىَ كَائِنَةٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2544","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2544","x":"Narrated Abu Musa:\n\nAllah's Messenger (ﷺ) said, \"He who has a slave-girl and educates and treats her nicely and then manumits and marries her, will get a double reward.\"","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، سَمِعَ مُحَمَّدَ بْنَ فُضَيْلٍ، عَنْ مُطَرِّفٍ، عَنِ الشَّعْبِيِّ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ مَنْ كَانَتْ لَهُ جَارِيَةٌ فَعَالَهَا، فَأَحْسَنَ إِلَيْهَا ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا، كَانَ لَهُ أَجْرَانِ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2893","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2893","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said to Abu Talha, \"Choose one of your boy servants to serve me in my expedition to Khaibar.\" So, Abu Talha took me letting me ride behind him while I was a boy nearing the age of puberty. I used to serve Allah's Messenger (ﷺ) when he stopped to rest. I heard him saying repeatedly, \"O Allah! I seek refuge with You from distress and sorrow, from helplessness and laziness, from miserliness and cowardice, from being heavily in debt and from being overcome by men.\" Then we reached Khaibar; and when Allah enabled him to conquer the Fort (of Khaibar), the beauty of Safiya bint Huyai bin Akhtab was described to him. Her husband had been killed while she was a bride. So Allah's Messenger (ﷺ) selected her for himself and took her along with him till we reached a place called Sa`d-AsSahba,' where her menses were over and he took her for his wife. Haris (a kind of dish) was served on a small leather sheet. Then Allah's Messenger (ﷺ) told me to call those who were around me. So, that was the marriage banquet of Allah's Messenger (ﷺ) and Safiya. Then we left for Medina. I saw Allah's Apostle folding a cloak round the hump of the camel so as to make a wide space for Safiya (to sit on behind him) He sat beside his camel letting his knees for Safiya to put her feet on so as to mount the camel. Then, we proceeded till we approached Medina; he looked at Uhud (mountain) and said, \"This is a mountain which loves us and is loved by us.\" Then he looked at Medina and said, \"O Allah! I make the area between its (i.e. Medina's) two mountains a sanctuary as Abraham made Mecca a sanctuary. O Allah! Bless them (i.e. the people of Medina) in their Mudd and Sa (i.e. measures).","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا يَعْقُوبُ، عَنْ عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي حَتَّى أَخْرُجَ إِلَى خَيْبَرَ ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ مُرْدِفِي، وَأَنَا غُلاَمٌ رَاهَقْتُ الْحُلُمَ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم إِذَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ ثُمَّ قَدِمْنَا خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ، فَخَرَجَ بِهَا حَتَّى بَلَغْنَا سَدَّ الصَّهْبَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ‏.‏ ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ حَتَّى تَرْكَبَ، فَسِرْنَا حَتَّى إِذَا أَشْرَفْنَا عَلَى الْمَدِينَةِ نَظَرَ إِلَى أُحُدٍ فَقَالَ ‏\"‏ هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ ثُمَّ نَظَرَ إِلَى الْمَدِينَةِ فَقَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ لاَبَتَيْهَا بِمِثْلِ مَا حَرَّمَ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4200","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4200","x":"Narrated Anas:\n\nThe Prophet (ﷺ) offered the Fajr Prayer near Khaibar when it was still dark and then said, \"Allahu-Akbar! Khaibar is destroyed, for whenever we approach a (hostile) nation (to fight), then evil will be the morning for those who have been warned.\" Then the inhabitants of Khaibar came out running on the roads. The Prophet (ﷺ) had their warriors killed, their offspring and woman taken as captives. Safiya was amongst the captives, She first came in the share of Dahya Alkali but later on she belonged to the Prophet. The Prophet (ﷺ) made her manumission as her 'Mahr'.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ صَلَّى النَّبِيُّ صلى الله عليه وسلم الصُّبْحَ قَرِيبًا مِنْ خَيْبَرَ بِغَلَسٍ ثُمَّ قَالَ ‏\n\n\"‏ اللَّهُ أَكْبَرُ خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ، فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏\"\n\n‏‏.‏ فَخَرَجُوا يَسْعَوْنَ فِي السِّكَكِ، فَقَتَلَ النَّبِيُّ صلى الله عليه وسلم الْمُقَاتِلَةَ، وَسَبَى الذُّرِّيَّةَ، وَكَانَ فِي السَّبْىِ صَفِيَّةُ، فَصَارَتْ إِلَى دِحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ إِلَى النَّبِيِّ صلى الله عليه وسلم، فَجَعَلَ عِتْقَهَا صَدَاقَهَا‏.‏ فَقَالَ عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ لِثَابِتٍ يَا أَبَا مُحَمَّدٍ آنْتَ قُلْتَ لأَنَسٍ مَا أَصْدَقَهَا فَحَرَّكَ ثَابِتٌ رَأْسَهُ تَصْدِيقًا لَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4201","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4201","x":"Narrated `Abdul `Aziz bin Suhaib:\n\nAnas bin Malik said, \"The Prophet (ﷺ) took Safiya as a captive. He manumitted her and married her.\" Thabit asked Anas, \"What did he give her as Mahr (i.e. marriage gift)?\" Anas replied. \"Her Mahr was herself, for he manumitted her.\"","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ يَقُولُ سَبَى النَّبِيُّ صلى الله عليه وسلم صَفِيَّةَ، فَأَعْتَقَهَا وَتَزَوَّجَهَا‏.‏ فَقَالَ ثَابِتٌ لأَنَسٍ مَا أَصْدَقَهَا قَالَ أَصْدَقَهَا نَفْسَهَا فَأَعْتَقَهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4211","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4211","x":"Narrated Anas bin Malik:\n\nWe arrived at Khaibar, and when Allah helped His Apostle to open the fort, the beauty of Safiya bint Huyai bin Akhtaq whose husband had been killed while she was a bride, was mentioned to Allah's Apostle. The Prophet (ﷺ) selected her for himself, and set out with her, and when we reached a place called Sidd-as-Sahba,' Safiya became clean from her menses then Allah's Messenger (ﷺ) married her. Hais (i.e. an 'Arabian dish) was prepared on a small leather mat. Then the Prophet (ﷺ) said to me, \"I invite the people around you.\" So that was the marriage banquet of the Prophet (ﷺ) and Safiya. Then we proceeded towards Medina, and I saw the Prophet, making for her a kind of cushion with his cloak behind him (on his camel). He then sat beside his camel and put his knee for Safiya to put her foot on, in order to ride (on the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، ح وَحَدَّثَنِي أَحْمَدُ، حَدَّثَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ الزُّهْرِيُّ، عَنْ عَمْرٍو، مَوْلَى الْمُطَّلِبِ عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمْنَا خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا النَّبِيُّ صلى الله عليه وسلم لِنَفْسِهِ، فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الصَّهْبَاءِ حَلَّتْ، فَبَنَى بِهَا رَسُولُ اللَّهِ صلى الله عليه وسلم، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ لِي ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَتَهُ عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، فَرَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ، فَيَضَعُ رُكْبَتَهُ، وَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4212","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4212","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) stayed with Safiya bint Huyai for three days on the way of Khaibar where he consummated his marriage with her. Safiya was amongst those who were ordered to use a veil.","ar":"حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ يَحْيَى، عَنْ حُمَيْدٍ الطَّوِيلِ، سَمِعَ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه أَنَّ النَّبِيَّ صلى الله عليه وسلم أَقَامَ عَلَى صَفِيَّةَ بِنْتِ حُيَىٍّ، بِطَرِيقِ خَيْبَرَ ثَلاَثَةَ أَيَّامٍ، حَتَّى أَعْرَسَ بِهَا، وَكَانَتْ فِيمَنْ ضُرِبَ عَلَيْهَا الْحِجَابُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4213","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4213","x":"Narrated Anas:\n\nThe Prophet (ﷺ) stayed for three rights between Khaibar and Medina and was married to Safiya. I invited the Muslim to h s marriage banquet and there wa neither meat nor bread in that banquet but the Prophet ordered Bilal to spread the leather mats on which dates, dried yogurt and butter were put. The Muslims said amongst themselves, \"Will she (i.e. Safiya) be one of the mothers of the believers, (i.e. one of the wives of the Prophet (ﷺ) ) or just (a lady captive) of what his right-hand possesses\" Some of them said, \"If the Prophet (ﷺ) makes her observe the veil, then she will be one of the mothers of the believers (i.e. one of the Prophet's wives), and if he does not make her observe the veil, then she will be his lady slave.\" So when he departed, he made a place for her behind him (on his and made her observe the veil.","ar":"حَدَّثَنَا سَعِيدُ بْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرِ بْنِ أَبِي كَثِيرٍ، قَالَ أَخْبَرَنِي حُمَيْدٌ، أَنَّهُ سَمِعَ أَنَسًا ـ رضى الله عنه ـ يَقُولُ أَقَامَ النَّبِيُّ صلى الله عليه وسلم بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلاَثَ لَيَالٍ يُبْنَى عَلَيْهِ بِصَفِيَّةَ، فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ، وَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلاَ لَحْمٍ، وَمَا كَانَ فِيهَا إِلاَّ أَنْ أَمَرَ بِلاَلاً بِالأَنْطَاعِ فَبُسِطَتْ، فَأَلْقَى عَلَيْهَا التَّمْرَ وَالأَقِطَ وَالسَّمْنَ، فَقَالَ الْمُسْلِمُونَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، أَوْ مَا مَلَكَتْ يَمِينُهُ قَالُوا إِنْ حَجَبَهَا فَهْىَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، وَإِنْ لَمْ يَحْجُبْهَا فَهْىَ مِمَّا مَلَكَتْ يَمِينُهُ‏.‏ فَلَمَّا ارْتَحَلَ وَطَّأَ لَهَا خَلْفَهُ، وَمَدَّ الْحِجَابَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5085","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5085","x":"Narrated Anas:\n\nThe Prophet (ﷺ) stayed for three days between Khaibar and Medina, and there he consummated his marriage to Safiyya bint Huyai. I invited the Muslims to the wedding banquet in which neither meat nor bread was offered. He ordered for leather dining-sheets to be spread, and dates, dried yoghurt and butter were laid on it, and that was the Prophet's wedding banquet. The Muslims wondered, \"Is she (Saffiyya) considered as his wife or his slave girl?\" Then they said, \"If he orders her to veil herself, she will be one of the mothers of the Believers; but if he does not order her to veil herself, she will be a slave girl. So when the Prophet (ﷺ) proceeded from there, he spared her a space behind him (on his shecamel) and put a screening veil between her and the people.","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ أَقَامَ النَّبِيُّ صلى الله عليه وسلم بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلاَثًا يُبْنَى عَلَيْهِ بِصَفِيَّةَ بِنْتِ حُيَىٍّ فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ فَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلاَ لَحْمٍ، أُمِرَ بِالأَنْطَاعِ فَأَلْقَى فِيهَا مِنَ التَّمْرِ وَالأَقِطِ وَالسَّمْنِ فَكَانَتْ وَلِيمَتَهُ، فَقَالَ الْمُسْلِمُونَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ أَوْ مِمَّا مَلَكَتْ يَمِينُهُ، فَقَالُوا إِنْ حَجَبَهَا فَهْىَ مِنْ أُمَّهَاتِ الْمُؤْمِنِينَ، وَإِنْ لَمْ يَحْجُبْهَا فَهْىَ مِمَّا مَلَكَتْ يَمِينُهُ، فَلَمَّا ارْتَحَلَ وَطَّى لَهَا خَلْفَهُ وَمَدَّ الْحِجَابَ بَيْنَهَا وَبَيْنَ النَّاسِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5105","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5105","x":"Ibn 'Abbas further said, \"Seven types of marriages are unlawful because of blood relations, and seven because of marriage relations.\" Then Ibn 'Abbas recited the Verse:\n\n\"Forbidden for you (for marriages) are your mothers...\" (4:23). 'Abdullah bin Ja'far married the daughter and wife of 'Ali at the same time (they were step-daughter and mother). Ibn Sirin said, \"There is no harm in that.\" But Al-Hasan Al-Basri disapproved of it at first, but then said that there was no harm in it. Al-Hasan bin Al-Hasan bin 'Ali married two of his cousins in one night. Ja'far bin Zaid disapproved of that because of it would bring hatred (between the two cousins), but it is not unlawful, as Allah said, \"Lawful to you are all others [beyond those (mentioned)]. (4:24). Ibn 'Abbas said: \"If somebody commits illegal sexual intercourse with his wife's sister, his wife does not become unlawful for him.\" And narrated Abu Ja'far, \"If a person commits homosexuality with a boy, then the mother of that boy is unlawful for him to marry.\" Narrated Ibn 'Abbas, \"If one commits illegal sexual intercourse with his mother in law, then his married relation to his wife does not become unlawful.\" Abu Nasr reported to have said that Ibn 'Abbas in the above case, regarded his marital relation to his wife unlawful, but Abu Nasr is not known well for hearing Hadith from Ibn 'Abbas. Imran bin Hussain, Jabir b. Zaid, Al-Hasan and some other Iraqi's, are reported to have judged that his marital relations to his wife would be unlawful. In the above case Abu Hurairah said, \"The marital relation to one's wife does not become unlawful except if one as had sexual intercourse (with her mother).\" Ibn Al-Musaiyab, 'Urwa, and Az-Zuhri allows such person to keep his wife. 'Ali said, \"His marital relations to his wife does not become unlawful.\"","ar":"وَقَالَ لَنَا أَحْمَدُ بْنُ حَنْبَلٍ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ سُفْيَانَ، حَدَّثَنِي حَبِيبٌ، عَنْ سَعِيدٍ، عَنِ ابْنِ عَبَّاسٍ، حَرُمَ مِنَ النَّسَبِ سَبْعٌ، وَمِنَ الصِّهْرِ سَبْعٌ‏.‏ ثُمَّ قَرَأَ ‏{‏حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ‏}‏ الآيَةَ‏.‏ وَجَمَعَ عَبْدُ اللَّهِ بْنُ جَعْفَرٍ بَيْنَ ابْنَةِ عَلِيٍّ وَامْرَأَةِ عَلِيٍّ‏.‏ وَقَالَ ابْنُ سِيرِينَ لاَ بَأْسَ بِهِ‏.‏ وَكَرِهَهُ الْحَسَنُ مَرَّةً ثُمَّ قَالَ لاَ بَأْسَ بِهِ‏.‏ وَجَمَعَ الْحَسَنُ بْنُ الْحَسَنِ بْنِ عَلِيٍّ بَيْنَ ابْنَتَىْ عَمٍّ فِي لَيْلَةٍ، وَكَرِهَهُ جَابِرُ بْنُ زَيْدٍ لِلْقَطِيعَةِ، وَلَيْسَ فِيهِ تَحْرِيمٌ لِقَوْلِهِ تَعَالَى ‏{‏وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ‏}‏ وَقَالَ عِكْرِمَةُ عَنِ ابْنِ عَبَّاسٍ إِذَا زَنَى بِأُخْتِ امْرَأَتِهِ لَمْ تَحْرُمْ عَلَيْهِ امْرَأَتُهُ‏.‏ وَيُرْوَى عَنْ يَحْيَى الْكِنْدِيِّ عَنِ الشَّعْبِيِّ وَأَبِي جَعْفَرٍ، فِيمَنْ يَلْعَبُ بِالصَّبِيِّ إِنْ أَدْخَلَهُ فِيهِ، فَلاَ يَتَزَوَّجَنَّ أُمَّهُ، وَيَحْيَى هَذَا غَيْرُ مَعْرُوفٍ، لَمْ يُتَابَعْ عَلَيْهِ‏.‏ وَقَالَ عِكْرِمَةُ عَنِ ابْنِ عَبَّاسٍ إِذَا زَنَى بِهَا لَمْ تَحْرُمْ عَلَيْهِ امْرَأَتُهُ‏.‏ وَيُذْكَرُ عَنْ أَبِي نَصْرٍ أَنَّ ابْنَ عَبَّاسٍ حَرَّمَهُ‏.‏ وَأَبُو نَصْرٍ هَذَا لَمْ يُعْرَفْ بِسَمَاعِهِ مِنِ ابْنِ عَبَّاسٍ‏.‏ وَيُرْوَى عَنْ عِمْرَانَ بْنِ حُصَيْنٍ وَجَابِرِ بْنِ زَيْدٍ وَالْحَسَنِ وَبَعْضِ أَهْلِ الْعِرَاقِ تَحْرُمُ عَلَيْهِ‏.‏ وَقَالَ أَبُو هُرَيْرَةَ لاَ تَحْرُمُ حَتَّى يُلْزِقَ بِالأَرْضِ يَعْنِي يُجَامِعَ‏.‏ وَجَوَّزَهُ ابْنُ الْمُسَيَّبِ وَعُرْوَةُ وَالزُّهْرِيُّ‏.‏ وَقَالَ الزُّهْرِيُّ قَالَ عَلِيٌّ لاَ تَحْرُمُ‏.‏ وَهَذَا مُرْسَلٌ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5169","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5169","x":"Narrated Anas:\n\nAllah's Messenger (ﷺ) manumitted Safiyya and then married her, and her Mahr was her manumission, and he gave a wedding banquet with Hais (a sort of sweet dish made from butter, cheese and dates).","ar":"حَدَّثَنَا مُسَدَّدٌ، عَنْ عَبْدِ الْوَارِثِ، عَنْ شُعَيْبٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَعْتَقَ صَفِيَّةَ، وَتَزَوَّجَهَا وَجَعَلَ عِتْقَهَا صَدَاقَهَا، وَأَوْلَمَ عَلَيْهَا بِحَيْسٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5387","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5387","x":"Narrated Anas:\n\nThe Prophet (ﷺ) halted to consummate his marriage with Safiyya. I invited the Muslims to his wedding banquet. He ordered that leather dining sheets be spread. Then dates, dried yoghurt and butter were put on those sheets. Anas added: The Prophet (ﷺ) consummated his marriage with Safiyya (during a journey) whereupon Hais (sweet dish) was served on a leather dining sheet.","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، أَخْبَرَنِي حُمَيْدٌ، أَنَّهُ سَمِعَ أَنَسًا، يَقُولُ قَامَ النَّبِيُّ صلى الله عليه وسلم يَبْنِي بِصَفِيَّةَ فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ أَمَرَ بِالأَنْطَاعِ فَبُسِطَتْ فَأُلْقِيَ عَلَيْهَا التَّمْرُ وَالأَقِطُ وَالسَّمْنُ‏.‏ وَقَالَ عَمْرٌو عَنْ أَنَسٍ بَنَى بِهَا النَّبِيُّ صلى الله عليه وسلم ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5425","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5425","x":"Narrated Anas bin Malik:\n\nAllah's Messenger (ﷺ) said to Abu Talha, \"Seek one of your boys to serve me.\" Abu Talha mounted me behind him (on his riding animal) and took me (to the Prophet (ﷺ) ). So I used to serve Allah's Messenger (ﷺ) whenever he dismounted (to stay somewhere). I used to hear him saying very often, \"O Allah! I seek refuge with You from, having worries sadness, helplessness, laziness, miserliness, cowardice, from being heavily in debt and from being overpowered by other persons unjustly.\" I kept on serving till we -returned from the battle of Khaibar. The Prophet (ﷺ) then brought Safiyya bint Huyai whom he had won from the war booty. I saw him folding up a gown or a garment for her to sit on behind him (on his shecamel). When he reached As-Sahba', he prepared Hais and placed it on a dining sheet. Then he sent me to invite men, who (came and) ate; and that was his and Safiyya's wedding banquet. Then the Prophet proceeded, and when he saw (noticed) the mountain of Uhud, he said, \"This mountain loves us, and we love it.\" When we approached Medina, he said, \"O Allah! I make the area between its two mountains a sanctuary as Abraham has made Mecca a sanctuary. O Allah! Bless their Mudd and Sa (special kinds of measure).","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، مَوْلَى الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ، يُرْدِفُنِي وَرَاءَهُ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم كُلَّمَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولَ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ فَلَمْ أَزَلْ أَخْدُمُهُ حَتَّى أَقْبَلْنَا مِنْ خَيْبَرَ، وَأَقْبَلَ بِصَفِيَّةَ بِنْتِ حُيَىٍّ قَدْ حَازَهَا، فَكُنْتُ أَرَاهُ يُحَوِّي وَرَاءَهُ بِعَبَاءَةٍ أَوْ بِكِسَاءٍ، ثُمَّ يُرْدِفُهَا وَرَاءَهُ، حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَنَعَ حَيْسًا فِي نِطَعٍ، ثُمَّ أَرْسَلَنِي فَدَعَوْتُ رِجَالاً فَأَكَلُوا، وَكَانَ ذَلِكَ بِنَاءَهُ بِهَا، ثُمَّ أَقْبَلَ حَتَّى إِذَا بَدَا لَهُ أُحُدٌ قَالَ ‏\"‏ هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ جَبَلَيْهَا مِثْلَ مَا حَرَّمَ بِهِ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6363","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6363","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said to Abu Talha, \"Choose one of your boys to serve me.\" So Abu Talha took me (to serve the Prophet (ﷺ) ) by giving me a ride behind him (on his camel). So I used to serve Allah's Messenger (ﷺ) whenever he stayed somewhere. I used to hear him saying, \"O Allah! I seek refuge with you (Allah) from (worries) care and grief, from incapacity and laziness, from miserliness and cowardice, from being heavily in debt and from being overpowered by other men.\" I kept on serving him till he returned from (the battle of) Khaibar. He then brought Safiya, the daughter of Huyay whom he had got (from the booty). I saw him making a kind of cushion with a cloak or a garment for her. He then let her ride behind him. When we reached a place called As-Sahba', he prepared (a special meal called) Hais, and asked me to invite the men who (came and) ate, and that was the marriage banquet given on the consummation of his marriage to her. Then he proceeded till the mountain of Uhud appeared, whereupon he said, \"This mountain loves us and we love it.\" When he approached Medina, he said, \"O Allah! I make the land between its (i.e., Medina's) two mountains a sanctuary, as the prophet Abraham made Mecca a sanctuary. O Allah! Bless them (the people of Medina) in their Mudd and the Sa' (units of measuring).","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، مَوْلَى الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ لَنَا غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ يُرْدِفُنِي وَرَاءَهُ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم كُلَّمَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولَ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ فَلَمْ أَزَلْ أَخْدُمُهُ حَتَّى أَقْبَلْنَا مِنْ خَيْبَرَ، وَأَقْبَلَ بِصَفِيَّةَ بِنْتِ حُيَىٍّ قَدْ حَازَهَا، فَكُنْتُ أَرَاهُ يُحَوِّي وَرَاءَهُ بِعَبَاءَةٍ أَوْ كِسَاءٍ ثُمَّ يُرْدِفُهَا وَرَاءَهُ حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَنَعَ حَيْسًا فِي نِطَعٍ، ثُمَّ أَرْسَلَنِي فَدَعَوْتُ رِجَالاً فَأَكَلُوا، وَكَانَ ذَلِكَ بِنَاءَهُ بِهَا، ثُمَّ أَقْبَلَ حَتَّى بَدَا لَهُ أُحُدٌ قَالَ ‏\"‏ هَذَا جُبَيْلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ جَبَلَيْهَا مِثْلَ مَا حَرَّمَ بِهِ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 28, Hadith 1123","u":"https://quranx.com/Hadith/Malik/In-Book/Book-28/Hadith-1123","x":"Yahya related to me from Malik from Yahya ibn Said that Said ibn al-Musayyab said, \"The slave girl is not married when there is a free woman who is a wife unless the free woman wishes it. If the free woman complies, she has two-thirds of the division of time.\" Malik said, \"A free man must not marry a slave-girl when he can afford to marry a free-woman, and he should not marry a slave-girl when he cannot afford a free woman unless he fears fornication. That is because Allah, may he be Blessed and Exalted, says in His Book, 'If you are not affluent enough to marry believing women, who are muhsanat, take slave-girls who are believing women that your right hands own.' (Sura 4 ayat 24) He says, 'That is for those of you who fear al-anat.' \" Malik said, \"Al-anat is fornication.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، أَنَّهُ كَانَ يَقُولُ لاَ تُنْكَحُ الأَمَةُ عَلَى الْحُرَّةِ إِلاَّ أَنْ تَشَاءَ الْحُرَّةُ فَإِنْ طَاعَتِ الْحُرَّةُ فَلَهَا الثُّلُثَانِ مِنَ الْقَسْمِ ‏.‏ قَالَ مَالِكٌ وَلاَ يَنْبَغِي لِحُرٍّ أَنْ يَتَزَوَّجَ أَمَةً وَهُوَ يَجِدُ طَوْلاً لِحُرَّةٍ وَلاَ يَتَزَوَّجَ أَمَةً إِذَا لَمْ يَجِدْ طَوْلاً لِحُرَّةٍ إِلاَّ أَنْ يَخْشَى الْعَنَتَ وَذَلِكَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ فِي كِتَابِهِ ‏{‏وَمَنْ لَمْ يَسْتَطِعْ مِنْكُمْ طَوْلاً أَنْ يَنْكِحَ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ فَمِمَّا مَلَكَتْ أَيْمَانُكُمْ مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ‏}‏ وَقَالَ ‏{‏ذَلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ‏}‏ قَالَ مَالِكٌ وَالْعَنَتُ هُوَ الزِّنَا ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1456a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1456a","x":"Abu Sa'id al-Khudri (Allah her pleased with him) reported that at the Battle of Hanain Allah's Messenger (ﷺ) sent an army to Autas and encountered the enemy and fought with them. Having overcome them and taken them captives, the Companions of Allah's Messenger (may peace te upon him) seemed to refrain from having intercourse with captive women because of their husbands being polytheists. Then Allah, Most High, sent down regarding that:\n\n\" And women already married, except those whom your right hands possess (iv. 24)\" (i. e. they were lawful for them when their 'Idda period came to an end).","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ الْقَوَارِيرِيُّ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا سَعِيدُ، بْنُ أَبِي عَرُوبَةَ عَنْ قَتَادَةَ، عَنْ صَالِحٍ أَبِي الْخَلِيلِ، عَنْ أَبِي عَلْقَمَةَ الْهَاشِمِيِّ، عَنْ أَبِي سَعِيدٍ، الْخُدْرِيِّ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم يَوْمَ حُنَيْنٍ بَعَثَ جَيْشًا إِلَى أَوْطَاسٍ فَلَقُوا عَدُوًّا فَقَاتَلُوهُمْ فَظَهَرُوا عَلَيْهِمْ وَأَصَابُوا لَهُمْ سَبَايَا فَكَأَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم تَحَرَّجُوا مِنْ غِشْيَانِهِنَّ مِنْ أَجْلِ أَزْوَاجِهِنَّ مِنَ الْمُشْرِكِينَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي ذَلِكَ ‏{‏ وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ‏}‏ أَىْ فَهُنَّ لَكُمْ حَلاَلٌ إِذَا انْقَضَتْ عِدَّتُهُنَّ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1456d","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1456d","x":"This hadith has been reported on the authority of AbuSa'id (al-Khudri) (Allah be pleased with him) through another chain of transmitters and the words are:\n\nThey took captives (women) on the day of Autas who had their husbands. They were afraid (to have sexual intercourse with them) when this verse was revealed:\" And women already married except those whom you right hands posses\" (iv. 24)","ar":"وَحَدَّثَنِيهِ يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ، حَدَّثَنَا خَالِدُ بْنُ الْحَارِثِ، حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَبِي الْخَلِيلِ، عَنْ أَبِي سَعِيدٍ، قَالَ أَصَابُوا سَبْيًا يَوْمَ أَوْطَاسٍ لَهُنَّ أَزْوَاجٌ فَتَخَوَّفُوا فَأُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏ وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ‏}‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 2, Book 9, Hadith 1132","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-2/Book-9/Hadith-1132","x":"Abu Sa'eed Al-Khudri narrated:\n\n\"We got some captives on the day of Awtas, and they had husbands among their peopled. They mentioned that to the Messenger of Allah, so the following was revealed: And women who are already married, except those whom your right hands posses.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، حَدَّثَنَا عُثْمَانُ الْبَتِّيُّ، عَنْ أَبِي الْخَلِيلِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ أَصَبْنَا سَبَايَا يَوْمَ أَوْطَاسٍ وَلَهُنَّ أَزْوَاجٌ فِي قَوْمِهِنَّ فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَنَزَلَتْ ‏:‏ ‏(‏وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَهَكَذَا رَوَاهُ الثَّوْرِيُّ عَنْ عُثْمَانَ الْبَتِّيِّ عَنْ أَبِي الْخَلِيلِ عَنْ أَبِي سَعِيدٍ ‏.‏ وَأَبُو الْخَلِيلِ اسْمُهُ صَالِحُ بْنُ أَبِي مَرْيَمَ ‏.‏ وَرَوَى هَمَّامٌ، هَذَا الْحَدِيثَ عَنْ قَتَادَةَ، عَنْ صَالِحٍ أَبِي الْخَلِيلِ، عَنْ أَبِي عَلْقَمَةَ الْهَاشِمِيِّ، عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ حَدَّثَنَا بِذَلِكَ عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا حَبَّانُ بْنُ هِلاَلٍ، حَدَّثَنَا هَمَّامٌ، ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3016","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3016","x":"Narrated Abu Sa'eed Al-Khudri:\n\n\"On the Day of Awtas, we captured some women who had husbands among the idolaters. So some of the men disliked that, so Allah, Most High, revealed: And women already married, except those whom your right hands possess... (4:24)\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا حَبَّانُ بْنُ هِلاَلٍ، حَدَّثَنَا هَمَّامُ بْنُ يَحْيَى، حَدَّثَنَا قَتَادَةُ، عَنْ أَبِي الْخَلِيلِ، عَنْ أَبِي عَلْقَمَةَ الْهَاشِمِيِّ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ لَمَّا كَانَ يَوْمُ أَوْطَاسٍ أَصَبْنَا نِسَاءً لَهُنَّ أَزْوَاجٌ فِي الْمُشْرِكِينَ فَكَرِهَهُنَّ رِجَالٌ مِنْهُمْ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3017","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3017","x":"Narrated Abu Sa'eed Al-Khudri:\n\n\"We captured some women on the Day of Awtas and they had husbands among their people. That was mentioned to the Messenger of Allah (ﷺ) so Allah revealed: '...And women already married, except those whom your right hands possess... (4:24)'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا عُثْمَانُ الْبَتِّيُّ، عَنْ أَبِي الْخَلِيلِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ أَصَبْنَا سَبَايَا يَوْمَ أَوْطَاسٍ لَهُنَّ أَزْوَاجٌ فِي قَوْمِهِنَّ فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَنَزَلَتْ ‏:‏ ‏(‏وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَهَكَذَا رَوَى الثَّوْرِيُّ عَنْ عُثْمَانَ الْبَتِّيِّ عَنْ أَبِي الْخَلِيلِ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ وَلَيْسَ فِي هَذَا الْحَدِيثِ عَنْ أَبِي عَلْقَمَةَ وَلاَ أَعْلَمُ أَنَّ أَحَدًا ذَكَرَ أَبَا عَلْقَمَةَ فِي هَذَا الْحَدِيثِ إِلاَّ مَا ذَكَرَ هَمَّامٌ عَنْ قَتَادَةَ وَأَبُو الْخَلِيلِ اسْمُهُ صَالِحُ بْنُ أَبِي مَرْيَمَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3214","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3214","x":"Narrated Umm Hani bint Abu Talib:\n\n\"The Messenger of Allah (ﷺ) proposed to me, but I asked him to excuse me. Then Allah [Most High] revealed: 'Verily We have made lawful to you your wives, to whom you have paid their due, and those whom your right hand possess - whom Allah has given to you, and the daughters of your paternal uncles, and the daughters of your paternal aunts, and the daughters of your maternal uncles, and the daughters of your maternal aunts, who migrated with you, and a believing woman if she offers herself to the Prophet... (33:50)' She said: \"So I was not lawful for him because I did not perform Hijrah; I was one of the Tulaqa (those that accepted Islam after the conquest of Makkah).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، عَنْ أَبِي صَالِحٍ، عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ، قَالَتْ خَطَبَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَاعْتَذَرْتُ إِلَيْهِ فَعَذَرَنِي ثُمَّ أَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏إنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللاَّتِي آتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّاتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَالاَتِكَ اللاَّتِي هَاجَرْنَ مَعَكَ وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ ‏)‏ الآيَةَ قَالَتْ فَلَمْ أَكُنْ أَحِلُّ لَهُ لأَنِّي لَمْ أُهَاجِرْ كُنْتُ مِنَ الطُّلَقَاءِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ السُّدِّيِّ ‏.‏","v":[]}],"29":[{"c":"Sunan Abu Dawud","r":"Hadith 3762","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3762","x":"Narrated Jabir ibn Abdullah:\n\nThe Messenger of Allah (ﷺ) came out from the valley of a mountain where he had eased himself. There were some dried dates on a shield before us. We called him and he ate with us. He did not touch water.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ أَبِي مَرْيَمَ، حَدَّثَنَا عَمِّي، - يَعْنِي سَعِيدَ بْنَ الْحَكَمِ - حَدَّثَنَا اللَّيْثُ بْنُ سَعْدٍ، أَخْبَرَنِي خَالِدُ بْنُ يَزِيدَ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ قَالَ أَقْبَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنْ شِعْبٍ مِنَ الْجَبَلِ وَقَدْ قَضَى حَاجَتَهُ وَبَيْنَ أَيْدِينَا تَمْرٌ عَلَى تُرْسٍ أَوْ حَجَفَةٍ فَدَعَوْنَاهُ فَأَكَلَ مَعَنَا وَمَا مَسَّ مَاءً ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1844a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1844a","x":"It has been narrated on the authority of 'Abd al-Rahman b. Abd Rabb al-Ka'ba who said:\n\nI entered the mosque when 'Abdullah b. 'Amr b. al-'As was sitting in the shade of the Ka'ba and the people had gathered around him. I betook myself to them and sat near him. (Now) Abdullah said: I accompanied the Messenger of Allah (ﷺ) on a journey. We halted at a place. Some of us began to set right their tents, others began to compete with one another in shooting, and others began to graze their beasts, when an announcer of the Messenger of Allah (ﷺ) announced that the people should gather together for prayer, so we gathered around the Messenger of Allah (ﷺ). He said: It was the duty of every Prophet that has gone before me to guide his followers to what he knew was good for them and warn them against what he knew was bad for them; but this Umma of yours has its days of peace and (security) in the beginning of its career, and in the last phase of its existence it will be afflicted with trials and with things disagreeable to you. (In this phase of the Umma), there will be tremendous trials one after the other, each making the previous one dwindle into insignificance. When they would be afflicted with a trial, the believer would say: This is going to bring about my destruction. When at (the trial) is over, they would be afflicted with another trial, and the believer would say: This surely is going to be my end. Whoever wishes to be delivered from the fire and enter the garden should die with faith in Allah and the Last Day and should treat the people as he wishes to be treated by them. He who swears allegiance to a Caliph should give him the piedge of his hand and the sincerity of his heart (i. e. submit to him both outwardly as well as inwardly). He should obey him to the best of his capacity. It another man comes forward (as a claimant to Caliphate), disputing his authority, they (the Muslims) should behead the latter. The narrator says: I came close to him ('Abdullah b. 'Amr b. al-'As) and said to him: Can you say on oath that you heard it from the Messenger of Allah (ﷺ)? He pointed with his hands to his ears and his heart and said: My ears heard it and my mind retained it. I said to him: This cousin of yours, Mu'awiya, orders us to unjustly consume our wealth among ourselves and to kill one another, while Allah says:\" O ye who believe, do not consume your wealth among yourselves unjustly, unless it be trade based on mutual agreement, and do not kill yourselves. Verily, God is Merciful to you\" (iv. 29). The narrator says that (hearing this) Abdullah b. 'Amr b. al-As kept quiet for a while and then said: Obey him in so far as he is obedient to God; and diqobey him in matters involving disobedience to God.","ar":"حَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ، زُهَيْرٌ حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ زَيْدِ بْنِ وَهْبٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ، قَالَ دَخَلْتُ الْمَسْجِدَ فَإِذَا عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ فَأَتَيْتُهُمْ فَجَلَسْتُ إِلَيْهِ فَقَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي سَفَرٍ فَنَزَلْنَا مَنْزِلاً فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ وَمِنَّا مَنْ يَنْتَضِلُ وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صلى الله عليه وسلم الصَّلاَةَ جَامِعَةً ‏.‏ فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ إِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلاَّ كَانَ حَقًّا عَلَيْهِ أَنْ يَدُلَّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ وَإِنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا وَسَيُصِيبُ آخِرَهَا بَلاَءٌ وَأُمُورٌ تُنْكِرُونَهَا وَتَجِيءُ فِتْنَةٌ فَيُرَقِّقُ بَعْضُهَا بَعْضًا وَتَجِيءُ الْفِتْنَةُ فَيَقُولُ الْمُؤْمِنُ هَذِهِ مُهْلِكَتِي ‏.‏ ثُمَّ تَنْكَشِفُ وَتَجِيءُ الْفِتْنَةُ فَيَقُولُ الْمُؤْمِنُ هَذِهِ هَذِهِ ‏.‏ فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ وَيَدْخُلَ الْجَنَّةَ فَلْتَأْتِهِ مَنِيَّتُهُ وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ وَثَمَرَةَ قَلْبِهِ فَلْيُطِعْهُ إِنِ اسْتَطَاعَ فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الآخَرِ ‏\"‏ ‏.‏ فَدَنَوْتُ مِنْهُ فَقُلْتُ لَهُ أَنْشُدُكَ اللَّهَ آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ وَقَالَ سَمِعَتْهُ أُذُنَاىَ وَوَعَاهُ قَلْبِي ‏.‏ فَقُلْتُ لَهُ هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ وَنَقْتُلَ أَنْفُسَنَا وَاللَّهُ يَقُولُ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلاَّ أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلاَ تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا‏}‏ قَالَ فَسَكَتَ سَاعَةً ثُمَّ قَالَ أَطِعْهُ فِي طَاعَةِ اللَّهِ وَاعْصِهِ فِي مَعْصِيَةِ اللَّهِ ‏.‏","v":[]}],"32":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3022","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3022","x":"Narrated Mujahid:\n\nfrom Umm Salamah that she said: \"The men fight and the women do not fight, and we only get half the inheritance.' So Allah, Blessed and Most High, revealed: 'And wish not for things in which Allah has made some of you excell over others... (4:32)' Mujahid said: \"And the following was revealed about that: 'Verily the Muslim men and the Muslim women... (33:35). And Umm Salamah was the first camel-borne woman to arrive in Al-Madinah as an emigrant.","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، عَنْ أُمِّ سَلَمَةَ، أَنَّهَا قَالَتْ يَغْزُو الرِّجَالُ وَلاَ يَغْزُو النِّسَاءُ وَإِنَّمَا لَنَا نِصْفُ الْمِيرَاثِ ‏.‏ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏وَلاَ تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ ‏)‏ ‏.‏ قَالَ مُجَاهِدٌ فَأُنْزِلَ فِيهَا ‏:‏ ‏(‏ إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ ‏)‏ وَكَانَتْ أُمُّ سَلَمَةَ أَوَّلَ ظَعِينَةٍ قَدِمَتِ الْمَدِينَةَ مُهَاجِرَةً ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ مُرْسَلٌ ‏.‏ وَرَوَاهُ بَعْضُهُمْ عَنِ ابْنِ أَبِي نَجِيحٍ عَنْ مُجَاهِدٍ مُرْسَلٌ أَنَّ أُمَّ سَلَمَةَ قَالَتْ كَذَا وَكَذَا ‏.‏","v":[]}],"33":[{"c":"Sunan Abu Dawud","r":"Hadith 2928","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2928","x":"Narrated 'Abdullah bin 'Umar:\n\nThe Messenger of Allah (ﷺ) as saying: Each of you is a shepherd and each of you is responsible for his flock. The amir (ruler) who is over the people is a shepherd and is responsible for his flock; a man is a shepherd in charge of the inhabitants of his household and he is responsible for his flock; a woman is a shepherdess in charge of her husband's house and children and she is responsible for them; and a man's slave is a shepherd in charge of his master's property and he is responsible for it. So each of you is a shepherd and each of you is responsible for his flock.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ أَلاَ كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ فَالأَمِيرُ الَّذِي عَلَى النَّاسِ رَاعٍ عَلَيْهِمْ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ بَعْلِهَا وَوَلَدِهِ وَهِيَ مَسْئُولَةٌ عَنْهُمْ وَالَعَبْدُ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهُوَ مَسْئُولٌ عَنْهُ فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2929","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2929","x":"Narrated 'Abd al-Rahman b. Samurah:\n\nThe Messenger of Allah (ﷺ) said to me: 'Abdul al-Rahman b. Samurah, do not ask for the position of commander, for if you are given it after asking you will be left to discharge it yourself, but if you are given it without asking you will be helped to discharge it.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ الْبَزَّازُ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا يُونُسُ، وَمَنْصُورٌ، عَنِ الْحَسَنِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، قَالَ قَالَ لِيَ النَّبِيُّ صلى الله عليه وسلم ‏\n\n\"‏ يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ لاَ تَسْأَلِ الإِمَارَةَ فَإِنَّكَ إِذَا أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ فِيهَا إِلَى نَفْسِكَ وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2292","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2292","x":"Narrated Sa`id bin Jubair:\n\nIbn `Abbas said, \"In the verse: To every one We have appointed ' (Muwaliya Muwaliya means one's) heirs (4.33).' (And regarding the verse) 'And those with whom your right hands have made a pledge.' Ibn `Abbas said, \"When the emigrants came to the Prophet (ﷺ) in Medina, the emigrant would inherit the Ansari while the latter's relatives would not inherit him because of the bond of brotherhood which the Prophet established between them (i.e. the emigrants and the Ansar). When the verse: 'And to everyone We have appointed heirs' (4.33) was revealed, it canceled (the bond (the pledge) of brotherhood regarding inheritance).\" Then he said, \"The verse: To those also to whom your right hands have pledged, remained valid regarding cooperation and mutual advice, while the matter of inheritance was excluded and it became permissible to assign something in one's testament to the person who had the right of inheriting before.","ar":"حَدَّثَنَا الصَّلْتُ بْنُ مُحَمَّدٍ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ إِدْرِيسَ، عَنْ طَلْحَةَ بْنِ مُصَرِّفٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما – ‏{‏وَلِكُلٍّ جَعَلْنَا مَوَالِيَ‏}‏ قَالَ وَرَثَةً ‏{‏وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ‏}‏ قَالَ كَانَ الْمُهَاجِرُونَ لَمَّا قَدِمُوا الْمَدِينَةَ يَرِثُ الْمُهَاجِرُ الأَنْصَارِيَّ دُونَ ذَوِي رَحِمِهِ لِلأُخُوَّةِ الَّتِي آخَى النَّبِيُّ صلى الله عليه وسلم بَيْنَهُمْ، فَلَمَّا نَزَلَتْ ‏{‏وَلِكُلٍّ جَعَلْنَا مَوَالِيَ‏}‏ نَسَخَتْ، ثُمَّ قَالَ ‏{‏وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ ‏}‏ إِلاَّ النَّصْرَ وَالرِّفَادَةَ وَالنَّصِيحَةَ، وَقَدْ ذَهَبَ الْمِيرَاثُ وَيُوصِي لَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4580","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4580","x":"Narrated Ibn `Abbas:\n\nRegarding the Verse: \"To everyone, We have appointed heirs.\" (4.33) 'Mawali' means heirs. And regarding:-- \"And those to whom your right hands have pledged.\" When the Emigrants came to Medina, an Emigrant used to be the heir of an Ansari with the exclusion of the latter's relatives, and that was because of the bond of brotherhood which the Prophet (ﷺ) had established between them (i.e. the Emigrants and the Ansar). So when the Verses:-- \"To everyone We have appointed heirs.\" was revealed, (the inheritance through bond of brotherhood) was cancelled. Ibn `Abbas then said: \"And those to whom your right hands have pledged.\" is concerned with the covenant of helping and advising each other. So allies are no longer to be the heir of each other, but they can bequeath each other some of their property by means of a will.","ar":"حَدَّثَنِي الصَّلْتُ بْنُ مُحَمَّدٍ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ إِدْرِيسَ، عَنْ طَلْحَةَ بْنِ مُصَرِّفٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاس ٍ ـ رضى الله عنهما ـ ‏{‏وَلِكُلٍّ جَعَلْنَا مَوَالِيَ‏}‏ قَالَ وَرَثَةً‏.‏ ‏{‏وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ‏}‏ كَانَ الْمُهَاجِرُونَ لَمَّا قَدِمُوا الْمَدِينَةَ يَرِثُ الْمُهَاجِرُ الأَنْصَارِيَّ دُونَ ذَوِي رَحِمِهِ لِلأُخُوَّةِ الَّتِي آخَى النَّبِيُّ صلى الله عليه وسلم بَيْنَهُمْ فَلَمَّا نَزَلَتْ ‏{‏وَلِكُلٍّ جَعَلْنَا مَوَالِيَ‏}‏ نُسِخَتْ، ثُمَّ قَالَ ‏{‏وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ ‏}‏ مِنَ النَّصْرِ، وَالرِّفَادَةِ وَالنَّصِيحَةِ، وَقَدْ ذَهَبَ الْمِيرَاثُ وَيُوصِي لَهُ‏.‏ سَمِعَ أَبُو أُسَامَةَ إِدْرِيسَ، وَسَمِعَ إِدْرِيسُ طَلْحَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6747","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6747","x":"Narrated Ibn `Abbas:\n\nRegarding the Holy Verse:--'And to everyone, We have appointed heirs..' And:-- (4.33) 'To those also to Whom your right hands have pledged.' (4.33) When the emigrants came to Medina, the Ansar used to be the heir of the emigrants (and vice versa) instead of their own kindred by blood (Dhawl-l-arham), and that was because of the bond of brotherhood which the Prophet (ﷺ) had established between them, i.e. the Ansar and the emigrants. But when the Divine Verse:-- 'And to everyone We have appointed heirs,' (4.33) was revealed, it cancelled the other, order i.e. 'To those also, to whom Your right hands have pledged.'","ar":"حَدَّثَنِي إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ قُلْتُ لأَبِي أُسَامَةَ حَدَّثَكُمْ إِدْرِيسُ، حَدَّثَنَا طَلْحَةُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، ‏{‏وَلِكُلٍّ جَعَلْنَا مَوَالِيَ‏}‏ ‏{‏وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ‏}‏ قَالَ كَانَ الْمُهَاجِرُونَ حِينَ قَدِمُوا الْمَدِينَةَ يَرِثُ الأَنْصَارِيُّ الْمُهَاجِرِيَّ دُونَ ذَوِي رَحِمِهِ لِلأُخُوَّةِ الَّتِي آخَى النَّبِيُّ صلى الله عليه وسلم بَيْنَهُمْ فَلَمَّا نَزَلَتْ ‏{‏جَعَلْنَا مَوَالِيَ‏}‏ قَالَ نَسَخَتْهَا ‏{‏وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ‏}‏","v":[]}],"34":[{"c":"Sahih Bukhari","r":"Hadith 334","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-334","x":"Narrated `Aisha:\n\n(the wife of the Prophet) We set out with Allah's Messenger (ﷺ) on one of his journeys till we reached Al- Baida' or Dhatul-Jaish, a necklace of mine was broken (and lost). Allah's Messenger (ﷺ) stayed there to search for it, and so did the people along with him. There was no water at that place, so the people went to Abu- Bakr As-Siddiq and said, \"Don't you see what `Aisha has done? She has made Allah's Apostle and the people stay where there is no water and they have no water with them.\" Abu Bakr came while Allah's Messenger (ﷺ) was sleeping with his head on my thigh, He said, to me: \"You have detained Allah's Messenger (ﷺ) and the people where there is no water and they have no water with them. So he admonished me and said what Allah wished him to say and hit me on my flank with his hand. Nothing prevented me from moving (because of pain) but the position of Allah's Messenger (ﷺ) on my thigh. Allah's Messenger (ﷺ) got up when dawn broke and there was no water. So Allah revealed the Divine Verses of Tayammum. So they all performed Tayammum. Usaid bin Hudair said, \"O the family of Abu Bakr! This is not the first blessing of yours.\" Then the camel on which I was riding was caused to move from its place and the necklace was found beneath it.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكٌ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم قَالَتْ خَرَجْنَا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي بَعْضِ أَسْفَارِهِ، حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ ـ أَوْ بِذَاتِ الْجَيْشِ ـ انْقَطَعَ عِقْدٌ لِي، فَأَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى الْتِمَاسِهِ، وَأَقَامَ النَّاسُ مَعَهُ، وَلَيْسُوا عَلَى مَاءٍ، فَأَتَى النَّاسُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ فَقَالُوا أَلاَ تَرَى مَا صَنَعَتْ عَائِشَةُ أَقَامَتْ بِرَسُولِ اللَّهِ صلى الله عليه وسلم وَالنَّاسِ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ‏.‏ فَجَاءَ أَبُو بَكْرٍ وَرَسُولُ اللَّهِ صلى الله عليه وسلم وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ فَقَالَ حَبَسْتِ رَسُولَ اللَّهِ صلى الله عليه وسلم وَالنَّاسَ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ‏.‏ فَقَالَتْ عَائِشَةُ فَعَاتَبَنِي أَبُو بَكْرٍ، وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ، وَجَعَلَ يَطْعُنُنِي بِيَدِهِ فِي خَاصِرَتِي، فَلاَ يَمْنَعُنِي مِنَ التَّحَرُّكِ إِلاَّ مَكَانُ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى فَخِذِي، فَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ أَصْبَحَ عَلَى غَيْرِ مَاءٍ، فَأَنْزَلَ اللَّهُ آيَةَ التَّيَمُّمِ فَتَيَمَّمُوا‏.‏ فَقَالَ أُسَيْدُ بْنُ الْحُضَيْرِ مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ أَبِي بَكْرٍ‏.‏ قَالَتْ فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ، فَأَصَبْنَا الْعِقْدَ تَحْتَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1052","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1052","x":"Narrated `Abdullah bin `Abbas:\n\nThe sun eclipsed in the lifetime of the Prophet (p.b.u.h). Allah's Messenger (ﷺ) offered the eclipse prayer and stood for a long period equal to the period in which one could recite Surat-al-Baqara. Then he bowed for a long time and then stood up for a long period which was shorter than that of the first standing, then bowed again for a long time but for a shorter period than the first; then he prostrated twice and then stood up for a long period which was shorter than that of the first standing; then he bowed for a long time which was shorter than the previous one, and then he raised his head and stood up for a long period which was shorter than the first standing, then he bowed for a long time which was shorter than the first bowing, and then prostrated (twice) and finished the prayer. By then, the sun (eclipse) had cleared. The Prophet (ﷺ) then said, \"The sun and the moon are two of the signs of Allah. They eclipse neither because of the death of somebody nor because of his life (i.e. birth). So when you see them, remember Allah.\" The people say, \"O Allah's Messenger (ﷺ)! We saw you taking something from your place and then we saw you retreating.\" The Prophet (ﷺ) replied, \"I saw Paradise and stretched my hands towards a bunch (of its fruits) and had I taken it, you would have eaten from it as long as the world remains. I also saw the Hell-fire and I had never seen such a horrible sight. I saw that most of the inhabitants were women.\" The people asked, \"O Allah's Messenger (ﷺ)! Why is it so?\" The Prophet (ﷺ) replied, \"Because of their ungratefulness.\" It was asked whether they are ungrateful to Allah. The Prophet said, \"They are ungrateful to their companions of life (husbands) and ungrateful to good deeds. If you are benevolent to one of them throughout the life and if she sees anything (undesirable) in you, she will say, 'I have never had any good from you.' \"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ انْخَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم، فَصَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم، فَقَامَ قِيَامًا طَوِيلاً نَحْوًا مِنْ قِرَاءَةِ سُورَةِ الْبَقَرَةِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ قَامَ قِيَامًا طَوِيلاً وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ انْصَرَفَ وَقَدْ تَجَلَّتِ الشَّمْسُ، فَقَالَ صلى الله عليه وسلم ‏\"‏ إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَاذْكُرُوا اللَّهَ ‏\"‏‏.‏ قَالُوا يَا رَسُولَ اللَّهِ، رَأَيْنَاكَ تَنَاوَلْتَ شَيْئًا فِي مَقَامِكَ، ثُمَّ رَأَيْنَاكَ كَعْكَعْتَ‏.‏ قَالَ صلى الله عليه وسلم ‏\"‏ إِنِّي رَأَيْتُ الْجَنَّةَ، فَتَنَاوَلْتُ عُنْقُودًا، وَلَوْ أَصَبْتُهُ لأَكَلْتُمْ مِنْهُ مَا بَقِيَتِ الدُّنْيَا، وَأُرِيتُ النَّارَ، فَلَمْ أَرَ مَنْظَرًا كَالْيَوْمِ قَطُّ أَفْظَعَ، وَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ ‏\"‏‏.‏ قَالُوا بِمَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ بِكُفْرِهِنَّ ‏\"‏‏.‏ قِيلَ يَكْفُرْنَ بِاللَّهِ قَالَ ‏\"‏ يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ كُلَّهُ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1462","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1462","x":"Narrated Abu Sa`id Al-Khudri:\n\nOn `Id ul Fitr or `Id ul Adha Allah's Messenger (ﷺ) (p.b.u.h) went out to the Musalla. After finishing the prayer, he delivered the sermon and ordered the people to give alms. He said, \"O people! Give alms.\" Then he went towards the women and said. \"O women! Give alms, for I have seen that the majority of the dwellers of Hell-Fire were you (women).\" The women asked, \"O Allah's Messenger (ﷺ)! What is the reason for it?\" He replied, \"O women! You curse frequently, and are ungrateful to your husbands. I have not seen anyone more deficient in intelligence and religion than you. O women, some of you can lead a cautious wise man astray.\" Then he left. And when he reached his house, Zainab, the wife of Ibn Mas`ud, came and asked permission to enter It was said, \"O Allah's Messenger (ﷺ)! It is Zainab.\" He asked, 'Which Zainab?\" The reply was that she was the wife of Ibn Mas'ub. He said, \"Yes, allow her to enter.\" And she was admitted. Then she said, \"O Prophet of Allah! Today you ordered people to give alms and I had an ornament and intended to give it as alms, but Ibn Mas`ud said that he and his children deserved it more than anybody else.\" The Prophet (ﷺ) replied, \"Ibn Mas`ud had spoken the truth. Your husband and your children had more right to it than anybody else.\"","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ أَخْبَرَنِي زَيْدٌ، عَنْ عِيَاضِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ـ رضى الله عنه ـ خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي أَضْحًى أَوْ فِطْرٍ إِلَى الْمُصَلَّى ثُمَّ انْصَرَفَ فَوَعَظَ النَّاسَ وَأَمَرَهُمْ بِالصَّدَقَةِ فَقَالَ ‏\"‏ أَيُّهَا النَّاسُ تَصَدَّقُوا ‏\"‏‏.‏ فَمَرَّ عَلَى النِّسَاءِ فَقَالَ ‏\"‏ يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ ‏\"‏‏.‏ فَقُلْنَ وَبِمَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ تُكْثِرْنَ اللَّعْنَ وَتَكْفُرْنَ الْعَشِيرَ، مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ الْحَازِمِ مِنْ إِحْدَاكُنَّ يَا مَعْشَرَ النِّسَاءِ ‏\"‏‏.‏ ثُمَّ انْصَرَفَ فَلَمَّا صَارَ إِلَى مَنْزِلِهِ جَاءَتْ زَيْنَبُ امْرَأَةُ ابْنِ مَسْعُودٍ تَسْتَأْذِنُ عَلَيْهِ فَقِيلَ يَا رَسُولَ اللَّهِ هَذِهِ زَيْنَبُ فَقَالَ ‏\"‏ أَىُّ الزَّيَانِبِ ‏\"‏‏.‏ فَقِيلَ امْرَأَةُ ابْنِ مَسْعُودٍ‏.‏ قَالَ ‏\"‏ نَعَمِ ائْذَنُوا لَهَا ‏\"‏‏.‏ فَأُذِنَ لَهَا قَالَتْ يَا نَبِيَّ اللَّهِ إِنَّكَ أَمَرْتَ الْيَوْمَ بِالصَّدَقَةِ، وَكَانَ عِنْدِي حُلِيٌّ لِي، فَأَرَدْتُ أَنْ أَتَصَدَّقَ بِهِ، فَزَعَمَ ابْنُ مَسْعُودٍ أَنَّهُ وَوَلَدَهُ أَحَقُّ مَنْ تَصَدَّقْتُ بِهِ عَلَيْهِمْ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ صَدَقَ ابْنُ مَسْعُودٍ، زَوْجُكِ وَوَلَدُكِ أَحَقُّ مَنْ تَصَدَّقْتِ بِهِ عَلَيْهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1862","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1862","x":"Narrated Ibn `Abbas:\n\nThe Prophet (ﷺ) said, \"A woman should not travel except with a Dhu-Mahram (her husband or a man with whom that woman cannot marry at all according to the Islamic Jurisprudence), and no man may visit her except in the presence of a Dhu-Mahram.\" A man got up and said, \"O Allah's Messenger (ﷺ)! I intend to go to such and such an army and my wife wants to perform Hajj.\" The Prophet (ﷺ) said (to him), \"Go along with her (to Hajj).","ar":"حَدَّثَنَا أَبُو النُّعْمَانِ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ عَمْرٍو، عَنْ أَبِي مَعْبَدٍ، مَوْلَى ابْنِ عَبَّاسٍ عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ لاَ تُسَافِرِ الْمَرْأَةُ إِلاَّ مَعَ ذِي مَحْرَمٍ، وَلاَ يَدْخُلُ عَلَيْهَا رَجُلٌ إِلاَّ وَمَعَهَا مَحْرَمٌ ‏\"‏‏.‏ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ أَخْرُجَ فِي جَيْشِ كَذَا وَكَذَا، وَامْرَأَتِي تُرِيدُ الْحَجَّ‏.‏ فَقَالَ ‏\"‏ اخْرُجْ مَعَهَا ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2450","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2450","x":"Narrated Aisha:\n\nRegarding the explanation of the following verse:-- \"If a wife fears Cruelty or desertion On her husband's part.\" (4.128) A man may dislike his wife and intend to divorce her, so she says to him, \"I give up my rights, so do not divorce me.\" The above verse was revealed concerning such a case.","ar":"حَدَّثَنَا مُحَمَّدٌ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏ قَالَتِ الرَّجُلُ تَكُونُ عِنْدَهُ الْمَرْأَةُ، لَيْسَ بِمُسْتَكْثِرٍ مِنْهَا، يُرِيدُ أَنْ يُفَارِقَهَا، فَتَقُولُ أَجْعَلُكَ مِنْ شَأْنِي فِي حِلٍّ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2559","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2559","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"If somebody fights (or beats somebody) then he should avoid the face.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ، حَدَّثَنَا ابْنُ وَهْبٍ، قَالَ حَدَّثَنِي مَالِكُ بْنُ أَنَسٍ، قَالَ وَأَخْبَرَنِي ابْنُ فُلاَنٍ، عَنْ سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم وَحَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنْ هَمَّامٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبِ الْوَجْهَ ‏\"\n\n‏‏.‏","v":[]}],"35":[{"c":"Muwatta Malik","r":"Book 29, Hadith 1233","u":"https://quranx.com/Hadith/Malik/In-Book/Book-29/Hadith-1233","x":"Yahya related to me from Malik that he had heard that Ali ibn Abi Talib said about the two arbiters about whom Allah, the Exalted, said,\"If you fear a breach between the two, appoint an arbiter from his people, and an arbiter from her people. If they desire to set things aright, Allah will make peace between them, surely Allah is Knowing, Aware,\" (Sura 4 ayat 35), that the separation and the joining were overseen by the two of them. Malik said, \"That is the best of what I have heard from the people of knowledge. Whatever the two arbiters say concerning separation or joining is taken into consideration \"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ، قَالَ فِي الْحَكَمَيْنِ اللَّذَيْنِ قَالَ اللَّهُ تَعَالَى ‏{‏وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلاَحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا‏}‏ إِنَّ إِلَيْهِمَا الْفُرْقَةَ بَيْنَهُمَا وَالاِجْتِمَاعَ ‏.‏ قَالَ مَالِكٌ وَذَلِكَ أَحْسَنُ مَا سَمِعْتُ مِنْ أَهْلِ الْعِلْمِ أَنَّ الْحَكَمَيْنِ يَجُوزُ قَوْلُهُمَا بَيْنَ الرَّجُلِ وَامْرَأَتِهِ فِي الْفُرْقَةِ وَالاِجْتِمَاعِ ‏.‏","v":[]}],"40":[{"c":"Sahih Bukhari","r":"Hadith 7439","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7439","x":"Narrated Abu Sa'id Al-Khudri:\n\nWe said, \"O Allah's Messenger (ﷺ)! Shall we see our Lord on the Day of Resurrection?\" He said, \"Do you have any difficulty in seeing the sun and the moon when the sky is clear?\" We said, \"No.\" He said, \"So you will have no difficulty in seeing your Lord on that Day as you have no difficulty in seeing the sun and the moon (in a clear sky).\" The Prophet then said, \"Somebody will then announce, 'Let every nation follow what they used to worship.' So the companions of the cross will go with their cross, and the idolators (will go) with their idols, and the companions of every god (false deities) (will go) with their god, till there remain those who used to worship Allah, both the obedient ones and the mischievous ones, and some of the people of the Scripture. Then Hell will be presented to them as if it were a mirage. Then it will be said to the Jews, \"What did you use to worship?' They will reply, 'We used to worship Ezra, the son of Allah.' It will be said to them, 'You are liars, for Allah has neither a wife nor a son. What do you want (now)?' They will reply, 'We want You to provide us with water.' Then it will be said to them 'Drink,' and they will fall down in Hell (instead). Then it will be said to the Christians, 'What did you use to worship?' They will reply, 'We used to worship Messiah, the son of Allah.' It will be said, 'You are liars, for Allah has neither a wife nor a son. What: do you want (now)?' They will say, 'We want You to provide us with water.' It will be said to them, 'Drink,' and they will fall down in Hell (instead). When there remain only those who used to worship Allah (Alone), both the obedient ones and the mischievous ones, it will be said to them, 'What keeps you here when all the people have gone?' They will say, 'We parted with them (in the world) when we were in greater need of them than we are today, we heard the call of one proclaiming, 'Let every nation follow what they used to worship,' and now we are waiting for our Lord.' Then the Almighty will come to them in a shape other than the one which they saw the first time, and He will say, 'I am your Lord,' and they will say, 'You are not our Lord.' And none will speak: to Him then but the Prophets, and then it will be said to them, 'Do you know any sign by which you can recognize Him?' They will say. 'The Shin,' and so Allah will then uncover His Shin whereupon every believer will prostrate before Him and there will remain those who used to prostrate before Him just for showing off and for gaining good reputation. These people will try to prostrate but their backs will be rigid like one piece of a wood (and they will not be able to prostrate). Then the bridge will be laid across Hell.\" We, the companions of the Prophet (ﷺ) said, \"O Allah's Messenger (ﷺ)! What is the bridge?' He said, \"It is a slippery (bridge) on which there are clamps and (Hooks like) a thorny seed that is wide at one side and narrow at the other and has thorns with bent ends. Such a thorny seed is found in Najd and is called As-Sa'dan. Some of the believers will cross the bridge as quickly as the wink of an eye, some others as quick as lightning, a strong wind, fast horses or she-camels. So some will be safe without any harm; some will be safe after receiving some scratches, and some will fall down into Hell (Fire). The last person will cross by being dragged (over the bridge).\" The Prophet (ﷺ) said, \"You (Muslims) cannot be more pressing in claiming from me a right that has been clearly proved to be yours than the believers in interceding with Almighty for their (Muslim) brothers on that Day, when they see themselves safe. They will say, 'O Allah! (Save) our brothers (for they) used to pray with us, fast with us and also do good deeds with us.' Allah will say, 'Go and take out (of Hell) anyone in whose heart you find faith equal to the weight of one (gold) Dinar.' Allah will forbid the Fire to burn the faces of those sinners. They will go to them and find some of them in Hell (Fire) up to their feet, and some up to the middle of their legs. So they will take out those whom they will recognize and then they will return, and Allah will say (to them), 'Go and take out (of Hell) anyone in whose heart you find faith equal to the weight of one half Dinar.' They will take out whomever they will recognize and return, and then Allah will say, 'Go and take out (of Hell) anyone in whose heart you find faith equal to the weight of an atom (or a smallest ant), and so they will take out all those whom they will recognize.\" Abu Sa'id said: If you do not believe me then read the Holy Verse:-- 'Surely! Allah wrongs not even of the weight of an atom (or a smallest ant) but if there is any good (done) He doubles it.' (4.40) The Prophet added, \"Then the prophets and Angels and the believers will intercede, and (last of all) the Almighty (Allah) will say, 'Now remains My Intercession. He will then hold a handful of the Fire from which He will take out some people whose bodies have been burnt, and they will be thrown into a river at the entrance of Paradise, called the water of life. They will grow on its banks, as a seed carried by the torrent grows. You have noticed how it grows beside a rock or beside a tree, and how the side facing the sun is usually green while the side facing the shade is white. Those people will come out (of the River of Life) like pearls, and they will have (golden) necklaces, and then they will enter Paradise whereupon the people of Paradise will say, 'These are the people emancipated by the Beneficent. He has admitted them into Paradise without them having done any good deeds and without sending forth any good (for themselves).' Then it will be said to them, 'For you is what you have seen and its equivalent as well.'\"","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ خَالِدِ بْنِ يَزِيدَ، عَنْ سَعِيدِ بْنِ أَبِي هِلاَلٍ، عَنْ زَيْدٍ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قُلْنَا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ قَالَ ‏\"‏ هَلْ تُضَارُونَ فِي رُؤْيَةِ الشَّمْسِ وَالْقَمَرِ إِذَا كَانَتْ صَحْوًا ‏\"‏‏.‏ قُلْنَا لاَ‏.‏ قَالَ ‏\"‏ فَإِنَّكُمْ لاَ تُضَارُونَ فِي رُؤْيَةِ رَبِّكُمْ يَوْمَئِذٍ، إِلاَّ كَمَا تُضَارُونَ فِي رُؤْيَتِهِمَا ـ ثُمَّ قَالَ ـ يُنَادِي مُنَادٍ لِيَذْهَبْ كُلُّ قَوْمٍ إِلَى مَا كَانُوا يَعْبُدُونَ‏.‏ فَيَذْهَبُ أَصْحَابُ الصَّلِيبِ مَعَ صَلِيبِهِمْ، وَأَصْحَابُ الأَوْثَانِ مَعَ أَوْثَانِهِمْ، وَأَصْحَابُ كُلِّ آلِهَةٍ مَعَ آلِهَتِهِمْ حَتَّى يَبْقَى مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ أَوْ فَاجِرٍ، وَغُبَّرَاتٌ مِنْ أَهْلِ الْكِتَابِ، ثُمَّ يُؤْتَى بِجَهَنَّمَ تُعْرَضُ كَأَنَّهَا سَرَابٌ فَيُقَالُ لِلْيَهُودِ مَا كُنْتُمْ تَعْبُدُونَ قَالُوا كُنَّا نَعْبُدُ عُزَيْرَ ابْنَ اللَّهِ‏.‏ فَيُقَالُ كَذَبْتُمْ لَمْ يَكُنْ لِلَّهِ صَاحِبَةٌ وَلاَ وَلَدٌ فَمَا تُرِيدُونَ قَالُوا نُرِيدُ أَنْ تَسْقِيَنَا، فَيُقَالُ اشْرَبُوا فَيَتَسَاقَطُونَ فِي جَهَنَّمَ ثُمَّ يُقَالُ لِلنَّصَارَى مَا كُنْتُمْ تَعْبُدُونَ فَيَقُولُونَ كُنَّا نَعْبُدُ الْمَسِيحَ ابْنَ اللَّهِ‏.‏ فَيُقَالُ كَذَبْتُمْ لَمْ يَكُنْ لِلَّهِ صَاحِبَةٌ وَلاَ وَلَدٌ، فَمَا تُرِيدُونَ فَيَقُولُونَ نُرِيدُ أَنْ تَسْقِيَنَا‏.‏ فَيُقَالُ اشْرَبُوا‏.‏ فَيَتَسَاقَطُونَ حَتَّى يَبْقَى مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ أَوْ فَاجِرٍ فَيُقَالُ لَهُمْ مَا يَحْبِسُكُمْ وَقَدْ ذَهَبَ النَّاسُ فَيَقُولُونَ فَارَقْنَاهُمْ وَنَحْنُ أَحْوَجُ مِنَّا إِلَيْهِ الْيَوْمَ وَإِنَّا سَمِعْنَا مُنَادِيًا يُنَادِي لِيَلْحَقْ كُلُّ قَوْمٍ بِمَا كَانُوا يَعْبُدُونَ‏.‏ وَإِنَّمَا نَنْتَظِرُ رَبَّنَا ـ قَالَ ـ فَيَأْتِيهِمُ الْجَبَّارُ‏.‏ فَيَقُولُ أَنَا رَبُّكُمْ‏.‏ فَيَقُولُونَ أَنْتَ رَبُّنَا‏.‏ فَلاَ يُكَلِّمُهُ إِلاَّ الأَنْبِيَاءُ فَيَقُولُ هَلْ بَيْنَكُمْ وَبَيْنَهُ آيَةٌ تَعْرِفُونَهُ فَيَقُولُونَ السَّاقُ‏.‏ فَيَكْشِفُ عَنْ سَاقِهِ فَيَسْجُدُ لَهُ كُلُّ مُؤْمِنٍ، وَيَبْقَى مَنْ كَانَ يَسْجُدُ لِلَّهِ رِيَاءً وَسُمْعَةً، فَيَذْهَبُ كَيْمَا يَسْجُدَ فَيَعُودُ ظَهْرُهُ طَبَقًا وَاحِدًا، ثُمَّ يُؤْتَى بِالْجَسْرِ فَيُجْعَلُ بَيْنَ ظَهْرَىْ جَهَنَّمَ ‏\"‏‏.‏ قُلْنَا يَا رَسُولَ اللَّهِ وَمَا الْجَسْرُ قَالَ ‏\"‏ مَدْحَضَةٌ مَزِلَّةٌ، عَلَيْهِ خَطَاطِيفُ وَكَلاَلِيبُ وَحَسَكَةٌ مُفَلْطَحَةٌ، لَهَا شَوْكَةٌ عُقَيْفَاءُ تَكُونُ بِنَجْدٍ يُقَالُ لَهَا السَّعْدَانُ، الْمُؤْمِنُ عَلَيْهَا كَالطَّرْفِ وَكَالْبَرْقِ وَكَالرِّيحِ وَكَأَجَاوِيدِ الْخَيْلِ وَالرِّكَابِ، فَنَاجٍ مُسَلَّمٌ وَنَاجٍ مَخْدُوشٌ وَمَكْدُوسٌ فِي نَارِ جَهَنَّمَ، حَتَّى يَمُرَّ آخِرُهُمْ يُسْحَبُ سَحْبًا، فَمَا أَنْتُمْ بِأَشَدَّ لِي مُنَاشَدَةً فِي الْحَقِّ، قَدْ تَبَيَّنَ لَكُمْ مِنَ الْمُؤْمِنِ يَوْمَئِذٍ لِلْجَبَّارِ، وَإِذَا رَأَوْا أَنَّهُمْ قَدْ نَجَوْا فِي إِخْوَانِهِمْ يَقُولُونَ رَبَّنَا إِخْوَانُنَا كَانُوا يُصَلُّونَ مَعَنَا وَيَصُومُونَ مَعَنَا وَيَعْمَلُونَ مَعَنَا‏.‏ فَيَقُولُ اللَّهُ تَعَالَى اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ‏.‏ وَيُحَرِّمُ اللَّهُ صُوَرَهُمْ عَلَى النَّارِ، فَيَأْتُونَهُمْ وَبَعْضُهُمْ قَدْ غَابَ فِي النَّارِ إِلَى قَدَمِهِ وَإِلَى أَنْصَافِ سَاقَيْهِ، فَيُخْرِجُونَ مَنْ عَرَفُوا، ثُمَّ يَعُودُونَ فَيَقُولُ اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ فَأَخْرِجُوهُ‏.‏ فَيُخْرِجُونَ مَنْ عَرَفُوا، ثُمَّ يَعُودُونَ فَيَقُولُ اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ‏.‏ فَيُخْرِجُونَ مَنْ عَرَفُوا ‏\"‏‏.‏ قَالَ أَبُو سَعِيدٍ فَإِنْ لَمْ تُصَدِّقُونِي فَاقْرَءُوا ‏{‏إِنَّ اللَّهَ لاَ يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا‏}‏ ‏\"‏ فَيَشْفَعُ النَّبِيُّونَ وَالْمَلاَئِكَةُ وَالْمُؤْمِنُونَ فَيَقُولُ الْجَبَّارُ بَقِيَتْ شَفَاعَتِي‏.‏ فَيَقْبِضُ قَبْضَةً مِنَ النَّارِ فَيُخْرِجُ أَقْوَامًا قَدِ امْتُحِشُوا، فَيُلْقَوْنَ فِي نَهَرٍ بِأَفْوَاهِ الْجَنَّةِ يُقَالُ لَهُ مَاءُ الْحَيَاةِ، فَيَنْبُتُونَ فِي حَافَتَيْهِ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ، قَدْ رَأَيْتُمُوهَا إِلَى جَانِبِ الصَّخْرَةِ إِلَى جَانِبِ الشَّجَرَةِ، فَمَا كَانَ إِلَى الشَّمْسِ مِنْهَا كَانَ أَخْضَرَ، وَمَا كَانَ مِنْهَا إِلَى الظِّلِّ كَانَ أَبْيَضَ، فَيَخْرُجُونَ كَأَنَّهُمُ اللُّؤْلُؤُ، فَيُجْعَلُ فِي رِقَابِهِمُ الْخَوَاتِيمُ فَيَدْخُلُونَ الْجَنَّةَ فَيَقُولُ أَهْلُ الْجَنَّةِ هَؤُلاَءِ عُتَقَاءُ الرَّحْمَنِ أَدْخَلَهُمُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ وَلاَ خَيْرٍ قَدَّمُوهُ‏.‏ فَيُقَالُ لَهُمْ لَكُمْ مَا رَأَيْتُمْ وَمِثْلُهُ مَعَهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 183a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-183a","x":"Abu Sa'id al-Khudri reported:\n\nSome people during the lifetime of the Messenger of Allah (ﷺ) said: Messenger of Allah! shall we see our Lord on the Day of Resurrection? The Messenger of Allah (ﷺ) said: Yes, and added: Do you feel any trouble in seeing the sun at noon with no cloud over it, and do you feel trouble in seeing the moon (open) in the full moonlit night with no cloud over it? They said: No, Messenger of Allah! He (the Holy Prophet) said: You will not feel any trouble in seeing Allah on the Day of Resurrection any more than you do in seeing any one of them. When the Day of Resurrection comes a Mu'adhdhin (a proclaimer) would proclaim: Let every people follow what they used to worship. Then all who worshipped idols and stones besides Allah would fall into the Fire, till only the righteous and the vicious and some of the people of the Book who worshipped Allah are left. Then the Jews would be summoned, and it would be said to them: What did you worship? They will say: We worshipped 'Uzair, son of Allah. It would be said to them: You tell a lie; Allah had never had a spouse or a son. What do you want now? They would say: We feel thirsty, O our Lord! Quench our thirst. They would be directed (to a certain direction) and asked: Why don't you go there to drink water? Then they would be pushed towards the Fire (and they would find to their great dismay that) it was but a mirage (and the raging flames of fire) would be consuming one another, and they would fall into the Fire. Then the Christians would be summoned and it would be said to them: What did you worship? They would say: We worshipped Jesus, son of Allah. It would be said to them: You tell a lie; Allah did not take for Himself either a spouse or a son. Then it would be said to them: What do you want? They would say: Thirsty we are, O our Lord! Quench our thirst. They would be directed (to a certain direction) and asked: Why don't you go there to get water? But they would be pushed and gathered together towards the Hell, which was like a mirage to them, and the flames would consume one another. They would fall Into the Fire, till no one is left except he who worshipped Allah, be he pious or sinful. The Lord of the Universe, Glorified and Exalted, would come to them in a form recognisable to them and say; What are you looking for? Every people follow that which they worshipped. They would say: Our Lord, we kept ourselves separate from the people in the world, though we felt great need of them; we, however, did not associate ourselves with them. He would say: I am your Lord. They would say: We take refuge with Allah from thee and do not associate anything with Allah. They would repeat it twice or thrice, till some of them would be about to return. It would be said: Is there any sign between you and Him by which you will recognise Him? They would say: Yes. and the things would be laid bare. Those who used to prostrate themselves before God of their own accord would be permitted by God to prostrate themselves. But there would remain none who used to prostrate out of fear (of people) and ostentation but Allah would make his back as one piece, and whenever he would attempt to prostrate he would fall on his back. Then they would raise their heads and He would assume the Form in which they had seen Him the first time and would say: I am your Lord. They would say: Thou art our Lord. Then the bridge would be set up over the Hell and intercession would be allowed and they will say: O God, keep safe, keep safe. It was asked: Messenger of Allah, what is this bridge? He said: The void in which one Is likely to slip. There would be hooks, tongs, spits like the thorn that is found in Najd and is known as Sa'dan. The believers would then pass over within the twinkling of an eye, like lightning, like wind, like a bird, like the finest horses and camels. Some will escape and be safe, some will be lacerated and let go, and some will be pushed into the fire of Hell till the believers will find rescue from the Fire. By One in Whose hand is my life, there will be none among you more eager to claim a right than the believers on the Day of Resurrection for (saying their) brethren in the Fire who would say: O our Lord, they were fasting along with us, and praying and performing pilgrimage. It will be said to them: Take out those whom you recognise. Then their persons would be forbidden to the Fire; and they would take out a large number of people who had been overtaken by Fire up to the middle of the shank or up to the knees. They would then say: O our Lord I not one of those about whom Thou didst give us command remains in it. He will then say: Go back and bring out those in whose hearts you find good of the weight of a dinar Then they will take out a large number of people. Then they would say: O our Lord! we have not left anyone about whom You commanded us. He will then say: Go back and bring out those in whose hearts you find as much as half a dinar of good. Then they will take out a large number of people, and would say: O our Lord! not one of those about whom Thou commanded us we have left in it. Then He would say: Go back and in whose heart you find good to the weight of a particle bring him out. They would bring out a large number of people, and would then say: O our Lord, now we have not left anyone in it (Hell) having any good in him. Abu Sa'id Khudri said: If you don't testify me in this hadith, then recite if you like:\" Surely Allah wrongs not the weight of an atom; and if it is a good deed. He multiplies it and gives from Himself a great reward\" (al-Qur'an, iv. 40). Then Allah, Exalted and Great, would say: The angels have interceded, the apostles have interceded and the believers have interceded, and no one remains (to grant pardon) but the Most Merciful of the mercifuls. He will then take a handful from Fire and bring out from it people who never did any good and who had been turned into charcoal, and will cast them into a river called the river of life, on the outskirts of Paradise. They will come out as a seed comes cut from the silt carried by flood. You see it near the stone or near the tree. That which is exposed to the sun is yellowish or greenish and which is under the shade is white. They said: Messenger of Allah! it seems as if you had been tending a flock in the jungle. He (the Holy Prophet) said: They will come forth like pearls with seals on their necks. The inhabitants of Paradise would recognise them (and say): Those are who have been set free by the Compassionate One. Who has admitted them into Paradise without any (good) deed that they did or any good that they sent in advance Then He would say: Enter the Paradise; whatever you see in it is yours. They would say: O Lord, Thou hast bestowed upon us (favours) which Thou didst not bestow upon anyone else in the world. He would say: There is with Me (a favour) for you better than this. They would say: O our Lord! which thing is better than this? He would say: It is My pleasure. I will never be angry with you after this","ar":"وَحَدَّثَنِي سُوَيْدُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنِي حَفْصُ بْنُ مَيْسَرَةَ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ نَاسًا، فِي زَمَنِ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالُوا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قَالَ ‏\"‏ هَلْ تُضَارُّونَ فِي رُؤْيَةِ الشَّمْسِ بِالظَّهِيرَةِ صَحْوًا لَيْسَ مَعَهَا سَحَابٌ وَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ صَحْوًا لَيْسَ فِيهَا سَحَابٌ ‏\"‏ ‏.‏ قَالُوا لاَ يَا رَسُولَ اللَّهِ ‏.‏ قَالَ ‏\"‏ مَا تُضَارُّونَ فِي رُؤْيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ إِلاَّ كَمَا تُضَارُّونَ فِي رُؤْيَةِ أَحَدِهِمَا إِذَا كَانَ يَوْمُ الْقِيَامَةِ أَذَّنَ مُؤَذِّنٌ لِيَتَّبِعْ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ ‏.‏ فَلاَ يَبْقَى أَحَدٌ كَانَ يَعْبُدُ غَيْرَ اللَّهِ سُبْحَانَهُ مِنَ الأَصْنَامِ وَالأَنْصَابِ إِلاَّ يَتَسَاقَطُونَ فِي النَّارِ حَتَّى إِذَا لَمْ يَبْقَ إِلاَّ مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ وَفَاجِرٍ وَغُبَّرِ أَهْلِ الْكِتَابِ فَيُدْعَى الْيَهُودُ فَيُقَالُ لَهُمْ مَا كُنْتُمْ تَعْبُدُونَ قَالُوا كُنَّا نَعْبُدُ عُزَيْرَ ابْنَ اللَّهِ ‏.‏ فَيُقَالُ كَذَبْتُمْ مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلاَ وَلَدٍ فَمَاذَا تَبْغُونَ قَالُوا عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا ‏.‏ فَيُشَارُ إِلَيْهِمْ أَلاَ تَرِدُونَ فَيُحْشَرُونَ إِلَى النَّارِ كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا فَيَتَسَاقَطُونَ فِي النَّارِ ‏.‏ ثُمَّ يُدْعَى النَّصَارَى فَيُقَالُ لَهُمْ مَا كُنْتُمْ تَعْبُدُونَ قَالُوا كُنَّا نَعْبُدُ الْمَسِيحَ ابْنَ اللَّهِ ‏.‏ فَيُقَالُ لَهُمْ كَذَبْتُمْ ‏.‏ مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلاَ وَلَدٍ ‏.‏ فَيُقَالُ لَهُمْ مَاذَا تَبْغُونَ فَيَقُولُونَ عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا ‏.‏ - قَالَ - فَيُشَارُ إِلَيْهِمْ أَلاَ تَرِدُونَ فَيُحْشَرُونَ إِلَى جَهَنَّمَ كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا فَيَتَسَاقَطُونَ فِي النَّارِ حَتَّى إِذَا لَمْ يَبْقَ إِلاَّ مَنْ كَانَ يَعْبُدُ اللَّهَ تَعَالَى مِنْ بَرٍّ وَفَاجِرٍ أَتَاهُمْ رَبُّ الْعَالَمِينَ سُبْحَانَهُ وَتَعَالَى فِي أَدْنَى صُورَةٍ مِنَ الَّتِي رَأَوْهُ فِيهَا ‏.‏ قَالَ فَمَا تَنْتَظِرُونَ تَتْبَعُ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ ‏.‏ قَالُوا يَا رَبَّنَا فَارَقْنَا النَّاسَ فِي الدُّنْيَا أَفْقَرَ مَا كُنَّا إِلَيْهِمْ وَلَمْ نُصَاحِبْهُمْ ‏.‏ فَيَقُولُ أَنَا رَبُّكُمْ ‏.‏ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ لاَ نُشْرِكُ بِاللَّهِ شَيْئًا - مَرَّتَيْنِ أَوْ ثَلاَثًا - حَتَّى إِنَّ بَعْضَهُمْ لَيَكَادُ أَنْ يَنْقَلِبَ ‏.‏ فَيَقُولُ هَلْ بَيْنَكُمْ وَبَيْنَهُ آيَةٌ فَتَعْرِفُونَهُ بِهَا فَيَقُولُونَ نَعَمْ ‏.‏ فَيُكْشَفُ عَنْ سَاقٍ فَلاَ يَبْقَى مَنْ كَانَ يَسْجُدُ لِلَّهِ مِنْ تِلْقَاءِ نَفْسِهِ إِلاَّ أَذِنَ اللَّهُ لَهُ بِالسُّجُودِ وَلاَ يَبْقَى مَنْ كَانَ يَسْجُدُ اتِّقَاءً وَرِيَاءً إِلاَّ جَعَلَ اللَّهُ ظَهْرَهُ طَبَقَةً وَاحِدَةً كُلَّمَا أَرَادَ أَنْ يَسْجُدَ خَرَّ عَلَى قَفَاهُ ‏.‏ ثُمَّ يَرْفَعُونَ رُءُوسَهُمْ وَقَدْ تَحَوَّلَ فِي صُورَتِهِ الَّتِي رَأَوْهُ فِيهَا أَوَّلَ مَرَّةٍ فَقَالَ أَنَا رَبُّكُمْ ‏.‏ فَيَقُولُونَ أَنْتَ رَبُّنَا ‏.‏ ثُمَّ يُضْرَبُ الْجِسْرُ عَلَى جَهَنَّمَ وَتَحِلُّ الشَّفَاعَةُ وَيَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ ‏\"‏ ‏.‏ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْجِسْرُ قَالَ ‏\"‏ دَحْضٌ مَزِلَّةٌ ‏.‏ فِيهِ خَطَاطِيفُ وَكَلاَلِيبُ وَحَسَكٌ تَكُونُ بِنَجْدٍ فِيهَا شُوَيْكَةٌ يُقَالُ لَهَا السَّعْدَانُ فَيَمُرُّ الْمُؤْمِنُونَ كَطَرْفِ الْعَيْنِ وَكَالْبَرْقِ وَكَالرِّيحِ وَكَالطَّيْرِ وَكَأَجَاوِيدِ الْخَيْلِ وَالرِّكَابِ فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ مُرْسَلٌ وَمَكْدُوسٌ فِي نَارِ جَهَنَّمَ ‏.‏ حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ فَوَالَّذِي نَفْسِي بِيَدِهِ مَا مِنْكُمْ مِنْ أَحَدٍ بِأَشَدَّ مُنَاشَدَةً لِلَّهِ فِي اسْتِقْصَاءِ الْحَقِّ مِنَ الْمُؤْمِنِينَ لِلَّهِ يَوْمَ الْقِيَامَةِ لإِخْوَانِهِمُ الَّذِينَ فِي النَّارِ يَقُولُونَ رَبَّنَا كَانُوا يَصُومُونَ مَعَنَا وَيُصَلُّونَ وَيَحُجُّونَ ‏.‏ فَيُقَالُ لَهُمْ أَخْرِجُوا مَنْ عَرَفْتُمْ ‏.‏ فَتُحَرَّمُ صُوَرُهُمْ عَلَى النَّارِ فَيُخْرِجُونَ خَلْقًا كَثيرًا قَدْ أَخَذَتِ النَّارُ إِلَى نِصْفِ سَاقَيْهِ وَإِلَى رُكْبَتَيْهِ ثُمَّ يَقُولُونَ رَبَّنَا مَا بَقِيَ فِيهَا أَحَدٌ مِمَّنْ أَمَرْتَنَا بِهِ ‏.‏ فَيَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ ‏.‏ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ نَذَرْ فِيهَا أَحَدًا مِمَّنْ أَمَرْتَنَا ‏.‏ ثُمَّ يَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ ‏.‏ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ نَذَرْ فِيهَا مِمَّنْ أَمَرْتَنَا أَحَدًا ‏.‏ ثُمَّ يَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ ‏.‏ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ نَذَرْ فِيهَا خَيْرًا ‏\"‏ ‏.‏ وَكَانَ أَبُو سَعِيدٍ الْخُدْرِيُّ يَقُولُ إِنْ لَمْ تُصَدِّقُونِي بِهَذَا الْحَدِيثِ فَاقْرَءُوا إِنْ شِئْتُمْ ‏{‏ إِنَّ اللَّهَ لاَ يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا‏}‏ ‏\"‏ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ شَفَعَتِ الْمَلاَئِكَةُ وَشَفَعَ النَّبِيُّونَ وَشَفَعَ الْمُؤْمِنُونَ وَلَمْ يَبْقَ إِلاَّ أَرْحَمُ الرَّاحِمِينَ فَيَقْبِضُ قَبْضَةً مِنَ النَّارِ فَيُخْرِجُ مِنْهَا قَوْمًا لَمْ يَعْمَلُوا خَيْرًا قَطُّ قَدْ عَادُوا حُمَمًا فَيُلْقِيهِمْ فِي نَهْرٍ فِي أَفْوَاهِ الْجَنَّةِ يُقَالُ لَهُ نَهْرُ الْحَيَاةِ فَيَخْرُجُونَ كَمَا تَخْرُجُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ أَلاَ تَرَوْنَهَا تَكُونُ إِلَى الْحَجَرِ أَوْ إِلَى الشَّجَرِ مَا يَكُونُ إِلَى الشَّمْسِ أُصَيْفِرُ وَأُخَيْضِرُ وَمَا يَكُونُ مِنْهَا إِلَى الظِّلِّ يَكُونُ أَبْيَضَ ‏\"‏ ‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ كَأَنَّكَ كُنْتَ تَرْعَى بِالْبَادِيَةِ قَالَ ‏\"‏ فَيَخْرُجُونَ كَاللُّؤْلُؤِ فِي رِقَابِهِمُ الْخَوَاتِمُ يَعْرِفُهُمْ أَهْلُ الْجَنَّةِ هَؤُلاَءِ عُتَقَاءُ اللَّهِ الَّذِينَ أَدْخَلَهُمُ اللَّهُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ وَلاَ خَيْرٍ قَدَّمُوهُ ثُمَّ يَقُولُ ادْخُلُوا الْجَنَّةَ فَمَا رَأَيْتُمُوهُ فَهُوَ لَكُمْ ‏.‏ فَيَقُولُونَ رَبَّنَا أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنَ الْعَالَمِينَ ‏.‏ فَيَقُولُ لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا فَيَقُولُونَ يَا رَبَّنَا أَىُّ شَىْءٍ أَفْضَلُ مِنْ هَذَا ‏.‏ فَيَقُولُ رِضَاىَ فَلاَ أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا ‏\"‏ ‏.‏","v":[]}],"41":[{"c":"Sahih Bukhari","r":"Hadith 4582","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4582","x":"Narrated `Abdullah bin Masud:\n\nAllah's Messenger (ﷺ) said to me, \"Recite (of the Qur'an) for me,\" I said, \"Shall I recite it to you although it had been revealed to you?\" He said, \"I like to hear (the Qur'an) from others.\" So I recited Surat-an- Nisa' till I reached: \"How (will it be) then when We bring from each nation a witness, and We bring you (O Muhammad) as a witness against these people?\" (4.41) Then he said, \"Stop!\" And behold, his eyes were overflowing with tears.\"","ar":"حَدَّثَنَا صَدَقَةُ، أَخْبَرَنَا يَحْيَى، عَنْ سُفْيَانَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَبِيدَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ يَحْيَى بَعْضُ الْحَدِيثِ عَنْ عَمْرِو بْنِ مُرَّةَ، قَالَ قَالَ لِي النَّبِيُّ صلى الله عليه وسلم ‏\"‏ اقْرَأْ عَلَىَّ ‏\"‏‏.‏ قُلْتُ آقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏\"‏ فَإِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي ‏\"‏‏.‏ فَقَرَأْتُ عَلَيْهِ سُورَةَ النِّسَاءِ حَتَّى بَلَغْتُ ‏{‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا‏}‏ قَالَ ‏\"‏ أَمْسِكْ ‏\"‏‏.‏ فَإِذَا عَيْنَاهُ تَذْرِفَانِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5050","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5050","x":"Narrated `Abdullah bin Mas`ud:\n\nThe Prophet (ﷺ) said to me, \"Recite (the Qur'an) to me.\" I said, \"O Allah's Messenger (ﷺ) Shall I recite (the Qur'an) to you while it has been revealed to you?\" He said, \"Yes.\" So I recited Surat-An-Nisa' (The Women), but when I recited the Verse: 'How (will it be) then when We bring from each nation a witness and We bring you (O Muhammad) as a witness against these people.' (4.41) He said, \"Enough for the present,\" I looked at him and behold! His eyes were overflowing with tears","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبِيدَةَ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ لِي النَّبِيُّ صلى الله عليه وسلم ‏\"‏ اقْرَأْ عَلَىَّ ‏\"‏‏.‏ قُلْتُ يَا رَسُولَ اللَّهِ آقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏\"‏ نَعَمْ ‏\"‏‏.‏ فَقَرَأْتُ سُورَةَ النِّسَاءِ حَتَّى أَتَيْتُ إِلَى هَذِهِ الآيَةِ ‏{‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا‏}‏ قَالَ ‏\"‏ حَسْبُكَ الآنَ ‏\"‏‏.‏ فَالْتَفَتُّ إِلَيْهِ فَإِذَا عَيْنَاهُ تَذْرِفَانِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5055","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5055","x":"Narrated `Abdullah (bin Mas`ud):\n\nAllah's Messenger (ﷺ) said (to me), \"Recite the Qur'an to me.\" I said, \"Shall I recite (it) to you while it has been revealed to you?\" He said, \"I like to hear it from another person.\" So I recited Surat An-Nisa (The Women) till I reached the Verse: 'How (will it be) then when We bring from each nation a witness, and We bring you (O Muhammad) as a witness against these people.' (4.41) Then he said to me, \"Stop!\" Thereupon I saw his eyes overflowing with tears.","ar":"حَدَّثَنَا صَدَقَةُ، أَخْبَرَنَا يَحْيَى، عَنْ سُفْيَانَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَبِيدَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ يَحْيَى بَعْضُ الْحَدِيثِ عَنْ عَمْرِو بْنِ مُرَّةَ، قَالَ لِي النَّبِيُّ صلى الله عليه وسلم‏.‏ ـ حَدَّثَنَا مُسَدَّدٌ عَنْ يَحْيَى عَنْ سُفْيَانَ عَنِ الأَعْمَشِ عَنْ إِبْرَاهِيمَ عَنْ عَبِيدَةَ عَنْ عَبْدِ اللَّهِ قَالَ الأَعْمَشُ وَبَعْضُ الْحَدِيثِ حَدَّثَنِي عَمْرُو بْنُ مُرَّةَ عَنْ إِبْرَاهِيمَ وَعَنْ أَبِيهِ عَنْ أَبِي الضُّحَى عَنْ عَبْدِ اللَّهِ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اقْرَأْ عَلَىَّ ‏\"‏‏.‏ قَالَ قُلْتُ أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏\"‏ إِنِّي أَشْتَهِي أَنْ أَسْمَعَهُ مِنْ غَيْرِي ‏\"‏‏.‏ قَالَ فَقَرَأْتُ النِّسَاءَ حَتَّى إِذَا بَلَغْتُ ‏{‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا‏}‏‏.‏ قَالَ لِي ‏\"‏ كُفَّ ـ أَوْ أَمْسِكْ ـ ‏\"‏‏.‏ فَرَأَيْتُ عَيْنَيْهِ تَذْرِفَانِ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4194","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4194","x":"It was narrated that ‘Abdullah said:\n\n\"The Prophet (ﷺ) said to me: ‘Recite Qur’an to me,’ so I recited Surat An-Nisa’ to him, and when I reached (the Verse): \"How (will it be) then, when We bring forth from each nation a witness and We bring you as a witness against these people?\" [4:41] I looked at him, and his eyes were filled with tears.\"","ar":"حَدَّثَنَا هَنَّادُ بْنُ السَّرِيِّ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ قَالَ لِيَ النَّبِيُّ ـ صلى الله عليه وسلم ـ ‏\"‏ اقْرَأْ عَلَىَّ ‏\"‏ ‏.‏ فَقَرَأْتُ عَلَيْهِ بِسُورَةِ النِّسَاءِ حَتَّى إِذَا بَلَغْتُ ‏{فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا}‏ فَنَظَرْتُ إِلَيْهِ فَإِذَا عَيْنَاهُ تَدْمَعَانِ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 446","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-446","x":"Ibn Mas'ud (May Allah be pleased with him) reported:\n\nThe Prophet (ﷺ) said to me: \"Recite the Qur'an to me\". I said, \"O Messenger of Allah! Shall I recite the Qur'an to you, when it has been revealed to you?\" He (ﷺ) replied, \"I love to hear it recited by others\". So I recited to him a portion from Surat An-Nisa'. When I reached the Ayah:\"How (will it be) then, when We bring from each nation a witness and We bring you (O Muhammad (ﷺ)) as a witness against these people?\". (4:41)He (ﷺ) said, \"Enough for now\". When I looked at him I saw his eyes were shedding tears.[Al- Bukhari and Muslim].","ar":"وعن ابن مسعود، رضي الله عنه ، قال‏:‏ قال لي النبي، صلى الله عليه وسلم، \"اقرأ علي القرآن\" قلت‏:‏ يا رسول الله أقرأ عليك وعليك أنزل ‏؟‏‏!‏ قال‏:‏‏\"‏إنى أحب أن أسمعه من غيري\" فقرأت عليه سورة النساء، حتى جئت إلى هذه الآية ‏(‏فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيداً‏}‏ ‏(‏‏(‏النساء‏:‏41‏)‏‏)‏ قال‏:‏ ‏\"‏حسبك الآن‏\"‏ فالتفت إليه، فإذا عيناه تذرفان ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏","v":[]},{"c":"Shama'il Muhammadiyah","r":"Hadith 322","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-322","x":"'Abdu’llah ibn Mas'ud said (may Allah be well pleased with him):\n\n\"Allah’s Messenger (Allah bless him and give him peace) told me: ‘Recite the Qur’an to me,’ so I said: ‘O Messenger of Allah, shall I recite the Qur’an to you when it was to you that it was revealed?’ He said: ‘I like to hear it from someone other than myself,’ so I recited the Sura of the Women [Surat an-Nisa’] until the place that reads: And We bring you as a witness against these [wa ji'na bi-ka 'ala ha'ula'i shahida]' (Al-Qur'an; 4:41). Then I saw the eyes of Allah’s Messenger bathed in tears.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلانَ، قَالَ‏:‏ حَدَّثَنَا مُعَاوِيَةُ بْنُ هِشَامٍ، قَالَ‏:‏ حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنِ إِبْرَاهِيمَ، عَنْ عُبَيْدَةَ، عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ، قَالَ‏:‏ قَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم‏:‏ اقْرَأْ عَلَيَّ فَقُلْتُ‏:‏ يَا رَسُولَ اللهِ، أَقَرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ، قَالَ‏:‏ إِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي، فَقَرَأْتُ سُورَةَ النِّسَاءِ، حَتَّى بَلَغْتُ وَجِئِنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا، قَالَ‏:‏ فَرَأَيْتُ عَيْنَيْ رَسُولِ اللهِ تَهْمِلانِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3024","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3024","x":"Narrated 'Alqamah:\n\n\"'Abdullah said: 'The Messenger of Allah (ﷺ) commanded me to recite for him while he was on the Minbar. So I recited from Surat An-Nisa for him, until I reached: How then (will it be) when We bring from each nation a witness, and We bring you (Muhammad) as a witness against these people? (4:41) The Messenger of Allah (ﷺ) was beckoning me (to stop) with his hand, and I looked at him and his eyes were flowing with tears.\"","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، قَالَ قَالَ عَبْدُ اللَّهِ أَمَرَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ أَقْرَأَ عَلَيْهِ وَهُوَ عَلَى الْمِنْبَرِ ‏.‏ فَقَرَأْتُ عَلَيْهِ مِنْ سُورَةِ النِّسَاءِ حَتَّى إِذَا بَلَغْتُ‏:‏ ‏(‏ فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا ‏)‏ غَمَزَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم بِيَدِهِ فَنَظَرْتُ إِلَيْهِ وَعَيْنَاهُ تَدْمَعَانِ ‏.‏ قَالَ أَبُو عِيسَى هَكَذَا رَوَى أَبُو الأَحْوَصِ عَنِ الأَعْمَشِ عَنْ إِبْرَاهِيمَ عَنْ عَلْقَمَةَ عَنْ عَبْدِ اللَّهِ وَإِنَّمَا هُوَ إِبْرَاهِيمُ عَنْ عَبِيدَةَ عَنْ عَبْدِ اللَّهِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3025","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3025","x":"Narrated Ibrahim:\n\nfrom 'Abidah that 'Abdullah said: \"The Messenger of Allah (ﷺ) said to me: 'Recite for me.' I said: 'O Messenger of Allah! Shall I recite for you while it is to you whom it was revealed?' He said: 'I love to hear it from other than me.'\" So I recited Surat An-Nisa until I reached: \"...And We bring you (Muhammad) as a witness against these people? (4:41)\" He said: \"So I saw the eyes of the Prophet (ﷺ) overflowing with tears.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا مُعَاوِيَةُ بْنُ هِشَامٍ، حَدَّثَنَا سُفْيَانُ الثَّوْرِيُّ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبِيدَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اقْرَأْ عَلَىَّ ‏\"‏ ‏.‏ فَقُلْتُ يَا رَسُولَ اللَّهِ أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏\"‏ إِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي ‏\"‏ ‏.‏ فَقَرَأْتُ سُورَةَ النِّسَاءِ حَتَّى إِذَا بَلَغْتُ ‏:‏ ‏(‏جِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا ‏)‏ قَالَ فَرَأَيْتُ عَيْنَىِ النَّبِيِّ صلى الله عليه وسلم تَهْمِلاَنِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا أَصَحُّ مِنْ حَدِيثِ أَبِي الأَحْوَصِ ‏.‏","v":[]}],"43":[{"c":"Sunan Abu Dawud","r":"Hadith 3678","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3678","x":"Abu Hurairah b. Bashir reported the Apostel of Allah (ﷺ)as saying:\n\nWine comes from these two trees, the date-palm and the grapes-vine. Abu Dawud said : The name of Abu KAthir al-Ubari is Yazid b. ‘Abd al-Rahman b. Ghufailat al-Sahmi. Some said: Uzainah. What is correct is Ghufailah.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، حَدَّثَنِي يَحْيَى، عَنْ أَبِي كَثِيرٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏\"\n\n‏ ‏.‏ قَالَ أَبُو دَاوُدَ اسْمُ أَبِي كَثِيرٍ الْغُبَرِيِّ يَزِيدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ غُفَيْلَةَ السَّحْمِيُّ ‏.‏ وَقَالَ بَعْضُهُمْ أُذَيْنَةُ وَالصَّوَابُ غُفَيْلَةُ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 3679","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3679","x":"Ibn ‘Umar reported the Apostel of Allah (ﷺ) as saying:\n\nEvery intoxicant is forbidden. He who drinks wine in this world, and dies when he is addiction to it, will not drink it in the next.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ دَاوُدَ، وَمُحَمَّدُ بْنُ عِيسَى، - فِي آخَرِينَ - قَالُوا حَدَّثَنَا حَمَّادٌ، - يَعْنِي ابْنَ زَيْدٍ - عَنْ أَيُّوبَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ وَمَنْ مَاتَ وَهُوَ يَشْرَبُ الْخَمْرَ يُدْمِنُهَا لَمْ يَشْرَبْهَا فِي الآخِرَةِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 3680","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3680","x":"Narrated Abdullah Ibn Abbas:\n\nThe Messenger of Allah (ﷺ) said: Every intoxicant is khamr (wine) and every intoxicant is forbidden. If anyone drinks wine, Allah will not accept prayer from him for forty days, but if he repents, Allah will accept his repentance. If he repeats it a fourth time, it is binding on Allah that He will give him tinat al-khabal to drink. He was asked: What is tinat al-khabal, Messenger of Allah? He replied: Discharge of wounds, flowing from the inhabitants of Hell. If anyone serves it to a minor who does not distinguish between the lawful and the unlawful, it is binding on Allah that He will give him to drink the discharge of wounds, flowing from the inhabitants of Hell.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ رَافِعٍ النَّيْسَابُورِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ عُمَرَ الصَّنْعَانِيُّ، قَالَ سَمِعْتُ النُّعْمَانَ، يَقُولُ عَنْ طَاوُسٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ كُلُّ مُخَمِّرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ وَمَنْ شَرِبَ مُسْكِرًا بُخِسَتْ صَلاَتُهُ أَرْبَعِينَ صَبَاحًا فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ فَإِنْ عَادَ الرَّابِعَةَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ ‏\"‏ ‏.‏ قِيلَ وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ صَدِيدُ أَهْلِ النَّارِ وَمَنْ سَقَاهُ صَغِيرًا لاَ يَعْرِفُ حَلاَلَهُ مِنْ حَرَامِهِ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ ‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 242","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-242","x":"Narrated Aisha:\n\nThe Prophet (ﷺ) said, \"All drinks that produce intoxication are Haram (forbidden to drink).","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا سُفْيَانُ، قَالَ حَدَّثَنَا الزُّهْرِيُّ، عَنْ أَبِي سَلَمَةَ، عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 334","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-334","x":"Narrated `Aisha:\n\n(the wife of the Prophet) We set out with Allah's Messenger (ﷺ) on one of his journeys till we reached Al- Baida' or Dhatul-Jaish, a necklace of mine was broken (and lost). Allah's Messenger (ﷺ) stayed there to search for it, and so did the people along with him. There was no water at that place, so the people went to Abu- Bakr As-Siddiq and said, \"Don't you see what `Aisha has done? She has made Allah's Apostle and the people stay where there is no water and they have no water with them.\" Abu Bakr came while Allah's Messenger (ﷺ) was sleeping with his head on my thigh, He said, to me: \"You have detained Allah's Messenger (ﷺ) and the people where there is no water and they have no water with them. So he admonished me and said what Allah wished him to say and hit me on my flank with his hand. Nothing prevented me from moving (because of pain) but the position of Allah's Messenger (ﷺ) on my thigh. Allah's Messenger (ﷺ) got up when dawn broke and there was no water. So Allah revealed the Divine Verses of Tayammum. So they all performed Tayammum. Usaid bin Hudair said, \"O the family of Abu Bakr! This is not the first blessing of yours.\" Then the camel on which I was riding was caused to move from its place and the necklace was found beneath it.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكٌ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم قَالَتْ خَرَجْنَا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي بَعْضِ أَسْفَارِهِ، حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ ـ أَوْ بِذَاتِ الْجَيْشِ ـ انْقَطَعَ عِقْدٌ لِي، فَأَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى الْتِمَاسِهِ، وَأَقَامَ النَّاسُ مَعَهُ، وَلَيْسُوا عَلَى مَاءٍ، فَأَتَى النَّاسُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ فَقَالُوا أَلاَ تَرَى مَا صَنَعَتْ عَائِشَةُ أَقَامَتْ بِرَسُولِ اللَّهِ صلى الله عليه وسلم وَالنَّاسِ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ‏.‏ فَجَاءَ أَبُو بَكْرٍ وَرَسُولُ اللَّهِ صلى الله عليه وسلم وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ فَقَالَ حَبَسْتِ رَسُولَ اللَّهِ صلى الله عليه وسلم وَالنَّاسَ، وَلَيْسُوا عَلَى مَاءٍ، وَلَيْسَ مَعَهُمْ مَاءٌ‏.‏ فَقَالَتْ عَائِشَةُ فَعَاتَبَنِي أَبُو بَكْرٍ، وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ، وَجَعَلَ يَطْعُنُنِي بِيَدِهِ فِي خَاصِرَتِي، فَلاَ يَمْنَعُنِي مِنَ التَّحَرُّكِ إِلاَّ مَكَانُ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى فَخِذِي، فَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ أَصْبَحَ عَلَى غَيْرِ مَاءٍ، فَأَنْزَلَ اللَّهُ آيَةَ التَّيَمُّمِ فَتَيَمَّمُوا‏.‏ فَقَالَ أُسَيْدُ بْنُ الْحُضَيْرِ مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ أَبِي بَكْرٍ‏.‏ قَالَتْ فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ، فَأَصَبْنَا الْعِقْدَ تَحْتَهُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3026","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3026","x":"Narrated Abu 'Abdur-Rahman As-Sulami:\n\nthat 'Ali bin Abi Talib said: \"'Abdur-Rahman bin 'Awf prepared some food for which he invited us, and he gave us some wine to drink. The wine began to affect us when it was time for Salat. So they encouraged me (to lead) and I recited: 'Say: O you disbelievers! I do not worship what you worship, and we worship what you worship' - so Allah, Most High, revealed: O you who believe! Do not approach Salat when you are in a drunken state until you know what you are saying (4:43).\"","ar":"حَدَّثَنَا سُوَيْدُ بْنُ نَصْرٍ، أَخْبَرَنَا ابْنُ الْمُبَارَكِ، عَنْ سُفْيَانَ، عَنِ الأَعْمَشِ، نَحْوَ حَدِيثِ مُعَاوِيَةَ بْنِ هِشَامٍ ‏.‏ حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ سَعْدٍ، عَنْ أَبِي جَعْفَرٍ الرَّازِيِّ، عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ صَنَعَ لَنَا عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ طَعَامًا فَدَعَانَا وَسَقَانَا مِنَ الْخَمْرِ فَأَخَذَتِ الْخَمْرُ مِنَّا وَحَضَرَتِ الصَّلاَةُ فَقَدَّمُونِي فَقَرَأْتُ ‏:‏ ‏(‏ قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏)‏ لاَ أَعْبُدُ مَا تَعْبُدُونَ وَنَحْنُ نَعْبُدُ مَا تَعْبُدُونَ ‏.‏ قَالَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَقْرَبُوا الصَّلاَةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3049","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3049","x":"Narrated 'Amr bin Shurahbil [Abu Maisarah]:\n\nfrom 'Umar bin Al-Khattab, that he said: \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in Al-Baqarah was revealed: They ask you concerning Khamr and gambling. Say: \"In them is a great sin (2:219).\" So 'Umar was called, and it was recited to him, so he said: \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in An-Nisa was revealed: 'O you who believe! Approach not As-Salat while you are in a drunken state (4:43).' So 'Umar was called and it was recited him, so he said \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in Al-Ma'idah was revealed: Shaitan only wants to excite enmity and hatred between you with Khamr and gambling...' up to His saying: 'So will you not then abstain (5:91).' So 'Umar was called and it was recited to him, so he said: 'We abstained, we abstained.'\" Abü Maisarah narrated from 'Umar bin Al-Khattab who said: \"0 Allah! Make the verdict concerning Khamr sufficiently clear for us!\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ، أَخْبَرَنَا مُحَمَّدُ بْنُ يُوسُفَ، أَخْبَرَنَا إِسْرَائِيلُ، حَدَّثَنَا أَبُو إِسْحَاقَ، عَنْ عُمَرَ بْنِ شُرَحْبِيلَ أَبِي مَيْسَرَةَ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، أَنَّهُ قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي الْبَقَرَةِ ‏:‏ ‏(‏ يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ ‏)‏ الآيَةَ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي النِّسَاءِأَيُّهَا الَّذِينَ آمَنُوا لاَ تَقْرَبُوا الصَّلاَةَ وَأَنْتُمْ سُكَارَى ‏)‏ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي الْمَائِدَةِ ‏:‏ ‏(‏ إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ ‏)‏ إِلَى قَوْلِهَِ ( فَهَلْ أَنْتُمْ مُنْتَهُونَ ‏)‏ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ انْتَهَيْنَا انْتَهَيْنَا ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رُوِيَ عَنْ إِسْرَائِيلَ هَذَا الْحَدِيثُ مُرْسَلٌ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي مَيْسَرَةَ، عَمْرِو بْنِ شُرَحْبِيلَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ، قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ ‏.‏ فَذَكَرَ نَحْوَهُ وَهَذَا أَصَحُّ مِنْ حَدِيثِ مُحَمَّدِ بْنِ يُوسُفَ ‏.‏","v":[]}],"58":[{"c":"Sunan Abu Dawud","r":"Hadith 4746","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4746","x":"Narrated Zayd ibn Arqam:\n\nWe were with the Messenger of Allah (ﷺ). He said when we arrived at a halting place: You are not a hundred thousandth part of those who will come down to me at the pond. I (the narrator AbuHamzah) asked: What was your number that day? He replied: Seven or eight hundred.","ar":"حَدَّثَنَا حَفْصُ بْنُ عُمَرَ النَّمَرِيُّ، حَدَّثَنَا شُعْبَةُ، عَنْ عَمْرِو بْنِ مُرَّةَ، عَنْ أَبِي حَمْزَةَ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ ‏:‏ كُنَّا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَنَزَلْنَا مَنْزِلاً فَقَالَ ‏:‏ ‏\n\n\"‏ مَا أَنْتُمْ جُزْءٌ مِنْ مِائَةِ أَلْفِ جُزْءٍ مِمَّنْ يَرِدُ عَلَىَّ الْحَوْضَ ‏\"\n\n‏ ‏.‏ قَالَ قُلْتُ ‏:‏ كَمْ كُنْتُمْ يَوْمَئِذٍ قَالَ ‏:‏ سَبْعَمِائَةٍ أَوْ ثَمَانَمِائَةٍ ‏.‏","v":[]}],"59":[{"c":"Sunan Abu Dawud","r":"Hadith 2630","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2630","x":"Sahl bin Mu’adh reported on the authority of his father \"We fought along with the Prophet of Allaah(ﷺ). The rest of the tradition is to the same effect.\"","ar":"حَدَّثَنَا عَمْرُو بْنُ عُثْمَانَ، حَدَّثَنَا بَقِيَّةُ، عَنِ الأَوْزَاعِيِّ، عَنْ أَسِيدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ فَرْوَةَ بْنِ مُجَاهِدٍ، عَنْ سَهْلِ بْنِ مُعَاذٍ، عَنْ أَبِيهِ، قَالَ غَزَوْنَا مَعَ نَبِيِّ اللَّهِ صلى الله عليه وسلم ‏.‏ بِمَعْنَاهُ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4584","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4584","x":"Narrated Ibn `Abbas:\n\nThe Verse: \"Obey Allah and Obey the Apostle and those of you (Muslims) who are in authority.\" (4.59) was revealed in connection with `Abdullah bin Hudhafa bin Qais bin `Adi' when the Prophet (ﷺ) appointed him as the commander of a Sariyya (army detachment).","ar":"حَدَّثَنَا صَدَقَةُ بْنُ الْفَضْلِ، أَخْبَرَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ يَعْلَى بْنِ مُسْلِمٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الأَمْرِ مِنْكُمْ‏}‏‏.‏ قَالَ نَزَلَتْ فِي عَبْدِ اللَّهِ بْنِ حُذَافَةَ بْنِ قَيْسِ بْنِ عَدِيٍّ، إِذْ بَعَثَهُ النَّبِيُّ صلى الله عليه وسلم فِي سَرِيَّةٍ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1834","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1834","x":"It has been narrated on the authority of Ibn Juraij that the Qur'anic injunction:\n\n\" 0 you who believe, obey Allah, His Apostle and those in authority from amongst You\" (iv. 59) -was revealed in respect of 'Abdullah b. Hudhafa b. Qais b. Adi al-Sahmi who was despatched by the Prophet (ﷺ) as leader of a military campaign. The narrator said: He was informed of this fact by Ya'la b. Muslim who was informed by Sa'id b. Jubair who in turn was informed by Ibn Abbas.","ar":"حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، وَهَارُونُ بْنُ عَبْدِ اللَّهِ، قَالاَ حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، قَالَ قَالَ ابْنُ جُرَيْجٍ نَزَلَ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الأَمْرِ مِنْكُمْ‏}‏ فِي عَبْدِ اللَّهِ بْنِ حُذَافَةَ بْنِ قَيْسِ بْنِ عَدِيٍّ السَّهْمِيِّ بَعَثَهُ النَّبِيُّ صلى الله عليه وسلم فِي سَرِيَّةٍ ‏.‏ أَخْبَرَنِيهِ يَعْلَى بْنُ مُسْلِمٍ عَنْ سَعِيدِ بْنِ جُبَيْرٍ عَنِ ابْنِ عَبَّاسٍ ‏.‏","v":[]}],"65":[{"c":"Sunan Abu Dawud","r":"Hadith 3644","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3644","x":"Narrated AbuNamlah al-Ansari:\n\nWhen he was sitting with the Messenger of Allah (ﷺ) and a Jew was also with him, a funeral passed by him. He (the Jew) asked (Him): Muhammad, does this funeral speak? The Prophet (ﷺ) said: Allah has more knowledge. The Jew said: It speaks. The Messenger of Allah (ﷺ) said: Whatever the people of the Book tell you, do not verify them, nor falsify them, but say: We believe in Allah and His Apostle. If it is false, do not confirm it, and if it is right, do not falsify it.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ ثَابِتٍ الْمَرْوَزِيُّ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، أَخْبَرَنِي ابْنُ أَبِي نَمْلَةَ الأَنْصَارِيُّ، عَنْ أَبِيهِ، أَنَّهُ بَيْنَمَا هُوَ جَالِسٌ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَعِنْدَهُ رَجُلٌ مِنَ الْيَهُودِ مُرَّ بِجَنَازَةٍ فَقَالَ يَا مُحَمَّدُ هَلْ تَتَكَلَّمُ هَذِهِ الْجَنَازَةُ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ اللَّهُ أَعْلَمُ ‏\"‏ ‏.‏ فَقَالَ الْيَهُودِيُّ إِنَّهَا تَتَكَلَّمُ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا حَدَّثَكُمْ أَهْلُ الْكِتَابِ فَلاَ تُصَدِّقُوهُمْ وَلاَ تُكَذِّبُوهُمْ وَقُولُوا آمَنَّا بِاللَّهِ وَرُسُلِهِ فَإِنْ كَانَ بَاطِلاً لَمْ تُصَدِّقُوهُ وَإِنْ كَانَ حَقًّا لَمْ تُكَذِّبُوهُ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2359","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2359","x":"Narrated `Abdullah bin Az-Zubair:\n\nAn Ansari man quarreled with Az-Zubair in the presence of the Prophet (ﷺ) about the Harra Canals which were used for irrigating the date-palms. The Ansari man said to Az-Zubair, \"Let the water pass' but Az-Zubair refused to do so. So, the case was brought before the Prophet (ﷺ) who said to Az-Zubair, \"O Zubair! Irrigate (your land) and then let the water pass to your neighbor.\" On that the Ansari got angry and said to the Prophet, \"Is it because he (i.e. Zubair) is your aunt's son?\" On that the color of the face of Allah's Messenger (ﷺ) changed (because of anger) and he said, \"O Zubair! Irrigate (your land) and then withhold the water till it reaches the walls between the pits round the trees.\" Zubair said, \"By Allah, I think that the following verse was revealed on this occasion\": \"But no, by your Lord They can have No faith Until they make you judge In all disputes between them.\" (4.65)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، قَالَ حَدَّثَنِي ابْنُ شِهَابٍ، عَنْ عُرْوَةَ، عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ـ رضى الله عنهما ـ أَنَّهُ حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ النَّبِيِّ صلى الله عليه وسلم فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الأَنْصَارِيُّ سَرِّحِ الْمَاءَ يَمُرُّ فَأَبَى عَلَيْهِ، فَاخْتَصَمَا عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِلزُّبَيْرِ ‏\"‏ اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاء إِلَى جَارِكَ ‏\"‏‏.‏ فَغَضِبَ الأَنْصَارِيُّ، فَقَالَ أَنْ كَانَ ابْنَ عَمَّتِكَ‏.‏ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ اسْقِ يَا زُبَيْرُ، ثُمَّ احْبِسِ الْمَاءَ، حَتَّى يَرْجِعَ إِلَى الْجَدْرِ ‏\"‏‏.‏ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ ‏{‏فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2361","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2361","x":"Narrated `Urwa:\n\nWhen a man from the Ansar quarreled with Az-Zubair, the Prophet (ﷺ) said, \"O Zubair! Irrigate (your land) first and then let the water flow (to the land of the others).\" \"On that the Ansari said, (to the Prophet), \"It is because he is your aunt's son.\" On that the Prophet (ﷺ) said, \"O Zubair! Irrigate till the water reaches the walls between the pits around the trees and then stop (i.e. let the water go to the other's land).\" I think the following verse was revealed concerning this event: \"But no, by your Lord They can have No faith Until they make you judge In all disputes between them.\" (4.65)","ar":"حَدَّثَنَا عَبْدَانُ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، قَالَ خَاصَمَ الزُّبَيْرَ رَجُلٌ مِنَ الأَنْصَارِ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ يَا زُبَيْرُ اسْقِ ثُمَّ أَرْسِلْ ‏\"‏‏.‏ فَقَالَ الأَنْصَارِيُّ إِنَّهُ ابْنُ عَمَّتِكَ‏.‏ فَقَالَ عَلَيْهِ السَّلاَمُ ‏\"‏ اسْقِ يَا زُبَيْرُ، ثُمَّ يَبْلُغُ الْمَاءُ الْجَدْرَ، ثُمَّ أَمْسِكْ ‏\"‏‏.‏ فَقَالَ الزُّبَيْرُ فَأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ ‏{‏َلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ‏}‏‏.‏ قَالَ مُحَمَّدُ بْنُ الْعَبَّاسِ قَالَ أَبُو عَبْدِ اللَّهِ لَيْسَ أَحَدٌ يَذْكُرُ عُرْوَةَ عَنْ عَبْدِ اللَّهِ، إِلاَّ اللَّيْثُ فَقَطْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2362","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2362","x":"Narrated `Urwa bin Az-Zubair:\n\nAn Ansari man quarreled with Az-Zubair about a canal in the Harra which was used for irrigating date-palms. Allah's Messenger (ﷺ), ordering Zubair to be moderate, said, \"O Zubair! Irrigate (your land) first and then leave the water for your neighbor.\" The Ansari said, \"Is it because he is your aunt's son?\" On that the color of the face of Allah's Messenger (ﷺ) changed and he said, \"O Zubair! Irrigate (your land) and withhold the water till it reaches the walls that are between the pits around the trees.\" So, Allah's Apostle gave Zubair his full right. Zubair said, \"By Allah, the following verse was revealed in that connection\": \"But no, by your Lord They can have No faith Until they make you judge In all disputes between them.\" (4.65) (The sub-narrator,) Ibn Shihab said to Juraij (another sub-narrator), \"The Ansar and the other people interpreted the saying of the Prophet, 'Irrigate (your land) and withhold the water till it reaches the walls between the pits around the trees,' as meaning up to the ankles.\"","ar":"حَدَّثَنَا مُحَمَّدٌ، أَخْبَرَنَا مَخْلَدٌ، قَالَ أَخْبَرَنِي ابْنُ جُرَيْجٍ، قَالَ حَدَّثَنِي ابْنُ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّهُ حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ فِي شِرَاجٍ مِنَ الْحَرَّةِ يَسْقِي بِهَا النَّخْلَ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اسْقِ يَا زُبَيْرُ ـ فَأَمَرَهُ بِالْمَعْرُوفِ ـ ثُمَّ أَرْسِلْ إِلَى جَارِكَ ‏\"‏‏.‏ فَقَالَ الأَنْصَارِيُّ أَنْ كَانَ ابْنَ عَمَّتِكَ‏.‏ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ اسْقِ ثُمَّ احْبِسْ حَتَّى يَرْجِعَ الْمَاءُ إِلَى الْجَدْرِ ‏\"‏‏.‏ وَاسْتَوْعَى لَهُ حَقَّهُ‏.‏ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنَّ هَذِهِ الآيَةَ أُنْزِلَتْ فِي ذَلِكَ ‏{‏َلاَ وَرَبِّكِ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ‏}‏‏.‏ قَالَ لِي ابْنُ شِهَابٍ فَقَدَّرَتِ الأَنْصَارُ وَالنَّاسُ قَوْلَ النَّبِيِّ صلى الله عليه وسلم ‏\"‏ اسْقِ ثُمَّ احْبِسْ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ ‏\"‏‏.‏ وَكَانَ ذَلِكَ إِلَى الْكَعْبَيْنِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2708","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2708","x":"Narrated `Urwa bin Az-Zubair:\n\nAz-Zubair told me that he quarreled with an Ansari man who had participated in (the battle of) Badr in front of Allah's Messenger (ﷺ) about a water stream which both of them used for irrigation. Allah's Messenger (ﷺ) said to Az-Zubair, \"O Zubair! Irrigate (your garden) first, and then let the water flow to your neighbor.\" The Ansari became angry and said, \"O Allah's Messenger (ﷺ)! Is it because he is your cousin?\" On that the complexion of Allah's Messenger (ﷺ) changed (because of anger) and said (to Az-Zubair), \"I irrigate (your garden) and then withhold the water till it reaches the walls (surrounding the palms).\" So, Allah's Messenger (ﷺ) gave Az-Zubair his full right. Before that Allah's Messenger (ﷺ) had given a generous judgment beneficial for Az-Zubair and the Ansari, but when the Ansan irritated Allah's Messenger (ﷺ) he gave Az-Zubair his full right according to the evident law. Az-Zubair said, \"By Allah ! I think the following Verse was revealed concerning that case: \"But no by your Lord They can have No faith Until they make you judge In all disputes between them.\" (4.65)","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ الزُّبَيْرَ، كَانَ يُحَدِّثُ أَنَّهُ خَاصَمَ رَجُلاً مِنَ الأَنْصَارِ قَدْ شَهِدَ بَدْرًا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فِي شِرَاجٍ مِنَ الْحَرَّةِ كَانَا يَسْقِيَانِ بِهِ كِلاَهُمَا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِلزُّبَيْرِ ‏\"‏ اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلْ إِلَى جَارِكَ ‏\"‏‏.‏ فَغَضِبَ الأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ آنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ اسْقِ ثُمَّ احْبِسْ حَتَّى يَبْلُغَ الْجَدْرَ ‏\"‏‏.‏ فَاسْتَوْعَى رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَئِذٍ حَقَّهُ لِلزُّبَيْرِ، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم قَبْلَ ذَلِكَ أَشَارَ عَلَى الزُّبَيْرِ بِرَأْىٍ سَعَةٍ لَهُ وَلِلأَنْصَارِيِّ، فَلَمَّا أَحْفَظَ الأَنْصَارِيُّ رَسُولَ اللَّهِ صلى الله عليه وسلم اسْتَوْعَى لِلزُّبَيْرِ حَقَّهُ فِي صَرِيحِ الْحُكْمِ‏.‏ قَالَ عُرْوَةُ قَالَ الزُّبَيْرُ وَاللَّهِ مَا أَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ إِلاَّ فِي ذَلِكَ ‏{‏فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4585","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4585","x":"Narrated `Urwa:\n\nAz-Zubair quarrelled with a man from the Ansar because of a natural mountainous stream at Al-Harra. The Prophet (ﷺ) said \"O Zubair! Irrigate (your lands and the let the water flow to your neighbor The Ansar said, \"O Allah's Messenger (ﷺ) (This is because) he (Zubair) is your cousin?\" At that, the Prophet's face became red (with anger) and he said \"O Zubair! Irrigate (your land) and then withhold the water till it fills the land up to the walls and then let it flow to your neighbor.\" So the Prophet (ﷺ) enabled Az- Zubair to take his full right after the Ansari provoked his anger. The Prophet (ﷺ) had previously given a order that was in favor of both of them Az-Zubair said, \"I don't think but the Verse was revealed in this connection: \"But no, by your Lord, they can have no faith, until they make you judge in all disputes between them.\" (4.65)","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، قَالَ خَاصَمَ الزُّبَيْرُ رَجُلاً مِنَ الأَنْصَارِ فِي شَرِيجٍ مِنَ الْحَرَّةِ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ ‏\"‏‏.‏ فَقَالَ الأَنْصَارِيُّ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُهُ ثُمَّ قَالَ ‏\"‏ اسْقِ يَا زُبَيْرُ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ ‏\"‏‏.‏ وَاسْتَوْعَى النَّبِيُّ صلى الله عليه وسلم لِلزُّبَيْرِ حَقَّهُ فِي صَرِيحِ الْحُكْمِ حِينَ أَحْفَظَهُ الأَنْصَارِيُّ، كَانَ أَشَارَ عَلَيْهِمَا بِأَمْرٍ لَهُمَا فِيهِ سَعَةٌ‏.‏ قَالَ الزُّبَيْرُ فَمَا أَحْسِبُ هَذِهِ الآيَاتِ إِلاَّ نَزَلَتْ فِي ذَلِكَ ‏{‏فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2357","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2357","x":"'Urwa b. Zubair reported that 'Abdullah b. Zubair had narrated to him that a person from the Ansar disputed with Zubair in the presence of Allah's Messenger (ﷺ) in regard to the watering places of Harra from which they watered the date-palms. The Ansari said:\n\nLet the water flow, but he (Zubair) refused to do this and the dispute was brought to Allah's Messenger (ﷺ) and he said to Zubair: Zubair, water (your date-palms), then let the water flow to your neighbor. The Ansari was enraged and said: Allah's Messenger, (you have given this decision) for he is the son of your father's sister. The face of Allah's Apostle (ﷺ) underwent a change, and then said: Zubair, water (your date-palms), then hold it until it rises up to the walls. Zubair said: I think, by Allah, that this verse:\" Nay, by the Lord, they will not (really) (believe) until they make thee a judge of what is in dispute among them, and find in this no dislike of what thou decidest and submit with full submission\" (iv. 65).","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا لَيْثٌ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ رُمْحٍ، أَخْبَرَنَا اللَّيْثُ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ، حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الأَنْصَارِيُّ سَرِّحِ الْمَاءَ ‏.‏ يَمُرُّ فَأَبَى عَلَيْهِمْ فَاخْتَصَمُوا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِلزُّبَيْرِ ‏\"‏ اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ ‏\"‏ ‏.‏ فَغَضِبَ الأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ نَبِيِّ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ يَا زُبَيْرُ اسْقِ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ ‏\"‏ ‏.‏ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ ‏{‏ فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لاَ يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 13, Hadith 1363","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-13/Hadith-1363","x":"Narrated 'Abdullah bin Az-Zubair:\n\n\"A man from the Ansar disputed with Az-Zubair before the Messenger of Allah (ﷺ) about the canals of Harrah which they used to irrigate the date palms. The Ansari said: 'Let the water pass'. But he refused, So they brought their dispute to the Messenger of Allah (ﷺ). The Messenger of Allah (ﷺ) said to Az-Zubair: 'O Zubair! Irrigate (your land) then let the water pass to you neighbor.' The Ansari became angry and said:'[O Messenger of Allah!] Is this because he is your aunt's son?' The face of the Messenger of Allah (ﷺ) changed color. Then he said: 'O Zubair! Irrigate (your land) and then withhold the water until it reaches the walls.' Az-Zubair said: 'By Allah! I think that this Ayah was revealed about that: But no, by your Lord, they can have no Faith until they make you (O Muhammad) judge in all disputes between them, and find in themselves no resistance against your decisions and accept (them) with full submission.'\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا اللَّيْثُ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ، أَنَّهُ حَدَّثَهُ أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الأَنْصَارِيُّ سَرِّحِ الْمَاءَ يَمُرُّ ‏.‏ فَأَبَى عَلَيْهِ فَاخْتَصَمُوا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِلزُّبَيْرِ ‏\"‏ اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ ‏\"‏ ‏.‏ فَغَضِبَ الأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ يَا زُبَيْرُ اسْقِ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ ‏\"‏ ‏.‏ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنِّي لأَحْسِبُ نَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ ‏:‏ ‏(‏فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَرَوَى شُعَيْبُ بْنُ أَبِي حَمْزَةَ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ عَنِ الزُّبَيْرِ وَلَمْ يَذْكُرْ فِيهِ عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏.‏ وَرَوَاهُ عَبْدُ اللَّهِ بْنُ وَهْبٍ عَنِ اللَّيْثِ وَيُونُسَ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ نَحْوَ الْحَدِيثِ الأَوَّلِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3027","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3027","x":"Narrated 'Urwah bin Az-Zubair:\n\nthat 'Abdullah bin Az-Zubair narrated to him: \"A man from the Ansar was arguing with Az-Zubair about a stream at Al-Harrah with which they irrigated their date-palms. So the Ansari man said: 'Let the water pass through.' But he refused, so they brought their dispute to the Messenger of Allah (ﷺ). So the Messenger of Allah (ﷺ) said to Az-Zubair: 'O Zubair! Water and let the water flow to your neighbor.' The Ansari got angry and said: 'O Messenger of Allah! Is it because he is your nephew?' The face of the Messenger of Allah (ﷺ) changed. Then he said: 'O Zubair! Water and withhold the water until until it flows over your walls.' So Az-Zubair said: 'By Allah, I think this Ayah was revealed about that incident: But no, by your Lord! They can have no faith until they make you judge in all disputes between them... (4:65)\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّهُ حَدَّثَهُ أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ ‏.‏ فَقَالَ الأَنْصَارِيُّ سَرِّحِ الْمَاءَ يَمُرُّ فَأَبَى عَلَيْهِ فَاخْتَصَمُوا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِلزُّبَيْرِ ‏\"‏ اسْقِ يَا زُبَيْرُ وَأَرْسِلِ الْمَاءَ إِلَى جَارِكَ ‏\"‏ ‏.‏ فَغَضِبَ الأَنْصَارِيُّ وَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ ‏.‏ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ يَا زُبَيْرُ اسْقِ وَاحْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ ‏\"‏ ‏.‏ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِك ‏:‏ ‏(‏فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهم‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى سَمِعْتُ مُحَمَّدًا يَقُولُ قَدْ رَوَى ابْنُ وَهْبٍ هَذَا الْحَدِيثِ عَنِ اللَّيْثِ بْنِ سَعْدٍ وَيُونُسَ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ نَحْوَ هَذَا الْحَدِيثِ ‏.‏ وَرَوَى شُعَيْبُ بْنُ أَبِي حَمْزَةَ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنِ الزُّبَيْرِ وَلَمْ يَذْكُرْ عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏.‏","v":[]}],"69":[{"c":"Sahih Bukhari","r":"Hadith 3669","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3669","x":"'Aisha said (in another narration), (\"When the Prophet (ﷺ) was on his death-bed) he looked up and said thrice, (Amongst) the Highest Companion (See Qur'an 4.69)' Aisha said, Allah benefited the people by their two speeches. 'Umar frightened the people some of whom were hypocrites whom Allah caused to abandon Islam because of 'Umar's speech. Then Abu Bakr led the people to True Guidance and acquainted them with the right path they were to follow so that they went out reciting:\n\n-- \"Muhammad is no more than an Apostle and indeed many Apostles have passed away before him..\" (3.144)","ar":"وَقَالَ عَبْدُ اللَّهِ بْنُ سَالِمٍ عَنِ الزُّبَيْدِيِّ، قَالَ عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ أَخْبَرَنِي الْقَاسِمُ، أَنَّ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ شَخَصَ بَصَرُ النَّبِيِّ صلى الله عليه وسلم ثُمَّ قَالَ ‏\"‏ فِي الرَّفِيقِ الأَعْلَى ‏\"‏‏.‏ ثَلاَثًا، وَقَصَّ الْحَدِيثَ، قَالَتْ فَمَا كَانَتْ مِنْ خُطْبَتِهِمَا مِنْ خُطْبَةٍ إِلاَّ نَفَعَ اللَّهُ بِهَا، لَقَدْ خَوَّفَ عُمَرُ النَّاسَ وَإِنَّ فِيهِمْ لَنِفَاقًا، فَرَدَّهُمُ اللَّهُ بِذَلِكَ‏.‏ ثُمَّ لَقَدْ بَصَّرَ أَبُو بَكْرٍ النَّاسَ الْهُدَى وَعَرَّفَهُمُ الْحَقَّ الَّذِي عَلَيْهِمْ وَخَرَجُوا بِهِ يَتْلُونَ ‏{‏وَمَا مُحَمَّدٌ إِلاَّ رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ‏}‏ إِلَى ‏{‏الشَّاكِرِينَ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4435","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4435","x":"Narrated `Aisha:\n\nUsed to hear (from the Prophet) that no Prophet dies till he is given the option to select either the worldly life or the life of the Hereafter. I heard the Prophet (ﷺ) in his fatal disease, with his voice becoming hoarse, saying, \"In the company of those on whom is the grace of Allah..( to the end of the Verse ).\" (4.69) Thereupon I thought that the Prophet (ﷺ) had been given the option.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، عَنْ سَعْدٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ كُنْتُ أَسْمَعُ أَنَّهُ لاَ يَمُوتُ نَبِيٌّ حَتَّى يُخَيَّرَ بَيْنَ الدُّنْيَا وَالآخِرَةِ، فَسَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَأَخَذَتْهُ بُحَّةٌ يَقُولُ ‏{‏مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ‏}‏ الآيَةَ، فَظَنَنْتُ أَنَّهُ خُيِّرَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4440","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4440","x":"Narrated `Aisha:\n\nI heard the Prophet (ﷺ) and listened to him before his death while he was leaning his back on me and saying, \"O Allah! Forgive me, and bestow Your Mercy on me, and let me meet the (highest) companions (of the Hereafter).\" (See the Qur'an (4:69) and Hadith #4435)","ar":"حَدَّثَنَا مُعَلَّى بْنُ أَسَدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُخْتَارٍ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّ عَائِشَةَ، أَخْبَرَتْهُ أَنَّهَا، سَمِعَتِ النَّبِيَّ صلى الله عليه وسلم وَأَصْغَتْ إِلَيْهِ قَبْلَ أَنْ يَمُوتَ، وَهْوَ مُسْنِدٌ إِلَىَّ ظَهْرَهُ يَقُولُ ‏\n\n\"‏ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4586","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4586","x":"Narrated `Aisha:\n\nI heard Allah's Messenger (ﷺ) saying, \"No prophet gets sick but he is given the choice to select either this world or the Hereafter.\" `Aisha added: During his fatal illness, his voice became very husky and I heard him saying: \"In the company of those whom is the Grace of Allah, of the prophets, the Siddiqin (those followers of the prophets who were first and foremost to believe in them), the martyrs and the pious.' (4.69) And from this I came to know that he has been given the option.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ حَوْشَبٍ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ أَبِيهِ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ مَا مِنْ نَبِيٍّ يَمْرَضُ إِلاَّ خُيِّرَ بَيْنَ الدُّنْيَا وَالآخِرَةِ ‏\"‏‏.‏ وَكَانَ فِي شَكْوَاهُ الَّذِي قُبِضَ فِيهِ أَخَذَتْهُ بُحَّةٌ شَدِيدَةٌ فَسَمِعْتُهُ يَقُولُ ‏{‏مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ‏}‏ فَعَلِمْتُ أَنَّهُ خُيِّرَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4765","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4765","x":"Narrated Sa`id bin Jubair:\n\nIbn Abza said to me, \"Ask Ibn `Abbas regarding the Statement of Allah: 'And whoever murders a believer intentionally, his recompense is Hell.' (4.69) And also His Statement: '...nor kill such life as Allah has forbidden, except for a just cause.....except those who repent, believe, and do good deeds.' \" (25.68-70) So I asked Ibn `Abbas and he said, \"When this (25.68-69) was revealed, the people of Mecca said, \"We have invoked other gods with Allah, and we have murdered such lives which Allah has made sacred, and we have committed illegal sexual intercourse. So Allah revealed: 'Except those who repent, believe, and do good deeds and Allah is Oft-Forgiving, Most Merciful.' (25.70)","ar":"حَدَّثَنَا سَعْدُ بْنُ حَفْصٍ، حَدَّثَنَا شَيْبَانُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ ابْنُ أَبْزَى سَلِ ابْنَ عَبَّاسٍ عَنْ قَوْلِهِ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ‏}‏ وَقَوْلِهِ ‏{‏لاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ حَتَّى بَلَغَ ‏{‏إِلاَّ مَنْ تَابَ‏}‏ فَسَأَلْتُهُ فَقَالَ لَمَّا نَزَلَتْ قَالَ أَهْلُ مَكَّةَ فَقَدْ عَدَلْنَا بِاللَّهِ وَقَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَأَتَيْنَا الْفَوَاحِشَ، فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلاً صَالِحًا‏}‏ إِلَى قَوْلِهِ ‏{‏غَفُورًا رَحِيمًا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5674","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5674","x":"Narrated `Aisha:\n\nI heard the Prophet (ﷺ), who was resting against me, saying, \"O Allah! Excuse me and bestow Your Mercy on me and let me join with the highest companions (in Paradise).\" See Qur'an (4.69)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، قَالَ سَمِعْتُ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم وَهْوَ مُسْتَنِدٌ إِلَىَّ يَقُولُ ‏\n\n\"‏ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الأَعْلَى ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6348","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6348","x":"Narrated `Aisha:\n\nWhen Allah's Messenger (ﷺ) was healthy, he used to say, \"No prophet dies till he is shown his place in Paradise, and then he is given the option (to live or die).\" So when death approached him(during his illness), and while his head was on my thigh, he became unconscious for a while, and when he recovered, he fixed his eyes on the ceiling and said, \"O Allah! (Let me join) the Highest Companions (see Qur'an 4:69),\" I said, \"So, he does not choose us.\" Then I realized that it was the application of the statement he used to relate to us when he was healthy. So that was his last utterance (before he died), i.e. \"O Allah! (Let me join) the Highest Companions.\"","ar":"حَدَّثَنَا سَعِيدُ بْنُ عُفَيْرٍ، قَالَ حَدَّثَنِي اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، وَعُرْوَةُ بْنُ الزُّبَيْرِ، فِي رِجَالٍ مِنْ أَهْلِ الْعِلْمِ أَنَّ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَقُولُ وَهْوَ صَحِيحٌ ‏\"‏ لَنْ يُقْبَضَ نَبِيٌّ قَطُّ حَتَّى يَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ ثُمَّ يُخَيَّرُ ‏\"‏‏.‏ فَلَمَّا نَزَلَ بِهِ وَرَأْسُهُ عَلَى فَخِذِي، غُشِيَ عَلَيْهِ سَاعَةً، ثُمَّ أَفَاقَ فَأَشْخَصَ بَصَرَهُ إِلَى السَّقْفِ ثُمَّ قَالَ ‏\"‏ اللَّهُمَّ الرَّفِيقَ الأَعْلَى ‏\"‏‏.‏ قُلْتُ إِذًا لاَ يَخْتَارُنَا، وَعَلِمْتُ أَنَّهُ الْحَدِيثُ الَّذِي كَانَ يُحَدِّثُنَا، وَهْوَ صَحِيحٌ‏.‏ قَالَتْ فَكَانَتْ تِلْكَ آخِرَ كَلِمَةٍ تَكَلَّمَ بِهَا ‏\"‏ اللَّهُمَّ الرَّفِيقَ الأَعْلَى ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6509","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6509","x":"Narrated `Aisha:\n\n(the wife of the Prophet) When Allah's Messenger (ﷺ) was in good health, he used to say, \"No prophet's soul is ever captured unless he is shown his place in Paradise and given the option (to die or survive).\" So when the death of the Prophet (ﷺ) approached and his head was on my thigh, he became unconscious for a while and then he came to his senses and fixed his eyes on the ceiling and said, \"O Allah (with) the highest companions.\" (See Qur'an 4:69). I said' \"Hence he is not going to choose us.\" And I came to know that it was the application of the narration which he (the Prophet) used to narrate to us. And that was the last statement of the Prophet (before his death) i.e., \"O Allah! With the highest companions.\" (See Qur'an 4:69)","ar":"حَدَّثَنِي يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، وَعُرْوَةُ بْنُ الزُّبَيْرِ، فِي رِجَالٍ مِنْ أَهْلِ الْعِلْمِ أَنَّ عَائِشَةَ زَوْجَ النَّبِيِّ صلى الله عليه وسلم قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَقُولُ وَهْوَ صَحِيحٌ ‏\"‏ إِنَّهُ لَمْ يُقْبَضْ نَبِيٌّ قَطُّ حَتَّى يَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ ثُمَّ يُخَيَّرُ ‏\"‏‏.‏ فَلَمَّا نَزَلَ بِهِ، وَرَأْسُهُ عَلَى فَخِذِي، غُشِيَ عَلَيْهِ سَاعَةً، ثُمَّ أَفَاقَ، فَأَشْخَصَ بَصَرَهُ إِلَى السَّقْفِ ثُمَّ قَالَ ‏\"‏ اللَّهُمَّ الرَّفِيقَ الأَعْلَى ‏\"‏‏.‏ قُلْتُ إِذًا لاَ يَخْتَارُنَا، وَعَرَفْتُ أَنَّهُ الْحَدِيثُ الَّذِي كَانَ يُحَدِّثُنَا بِهِ ـ قَالَتْ ـ فَكَانَتْ تِلْكَ آخِرَ كَلِمَةٍ تَكَلَّمَ بِهَا النَّبِيُّ صلى الله عليه وسلم قَوْلُهُ ‏\"‏ اللَّهُمَّ الرَّفِيقَ الأَعْلَى ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6510","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6510","x":"Narrated `Aisha:\n\nThere was a leather or wood container full of water in front of Allah's Messenger (ﷺ) (at the time of his death). He would put his hand into the water and rub his face with it, saying, \"None has the right to be worshipped but Allah! No doubt, death has its stupors.\" Then he raised his hand and started saying, \"(O Allah!) with the highest companions.\" (See Qur'an 4:69) (and kept on saying it) till he expired and his hand dropped.\"","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ عُبَيْدِ بْنِ مَيْمُونٍ، حَدَّثَنَا عِيسَى بْنُ يُونُسَ، عَنْ عُمَرَ بْنِ سَعِيدٍ، قَالَ أَخْبَرَنِي ابْنُ أَبِي مُلَيْكَةَ، أَنَّ أَبَا عَمْرٍو، ذَكْوَانَ مَوْلَى عَائِشَةَ أَخْبَرَهُ أَنَّ عَائِشَةَ ـ رضى الله عنها ـ كَانَتْ تَقُولُ إِنَّ رَسُولَ اللَّهَ صلى الله عليه وسلم كَانَ بَيْنَ يَدَيْهِ رَكْوَةٌ ـ أَوْ عُلْبَةٌ فِيهَا مَاءٌ، يَشُكُّ عُمَرُ ـ فَجَعَلَ يُدْخِلُ يَدَيْهِ فِي الْمَاءِ، فَيَمْسَحُ بِهِمَا وَجْهَهُ وَيَقُولُ ‏\"‏ لاَ إِلَهَ إِلاَّ اللَّهُ، إِنَّ لِلْمَوْتِ سَكَرَاتٍ ‏\"‏‏.‏ ثُمَّ نَصَبَ يَدَهُ فَجَعَلَ يَقُولُ ‏\"‏ فِي الرَّفِيقِ الأَعْلَى ‏\"‏‏.‏ حَتَّى قُبِضَ وَمَالَتْ يَدُهُ‏.‏ قَالَ أَبُو عَبْد اللَّهِ الْعُلْبَةُ مِنْ الْخَشَبِ وَالرَّكْوَةُ مِنْ الْأَدَمِ.","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 6, Hadith 1620","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-6/Hadith-1620","x":"It was narrated that ‘Aishah said:\n\n\"I heard the Messenger of Allah (ﷺ) say: ‘There is no Prophet who fell sick but he was given the choice between this world and the Hereafter.’ She said: ‘When he became sick with the illness that would be his last, (his voice) became hoarse and I heard him say, \"In the company of those on whom Allah has bestowed His grace, of the Prophets, the true believers, the martyrs, and the righteous.’\" [4:69] Then I knew that he had been given the choice.\"","ar":"حَدَّثَنَا أَبُو مَرْوَانَ الْعُثْمَانِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ أَبِيهِ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يَقُولُ ‏\"‏ مَا مِنْ نَبِيٍّ يَمْرَضُ إِلاَّ خُيِّرَ بَيْنَ الدُّنْيَا وَالآخِرَةِ ‏\"‏ ‏.‏ قَالَتْ فَلَمَّا كَانَ مَرَضُهُ الَّذِي قُبِضَ فِيهِ أَخَذَتْهُ بُحَّةٌ فَسَمِعْتُهُ يَقُولُ ‏\"‏ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ ‏\"‏ ‏.‏ فَعَلِمْتُ أَنَّهُ خُيِّرَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2444c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2444c","x":"'A'isha reported:\n\nI heard that never a prophet dies until he is given an option to opt the life of (this) world or that of the Hereafter. She further said: I heard Allah's Messenger (ﷺ) say in his last illness in which he' died. I heard him saying in gruffness of the voice: Along with those persons upon whom Allah bestowed favours from amongst the Apostles, the testifiers of truth, the martyrs, the pious and goodly company are they (iv. 69). (It was on bearing these words) that I thought that he had been given choice (and he opted to live with these pious persons in the Paradise).","ar":"وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ - وَاللَّفْظُ لاِبْنِ الْمُثَنَّى - قَالاَ حَدَّثَنَا مُحَمَّدُ، بْنُ جَعْفَرٍ حَدَّثَنَا شُعْبَةُ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ كُنْتُ أَسْمَعُ أَنَّهُ لَنْ يَمُوتَ نَبِيٌّ حَتَّى يُخَيَّرَ بَيْنَ الدُّنْيَا وَالآخِرَةِ - قَالَتْ - فَسَمِعْتُ النَّبِيَّ صلى الله عليه وسلم فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَأَخَذَتْهُ بُحَّةٌ يَقُولُ ‏{‏ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا‏}‏ قَالَتْ فَظَنَنْتُهُ خُيِّرَ حِينَئِذٍ ‏.‏","v":[]}],"86":[{"c":"Al-Adab Al-Mufrad","r":"Book 43, Hadith 1095","u":"https://quranx.com/Hadith/Adab/English/Book-43/Hadith-1095","x":"Jabir said, \"When you come in to your family, greet them with a greeting from Allah which is blessed and good.\" He added, \"I only think that it is what is meant by His words, 'When you are greeted with a greeting, greet with one better than it or return it.' (4:86)\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ مُقَاتِلٍ، قَالَ‏:‏ أَخْبَرَنَا عَبْدُ اللهِ، قَالَ‏:‏ أَخْبَرَنَا ابْنُ جُرَيْجٍ قَالَ‏:‏ أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ جَابِرًا يَقُولُ‏:‏ إِذَا دَخَلْتَ عَلَى أَهْلِكَ فَسَلِّمْ عَلَيْهِمْ تَحِيَّةً مِنْ عِنْدِ اللهِ مُبَارَكَةً طَيْبَةً‏.‏","v":[]},{"c":"Al-Adab Al-Mufrad","r":"Book 44, Hadith 1107","u":"https://quranx.com/Hadith/Adab/English/Book-44/Hadith-1107","x":"Ibn 'Abbas said, \"Return the greeting to whomever it is, Jew, Christian, or Magian. That is because Allah says, 'When you are greeted with a greeting, greet with one better than it or return it.' (4:86)\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ، قَالَ‏:‏ حَدَّثَنَا الْوَلِيدُ بْنُ أَبِي ثَوْرٍ، عَنْ سِمَاكٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ قَالَ‏:‏ رُدُّوا السَّلاَمَ عَلَى مَنْ كَانَ يَهُودِيًّا، أَوْ نَصْرَانِيًّا، أَوْ مَجُوسِيًّا، ذَلِكَ بِأَنَّ اللَّهَ يَقُولُ‏:‏ ‏{‏وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا‏}‏‏.‏","v":[]}],"88":[{"c":"Sahih Bukhari","r":"Hadith 1884","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1884","x":"Narrated Zaid bin Thabit:\n\nWhen the Prophet (ﷺ) went out for (the battle of) Uhud, some of his companions (hypocrites) returned (home). A party of the believers remarked that they would kill those (hypocrites) who had returned, but another party said that they would not kill them. So, this Divine Inspiration was revealed: \"Then what is the matter with you that you are divided into two parties concerning the hypocrites.\" (4.88) The Prophet (ﷺ) said, \"Medina expels the bad persons from it, as fire expels the impurities of iron.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ، قَالَ سَمِعْتُ زَيْدَ بْنَ ثَابِتٍ ـ رضى الله عنه ـ يَقُولُ لَمَّا خَرَجَ النَّبِيُّ صلى الله عليه وسلم إِلَى أُحُدٍ رَجَعَ نَاسٌ مِنْ أَصْحَابِهِ فَقَالَتْ فِرْقَةٌ نَقْتُلُهُمْ‏.‏ وَقَالَتْ فِرْقَةٌ لاَ نَقْتُلُهُمْ‏.‏ فَنَزَلَتْ ‏{‏فَمَا لَكُمْ فِي الْمُنَافِقِينِ فِئَتَيْنِ‏}‏ وَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ إِنَّهَا تَنْفِي الرِّجَالَ كَمَا تَنْفِي النَّارُ خَبَثَ الْحَدِيدِ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4050","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4050","x":"Narrated Zaid bin Thabit:\n\nWhen the Prophet (ﷺ) set out for (the battle of) Uhud, some of those who had gone out with him, returned. The companions of the Prophet (ﷺ) were divided into two groups. One group said, \"We will fight them (i.e. the enemy),\" and the other group said, \"We will not fight them.\" So there came the Divine Revelation:-- '(O Muslims!) Then what is the matter within you that you are divided. Into two parties about the hypocrites? Allah has cast them back (to disbelief) Because of what they have earned.' (4.88) On that, the Prophet (ﷺ) said, \"That is Taiba (i.e. the city of Medina) which clears one from one's sins as the fire expels the impurities of silver.\"","ar":"حَدَّثَنَا أَبُو الْوَلِيدِ، حَدَّثَنَا شُعْبَةُ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، سَمِعْتُ عَبْدَ اللَّهِ بْنَ يَزِيدَ،، يُحَدِّثُ عَنْ زَيْدِ بْنِ ثَابِتٍ ـ رضى الله عنه ـ قَالَ لَمَّا خَرَجَ النَّبِيُّ صلى الله عليه وسلم إِلَى أُحُدٍ، رَجَعَ نَاسٌ مِمَّنْ خَرَجَ مَعَهُ، وَكَانَ أَصْحَابُ النَّبِيِّ صلى الله عليه وسلم فِرْقَتَيْنِ، فِرْقَةً تَقُولُ نُقَاتِلُهُمْ‏.‏ وَفِرْقَةً تَقُولُ لاَ نُقَاتِلُهُمْ‏.‏ فَنَزَلَتْ ‏{‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ وَاللَّهُ أَرْكَسَهُمْ بِمَا كَسَبُوا‏}‏ وَقَالَ ‏\"‏ إِنَّهَا طَيْبَةُ تَنْفِي الذُّنُوبَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4589","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4589","x":"Narrated Zaid bin Thabit:\n\nRegarding the Verse:-- \"Then what is the matter with you that you are divided into two parties about the hypocrites?\" (4.88) Some of the companions of the Prophet (ﷺ) returned from the battle of Uhud (i.e. refused to fight) whereupon the Muslims got divided into two parties; one of them was in favor of their execution and the other was not in favour of it. So there ware revealed: \"Then what is the matter with you that you are divided into two parties about the hypocrites?\" (4.88). Then the Prophet (ﷺ) said \"It (i.e. Medina) is aTayyaboh (good), it expels impurities as the fire expels the impurities of silver.\"","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، وَعَبْدُ الرَّحْمَنِ، قَالاَ حَدَّثَنَا شُعْبَةُ، عَنْ عَدِيٍّ، عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ، عَنْ زَيْدِ بْنِ ثَابِت ٍ ـ رضى الله عنه ـ ‏{‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ‏}‏ رَجَعَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم مِنْ أُحُدٍ، وَكَانَ النَّاسُ فِيهِمْ فِرْقَتَيْنِ فَرِيقٌ يَقُولُ اقْتُلْهُمْ‏.‏ وَفَرِيقٌ يَقُولُ لاَ فَنَزَلَتْ ‏{‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ‏}‏ وَقَالَ ‏\"‏ إِنَّهَا طَيْبَةُ تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏\"‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2776a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2776a","x":"Zaid b. Thabit reported that Allah's Apostle (ﷺ) set out for Uhud. Some of those persons who were with them came back. The Companions of Allah's Apostle (ﷺ) were divided in two groups. One group said:\n\nWe would kill them, and the other one said: No, this should not be done, and it was on this occasion that this verse was revealed:\" Why should you, then, be two parties in relation to hypocrites?\" (iv. 88).","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَدِيٍّ، - وَهُوَ ابْنُ ثَابِتٍ - قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ يَزِيدَ، يُحَدِّثُ عَنْ زَيْدِ بْنِ ثَابِتٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم خَرَجَ إِلَى أُحُدٍ فَرَجَعَ نَاسٌ مِمَّنْ كَانَ مَعَهُ فَكَانَ أَصْحَابُ النَّبِيِّ صلى الله عليه وسلم فِيهِمْ فِرْقَتَيْنِ قَالَ بَعْضُهُمْ نَقْتُلُهُمْ ‏.‏ وَقَالَ بَعْضُهُمْ لاَ ‏.‏ فَنَزَلَتْ ‏{‏ فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3028","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3028","x":"Narrated 'Abdullah bin Yazid:\n\nfrom Zaid bin Thabit that he heard about this Ayah: Then what is the matter with you that you are divided into two parties about the hypocrites? (4:88) He said: \"People among the Companions of the Prophet (ﷺ) returned on the Day of Uhud and there were two parties among them, a group who said: 'Kill them,' and a group that say not to. So Allah revealed this Ayah: Then what is the matter with you that you are divided into two parties about the hypocrites? (4:88) So he said: \"Indeed it is Taibah (Al-Madinah). And he said: 'It expels filth from it just like the fire expels filth from iron.'\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ يَزِيدَ، يُحَدِّثُ عَنْ زَيْدِ بْنِ ثَابِتٍ، أَنَّهُ قَالَ فِي هَذِهِ الآيَةِ ‏:‏ ‏(‏ فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏)‏ قَالَ رَجَعَ نَاسٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمَ أُحُدٍ ‏.‏ فَكَانَ النَّاسُ فِيهِمْ فَرِيقَيْنِ فَرِيقٌ يَقُولُ اقْتُلْهُمْ ‏.‏ وَفَرِيقٌ يَقُولُ لاَ ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏)‏ وَقَالَ ‏\"‏ إِنَّهَا طِيبَةُ وَقَالَ إِنَّهَا تَنْفِي الْخَبِيثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْحَدِيدِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَعَبْدُ اللَّهِ بْنُ يَزِيدَ هُوَ الأَنْصَارِيُّ الْخَطْمِيُّ وَلَهُ صُحْبَةٌ ‏.‏","v":[]}],"92":[{"c":"Sahih Muslim","r":"Hadith 3023a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3023a","x":"Sa'id b. Jubair reported:\n\nThe inhabitants of Kufa differed in regard to this verse:\" But whoever slays another believer intentionally, his requital shall be Hell\" (iv. 92), so I went to Ibn 'Abbas and asked him about it, whereupon he said: This has been revealed and nothing abrogated it.","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنِ الْمُغِيرَةِ بْنِ النُّعْمَانِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ اخْتَلَفَ أَهْلُ الْكُوفَةِ فِي هَذِهِ الآيَةِ ‏{‏ وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ‏}‏ فَرَحَلْتُ إِلَى ابْنِ عَبَّاسٍ فَسَأَلْتُهُ عَنْهَا فَقَالَ لَقَدْ أُنْزِلَتْ آخِرَ مَا أُنْزِلَ ثُمَّ مَا نَسَخَهَا شَىْءٌ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3023c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3023c","x":"Sa'id b. Jubair reported:\n\n'Abd al Rahman b. Abzi commanded me that I should ask Ibn 'Abbas about these two verses:\" He who slays a believer intentionally his requital shall be Hell where he would abide for ever\" (iv. 92). So, I asked him and he said: Nothing has abrogated it. And as for this verse:\" And they who call not upon another god with Allah and slay not the soul which Allah has forbidden, except in the cause of justice\" (xxv. 68), he (Ibn Abbas) said: This has been revealed in regard to the polytheists.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ بَشَّارٍ، قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى أَنْ أَسْأَلَ ابْنَ عَبَّاسٍ، عَنْ هَاتَيْنِ الآيَتَيْنِ، ‏{‏ وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا‏}‏ فَسَأَلْتُهُ فَقَالَ لَمْ يَنْسَخْهَا شَىْءٌ ‏.‏ وَعَنْ هَذِهِ الآيَةِ ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ قَالَ نَزَلَتْ فِي أَهْلِ الشِّرْكِ ‏.‏","v":[]}],"93":[{"c":"Sunan Abu Dawud","r":"Hadith 4285","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4285","x":"Narrated AbuSa'id al-Khudri:\n\nThe Prophet (ﷺ) said: The Mahdi will be of my stock, and will have a broad forehead a prominent nose. He will fill the earth will equity and justice as it was filled with oppression and tyranny, and he will rule for seven years.","ar":"حَدَّثَنَا سَهْلُ بْنُ تَمَّامِ بْنِ بَزِيعٍ، حَدَّثَنَا عِمْرَانُ الْقَطَّانُ، عَنْ قَتَادَةَ، عَنْ أَبِي نَضْرَةَ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الْمَهْدِيُّ مِنِّي أَجْلَى الْجَبْهَةِ أَقْنَى الأَنْفِ يَمْلأُ الأَرْضَ قِسْطًا وَعَدْلاً كَمَا مُلِئَتْ جَوْرًا وَظُلْمًا يَمْلِكُ سَبْعَ سِنِينَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4286","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4286","x":"Narrated Umm Salamah, Ummul Mu'minin:\n\nThe Prophet (ﷺ) said: Disagreement will occur at the death of a caliph and a man of the people of Medina will come flying forth to Mecca. Some of the people of Mecca will come to him, bring him out against his will and swear allegiance to him between the Corner and the Maqam. An expeditionary force will then be sent against him from Syria but will be swallowed up in the desert between Mecca and Medina. When the people see that, the eminent saints of Syria and the best people of Iraq will come to him and swear allegiance to him between the Corner and the Maqam. Then there will arise a man of Quraysh whose maternal uncles belong to Kalb and send against them an expeditionary force which will be overcome by them, and that is the expedition of Kalb. Disappointed will be the one who does not receive the booty of Kalb. He will divide the property, and will govern the people by the Sunnah of their Prophet (ﷺ) and establish Islam on Earth. He will remain seven years, then die, and the Muslims will pray over him. Abu Dawud said: Some transmitted from Hisham \"nine years\" and some \"seven years\".","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، عَنْ صَالِحٍ أَبِي الْخَلِيلِ، عَنْ صَاحِبٍ، لَهُ عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ يَكُونُ اخْتِلاَفٌ عِنْدَ مَوْتِ خَلِيفَةٍ فَيَخْرُجُ رَجُلٌ مِنْ أَهْلِ الْمَدِينَةِ هَارِبًا إِلَى مَكَّةَ فَيَأْتِيهِ نَاسٌ مِنْ أَهْلِ مَكَّةَ فَيُخْرِجُونَهُ وَهُوَ كَارِهٌ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ وَيُبْعَثُ إِلَيْهِ بَعْثٌ مِنَ الشَّامِ فَيُخْسَفُ بِهِمْ بِالْبَيْدَاءِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ فَإِذَا رَأَى النَّاسُ ذَلِكَ أَتَاهُ أَبْدَالُ الشَّامِ وَعَصَائِبُ أَهْلِ الْعِرَاقِ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ ثُمَّ يَنْشَأُ رَجُلٌ مِنْ قُرَيْشٍ أَخْوَالُهُ كَلْبٌ فَيَبْعَثُ إِلَيْهِمْ بَعْثًا فَيَظْهَرُونَ عَلَيْهِمْ وَذَلِكَ بَعْثُ كَلْبٍ وَالْخَيْبَةُ لِمَنْ لَمْ يَشْهَدْ غَنِيمَةَ كَلْبٍ فَيَقْسِمُ الْمَالَ وَيَعْمَلُ فِي النَّاسِ بِسُنَّةِ نَبِيِّهِمْ صلى الله عليه وسلم وَيُلْقِي الإِسْلاَمُ بِجِرَانِهِ إِلَى الأَرْضِ فَيَلْبَثُ سَبْعَ سِنِينَ ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ بَعْضُهُمْ عَنْ هِشَامٍ ‏\"‏ تِسْعَ سِنِينَ ‏\"‏ ‏.‏ وَقَالَ بَعْضُهُمْ ‏\"‏ سَبْعَ سِنِينَ ‏\"‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4288","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4288","x":"The tradition mentioned above has also been transmitted by Umm Salamah from the Prophet (ﷺ) through a different chain of narrators. The tradition of Mu'adh is more perfect.","ar":"حَدَّثَنَا ابْنُ الْمُثَنَّى، حَدَّثَنَا عَمْرُو بْنُ عَاصِمٍ، حَدَّثَنَا أَبُو الْعَوَّامِ، حَدَّثَنَا قَتَادَةُ، عَنْ أَبِي الْخَلِيلِ، عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ، عَنْ أُمِّ سَلَمَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا الْحَدِيثِ وَحَدِيثُ مُعَاذٍ أَتَمُّ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4289","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4289","x":"Umm salamah reported the Prophet (ﷺ) as saying about the swallowing up an army by the earth. I asked:\n\nHow will a man who comes against his will (be swallowed up by the earth), Messenger of Allah ? He replied: All will be swallowed up, but each will be raised according to his intention on the Day of Resurrection.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ، عَنْ عُبَيْدِ اللَّهِ ابْنِ الْقِبْطِيَّةِ، عَنْ أُمِّ سَلَمَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِقِصَّةِ جَيْشِ الْخَسْفِ قُلْتُ يَا رَسُولَ اللَّهِ فَكَيْفَ بِمَنْ كَانَ كَارِهًا قَالَ ‏\n\n\"‏ يُخْسَفُ بِهِمْ وَلَكِنْ يُبْعَثُ يَوْمَ الْقِيَامَةِ عَلَى نِيَّتِهِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4290","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4290","x":"Abu Dawud said:\n\nAbu Ishaq told that Ali looked at his son al-Hasan and said: This son of mine is a sayyid (chief) as named by the Prophet (ﷺ), and from his loins will come forth a man who will be called by the name of your Prophet (ﷺ) and resemble him in conduct but not in appearance. He then mentioned the story about his filling the earth with justice.","ar":"الْمُغِيرَةِ، قَالَ حَدَّثَنَا عَمْرُو بْنُ أَبِي قَيْسٍ، عَنْ شُعَيْبِ بْنِ خَالِدٍ، عَنْ أَبِي إِسْحَاقَ، قَالَ قَالَ عَلِيٌّ - رضى الله عنه - وَنَظَرَ إِلَى ابْنِهِ الْحَسَنِ فَقَالَ إِنَّ ابْنِي هَذَا سَيِّدٌ كَمَا سَمَّاهُ النَّبِيُّ صلى الله عليه وسلم وَسَيَخْرُجُ مِنْ صُلْبِهِ رَجُلٌ يُسَمَّى بِاسْمِ نَبِيِّكُمْ يُشْبِهُهُ فِي الْخُلُقِ وَلاَ يُشْبِهُهُ فِي الْخَلْقِ ثُمَّ ذَكَرَ قِصَّةَ يَمْلأُ الأَرْضَ عَدْلاً ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3855","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3855","x":"Narrated Sa`id bin Jubair:\n\n`AbdurRahman bin Abza said, \"Ask Ibn `Abbas about these two Qur'anic Verses: 'Nor kill such life as Allah has made sacred, Except for just cause.' (25.68) \"And whoever kills a believer intentionally, his recompense is Hell. (4.93) So I asked Ibn `Abbas who said, \"When the Verse that is in Sura-al-Furqan was revealed, the pagans of Mecca said, 'But we have slain such life as Allah has made sacred, and we have invoked other gods along with Allah, and we have also committed fornication.' So Allah revealed:-- 'Except those who repent, believe, and do good-- (25.70) So this Verse was concerned with those people. As for the Verse in Surat-an-Nisa (4-93), it means that if a man, after understanding Islam and its laws and obligations, murders somebody, then his punishment is to dwell in the (Hell) Fire forever.\" Then I mentioned this to Mujahid who said, \"Except the one who regrets (one's crime). \"","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، حَدَّثَنِي سَعِيدُ بْنُ جُبَيْرٍ، أَوْ قَالَ حَدَّثَنِي الْحَكَمُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى قَالَ سَلِ ابْنَ عَبَّاسٍ عَنْ هَاتَيْنِ الآيَتَيْنِ، مَا أَمْرُهُمَا ‏{‏وَلاَ تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ ‏}‏ ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏ فَسَأَلْتُ ابْنَ عَبَّاسٍ فَقَالَ لَمَّا أُنْزِلَتِ الَّتِي فِي الْفُرْقَانِ قَالَ مُشْرِكُو أَهْلِ مَكَّةَ فَقَدْ قَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ، وَدَعَوْنَا مَعَ اللَّهِ إِلَهًا آخَرَ، وَقَدْ أَتَيْنَا الْفَوَاحِشَ‏.‏ فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ‏}‏ الآيَةَ فَهَذِهِ لأُولَئِكَ وَأَمَّا الَّتِي فِي النِّسَاءِ الرَّجُلُ إِذَا عَرَفَ الإِسْلاَمَ وَشَرَائِعَهُ، ثُمَّ قَتَلَ فَجَزَاؤُهُ جَهَنَّمُ‏.‏ فَذَكَرْتُهُ لِمُجَاهِدٍ فَقَالَ إِلاَّ مَنْ نَدِمَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4650","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4650","x":"Narrated Ibn `Umar:\n\nThat a man came to him (while two groups of Muslims were fighting) and said, \"O Abu `Abdur Rahman! Don't you hear what Allah has mentioned in His Book: 'And if two groups of believers fight against each other...' (49.9) So what prevents you from fighting as Allah has mentioned in His Book?\"' Ibn `Umar said, \"O son of my brother! I would rather be blamed for not fighting because of this Verse than to be blamed because of another Verse where Allah says: 'And whoever kills a believer intentionally...\" (4.93) Then that man said, \"Allah says:-- 'And fight them until there is no more afflictions (worshipping other besides Allah) and the religion (i.e. worship) will be all for Allah (Alone)\" (8.39) Ibn `Umar said, \"We did this during the lifetime of Allah's Messenger (ﷺ) when the number of Muslims was small, and a man was put to trial because of his religion, the pagans would either kill or chain him; but when the Muslims increased (and Islam spread), there was no persecution.\" When that man saw that Ibn `Umar did not agree to his proposal, he said, \"What is your opinion regarding `Ali and `Uthman?\" Ibn `Umar said, \"What is my opinion regarding `Ali and `Uthman? As for `Uthman, Allah forgave him and you disliked to forgive him, and `Ali is the cousin and son-in-law of Allah's Messenger (ﷺ).\" Then he pointed out with his hand and said, \"And that is his daughter's (house) which you can see.\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ عَبْدِ الْعَزِيزِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَحْيَى، حَدَّثَنَا حَيْوَةُ، عَنْ بَكْرِ بْنِ عَمْرٍو، عَنْ بُكَيْرٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ أَنَّ رَجُلاً، جَاءَهُ فَقَالَ يَا أَبَا عَبْدِ الرَّحْمَنِ، أَلاَ تَسْمَعُ مَا ذَكَرَ اللَّهُ فِي كِتَابِهِ ‏{‏وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا‏}‏ إِلَى آخِرِ الآيَةِ، فَمَا يَمْنَعُكَ أَنْ لاَ تُقَاتِلَ كَمَا ذَكَرَ اللَّهُ فِي كِتَابِهِ‏.‏ فَقَالَ يَا ابْنَ أَخِي أَغْتَرُّ بِهَذِهِ الآيَةِ وَلاَ أُقَاتِلُ أَحَبُّ إِلَىَّ مِنْ أَنْ أَغْتَرَّ بِهَذِهِ الآيَةِ الَّتِي يَقُولُ اللَّهُ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏ إِلَى آخِرِهَا‏.‏ قَالَ فَإِنَّ اللَّهَ يَقُولُ ‏{‏وَقَاتِلُوهُمْ حَتَّى لاَ تَكُونَ فِتْنَةٌ‏}‏‏.‏ قَالَ ابْنُ عُمَرَ قَدْ فَعَلْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم إِذْ كَانَ الإِسْلاَمُ قَلِيلاً، فَكَانَ الرَّجُلُ يُفْتَنُ فِي دِينِهِ، إِمَّا يَقْتُلُوهُ وَإِمَّا يُوثِقُوهُ، حَتَّى كَثُرَ الإِسْلاَمُ، فَلَمْ تَكُنْ فِتْنَةٌ، فَلَمَّا رَأَى أَنَّهُ لاَ يُوَافِقُهُ فِيمَا يُرِيدُ قَالَ فَمَا قَوْلُكَ فِي عَلِيٍّ وَعُثْمَانَ‏.‏ قَالَ ابْنُ عُمَرَ مَا قَوْلِي فِي عَلِيٍّ وَعُثْمَانَ أَمَّا عُثْمَانُ فَكَانَ اللَّهُ قَدْ عَفَا عَنْهُ، فَكَرِهْتُمْ أَنْ يَعْفُوَ عَنْهُ، وَأَمَّا عَلِيٌّ فَابْنُ عَمِّ رَسُولِ اللَّهِ صلى الله عليه وسلم وَخَتَنُهُ‏.‏ وَأَشَارَ بِيَدِهِ وَهَذِهِ ابْنَتُهُ أَوْ بِنْتُهُ حَيْثُ تَرَوْنَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4763","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4763","x":"Narrated Sa`id bin Jubair:\n\nThe people of Kufa differed as regards the killing of a believer so I entered upon Ibn `Abbas (and asked him) about that. Ibn `Abbas said, \"The Verse (in Surat-An-Nisa', 4:93) was the last thing revealed in this respect and nothing cancelled its validity.\"","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، عَنِ الْمُغِيرَةِ بْنِ النُّعْمَانِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ اخْتَلَفَ أَهْلُ الْكُوفَةِ فِي قَتْلِ الْمُؤْمِنِ، فَرَحَلْتُ فِيهِ إِلَى ابْنِ عَبَّاسٍ، فَقَالَ نَزَلَتْ فِي آخِرِ مَا نَزَلَ وَلَمْ يَنْسَخْهَا شَىْءٌ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4764","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4764","x":"Narrated Sa`id bin Jubair:\n\nI asked Ibn `Abbas about Allah's saying:-- '.. this reward is Hell Fire.' (4.93) He said, \"No repentance is accepted from him (i.e. the murderer of a believer).\" I asked him regarding the saying of Allah: 'Those who invoke not with Allah any other god.'...(25.68) He said, \"This Verse was revealed concerning the pagans of the pre-lslamic period.\"","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا مَنْصُورٌ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ سَأَلْتُ ابْنَ عَبَّاسٍ ـ رضى الله عنهما ـ عَنْ قَوْلِهِ تَعَالَى ‏{‏فَجَزَاؤُهُ جَهَنَّمُ‏}‏ قَالَ لاَ تَوْبَةَ لَهُ‏.‏ وَعَنْ قَوْلِهِ جَلَّ ذِكْرُهُ ‏{‏لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ‏}‏ قَالَ كَانَتْ هَذِهِ فِي الْجَاهِلِيَّةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4766","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4766","x":"Narrated Sa`id bin Jubair:\n\n`Abdur-Rahman bin Abza ordered me to ask Ibn `Abbas regarding the two Verses (the first of which was ): \"And whosoever murders a believer intentionally.\" (4.93) So I asked him, and he said, \"Nothing has abrogated this Verse.\" About (the other Verse): 'And those who invoke not with Allah any other god.' he said, \"It was revealed concerning the pagans.\"","ar":"حَدَّثَنَا عَبْدَانُ، أَخْبَرَنَا أَبِي، عَنْ شُعْبَةَ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى أَنْ أَسْأَلَ ابْنَ عَبَّاسٍ، عَنْ هَاتَيْنِ الآيَتَيْنِ، ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏، فَسَأَلْتُهُ فَقَالَ لَمْ يَنْسَخْهَا شَىْءٌ‏.‏ وَعَنْ ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ‏}‏ قَالَ نَزَلَتْ فِي أَهْلِ الشِّرْكِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3029","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3029","x":"Narrated 'Amr bin Dinar:\n\nfrom Ibn 'Abbas that the Prophet (ﷺ) said: \"On the Day of Judgement, the murdered will come with the murderer's scalp and his head in his hand, and his jugular vein flowing blood saying: 'O Lord! This one killed me!' Until he comes close to the Throne.\" So they mentioned repentance to Ibn 'Abbas, and he recited this Ayah: And whoever kills a believer intentionally then his recompense is Hell (4:93). He said: \"This Ayah was not abrogated nor (its ruling) replaced so from where is his repentance?\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ مُحَمَّدٍ الزَّعْفَرَانِيُّ، حَدَّثَنَا شَبَابَةُ، حَدَّثَنَا وَرْقَاءُ بْنُ عُمَرَ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ يَجِيءُ الْمَقْتُولُ بِالْقَاتِلِ يَوْمَ الْقِيَامَةِ نَاصِيَتُهُ وَرَأْسُهُ بِيَدِهِ وَأَوْدَاجُهُ تَشْخُبُ دَمًا يَقُولُ يَا رَبِّ هَذَا قَتَلَنِي حَتَّى يُدْنِيَهُ مِنَ الْعَرْشِ ‏\"\n\n‏ ‏.‏ قَالَ فَذَكَرُوا لاِبْنِ عَبَّاسٍ التَّوْبَةَ فَتَلاَ هَذِهِ الآيَةََ‏:‏ ‏(‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَآؤُهُ جَهَبَّمُ‏)‏ قَالَ وَمَا نُسِخَتْ هَذِهِ الآيَةُ وَلاَ بُدِّلَتْ وَأَنَّى لَهُ التَّوْبَةُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ وَقَدْ رَوَى بَعْضُهُمْ هَذَا الْحَدِيثَ عَنْ عَمْرِو بْنِ دِينَارٍ عَنِ ابْنِ عَبَّاسٍ نَحْوَهُ وَلَمْ يَرْفَعْهُ ‏.‏","v":[]}],"94":[{"c":"Sunan Abu Dawud","r":"Hadith 3985","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3985","x":"Narrated Ubayy ibn Ka'b:\n\nThe Prophet (ﷺ) read the Qur'anic verse: \"Thou hast received (full) excuse from me (min ladunni)\" and put tashdid (doubling of consonants) on nun (n).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ أَبُو عَبْدِ اللَّهِ الْعَنْبَرِيُّ، حَدَّثَنَا أُمَيَّةُ بْنُ خَالِدٍ، حَدَّثَنَا أَبُو الْجَارِيَةِ الْعَبْدِيُّ، عَنْ شُعْبَةَ، عَنْ أَبِي إِسْحَاقَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، عَنْ أُبَىِّ بْنِ كَعْبٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ قَرَأَهَا ‏{‏ قَدْ بَلَغْتَ مِنْ لَدُنِّي ‏}‏ وَثَقَّلَهَا ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4591","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4591","x":"Narrated Ibn `Abbas:\n\nRegarding the Verse: \"And say not to anyone who offers you peace (by accepting Islam), You are not a believer.\" There was a man amidst his sheep. The Muslims pursued him, and he said (to them) \"Peace be on you.\" But they killed him and took over his sheep. Thereupon Allah revealed in that concern, the above Verse up to:-- \"...seeking the perishable good of this life.\" (4.94) i.e. those sheep.","ar":"حَدَّثَنِي عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏وَلاَ تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلاَمَ لَسْتَ مُؤْمِنًا‏}‏‏.‏ قَالَ قَالَ ابْنُ عَبَّاسٍ كَانَ رَجُلٌ فِي غُنَيْمَةٍ لَهُ فَلَحِقَهُ الْمُسْلِمُونَ فَقَالَ السَّلاَمُ عَلَيْكُمْ، فَقَتَلُوهُ وَأَخَذُوا غُنَيْمَتَهُ، فَأَنْزَلَ اللَّهُ فِي ذَلِكَ إِلَى قَوْلِهِ ‏{‏عَرَضَ الْحَيَاةِ الدُّنْيَا‏}‏ تِلْكَ الْغُنَيْمَةُ‏.‏ قَالَ قَرَأَ ابْنُ عَبَّاسٍ السَّلاَمَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1898b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1898b","x":"It has been narrated on the authority of Bara' who said:\n\nWhen the Qur'anic verse:\" Those who sit (at home) from among mu'min\" (iv. 94) was revealed, the son of Umm Maktum spoke to him (the Holy Prophet). (At this). the words:\" other than those who have a trouble (illness)\" were revealed.","ar":"وَحَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا ابْنُ بِشْرٍ، عَنْ مِسْعَرٍ، حَدَّثَنِي أَبُو إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ لَمَّا نَزَلَتْ ‏{‏ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ كَلَّمَهُ ابْنُ أُمِّ مَكْتُومٍ فَنَزَلَتْ ‏{‏ غَيْرُ أُولِي الضَّرَرِ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3025","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3025","x":"Ibn Abbas reported that some Muslims met a person with a small flock of sheep. He said:\n\nAs-Salam-o-'Alaikum. They caught hold of him and killed him and took possession of his flock. Then this verse was revealed:\" He who meets you and extends you salutations, don't say: You are not a Muslim\" (iv. 94). Ibn 'Abbas, however, recited the word as-Salam instead of\" as-Salam\".","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَأَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ، - وَاللَّفْظُ لاِبْنِ أَبِي شَيْبَةَ - قَالَ حَدَّثَنَا وَقَالَ الآخَرَانِ، أَخْبَرَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَقِيَ نَاسٌ مِنَ الْمُسْلِمِينَ رَجُلاً فِي غُنَيْمَةٍ لَهُ فَقَالَ السَّلاَمُ عَلَيْكُمْ ‏.‏ فَأَخَذُوهُ فَقَتَلُوهُ وَأَخَذُوا تِلْكَ الْغُنَيْمَةَ فَنَزَلَتْ ‏{‏ وَلاَ تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَمَ لَسْتَ مُؤْمِنًا‏}‏ وَقَرَأَهَا ابْنُ عَبَّاسٍ السَّلاَمَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3030","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3030","x":"Narrated Ibn 'Abbas:\n\n\"A man from Banu Sulaim who had some sheep with him, passed by some of the Companions of the Messenger of Allah (ﷺ). He gave Salam to them and they said: 'He did not give Salam except to protect himself.' So they attacked him, killed him, and took his sheep. They went to the Messenger of Allah (ﷺ) with them, and Allah, Most High, revealed: O you who believe! When you go in the cause of Allah, verify and say not to anyone who greets you: \"You are not a believer (4:94).\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي رِزْمَةَ، عَنْ إِسْرَائِيلَ، عَنْ سِمَاكٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ مَرَّ رَجُلٌ مِنْ بَنِي سُلَيْمٍ عَلَى نَفَرٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَمَعَهُ غَنَمٌ لَهُ فَسَلَّمَ عَلَيْهِمْ قَالُوا مَا سَلَّمَ عَلَيْكُمْ إِلاَّ لِيَتَعَوَّذَ مِنْكُمْ فَقَامُوا فَقَتَلُوهُ وَأَخَذُوا غَنَمَهُ فَأَتَوْا بِهَا رَسُولَ اللَّهِ صلى الله عليه وسلم ‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏(‏ يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ فَتَبَيَّنُوا وَلاَ تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلاَمَ لَسْتَ مُؤْمِنًا ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَفِي الْبَابِ عَنْ أُسَامَةَ بْنِ زَيْدٍ ‏.‏","v":[]}],"95":[{"c":"Sahih Bukhari","r":"Hadith 2831","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2831","x":"Narrated Al-Bara:\n\nWhen the Divine Inspiration: \"Those of the believers who sit (at home), was revealed the Prophet (ﷺ) sent for Zaid (bin Thabit) who came with a shoulder-blade and wrote on it. Ibn Um-Maktum complained about his blindness and on that the following revelation came: \"Not equal are those believers who sit (at home) except those who are disabled (by injury, or are blind or lame etc.) and those who strive hard and fight in the Way of Allah with their wealth and lives).\" (4.95)","ar":"حَدَّثَنَا أَبُو الْوَلِيدِ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ يَقُولُ لَمَّا نَزَلَتْ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ دَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْدًا، فَجَاءَ بِكَتِفٍ فَكَتَبَهَا، وَشَكَا ابْنُ أُمِّ مَكْتُومٍ ضَرَارَتَهُ فَنَزَلَتْ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2832","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2832","x":"Narrated Sahl bin Sa`d As-Sa`idi:\n\nI saw Marwan bin Al-Hakam sitting in the Mosque. So I came forward and sat by his side. He told us that Zaid bin Thabit had told him that Allah's Messenger (ﷺ) had dictated to him the Divine Verse: \"Not equal are those believers who sit (at home) and those who strive hard and fight in the Cause of Allah with their wealth and lives.' (4.95) Zaid said, \"Ibn-Maktum came to the Prophet (ﷺ) while he was dictating to me that very Verse. On that Ibn Um Maktum said, \"O Allah's Messenger (ﷺ)! If I had power, I would surely take part in Jihad.\" He was a blind man. So Allah sent down revelation to His Apostle while his thigh was on mine and it became so heavy for me that I feared that my thigh would be broken. Then that state of the Prophet (ﷺ) was over after Allah revealed \"...except those who are disabled (by injury or are blind or lame etc.) (4.95)","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ الزُّهْرِيُّ، قَالَ حَدَّثَنِي صَالِحُ بْنُ كَيْسَانَ، عَنِ ابْنِ شِهَابٍ، عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ، أَنَّهُ قَالَ رَأَيْتُ مَرْوَانَ بْنَ الْحَكَمِ جَالِسًا فِي الْمَسْجِدِ، فَأَقْبَلْتُ حَتَّى جَلَسْتُ إِلَى جَنْبِهِ، فَأَخْبَرَنَا أَنَّ زَيْدَ بْنَ ثَابِتٍ أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَمْلَى عَلَيْهِ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ قَالَ فَجَاءَهُ ابْنُ أُمِّ مَكْتُومٍ وَهُوَ يُمِلُّهَا عَلَىَّ، فَقَالَ يَا رَسُولَ اللَّهِ، لَوْ أَسْتَطِيعُ الْجِهَادَ لَجَاهَدْتُ‏.‏ وَكَانَ رَجُلاً أَعْمَى، فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَى رَسُولِهِ صلى الله عليه وسلم وَفَخِذُهُ عَلَى فَخِذِي، فَثَقُلَتْ عَلَىَّ حَتَّى خِفْتُ أَنْ تَرُضَّ فَخِذِي، ثُمَّ سُرِّيَ عَنْهُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏غَيْرُ أُولِي الضَّرَرِ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4593","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4593","x":"Narrated Al-Bara:\n\nWhen the Verse:-- \"Not equal are those of the believers who sit (at home)\" (4.95) was revealed, Allah Apostle called for Zaid who wrote it. In the meantime Ibn Um Maktum came and complained of his blindness, so Allah revealed: \"Except those who are disabled (by injury or are blind or lame...\" etc.) (4.95)","ar":"حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتْ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ دَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْدًا فَكَتَبَهَا، فَجَاءَ ابْنُ أُمِّ مَكْتُومٍ فَشَكَا ضَرَارَتَهُ، فَأَنْزَلَ اللَّهُ ‏{‏غَيْرَ أُولِي الضَّرَرِ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4594","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4594","x":"Narrated Al-Bara:\n\nWhen the Verse:--\"Not equal are those of the believers who sit (at home),\" (4.95) was revealed, the Prophet said, \"Call so-and-so.\" That person came to him with an ink-pot and a wooden board or a shoulder scapula bone. The Prophet (ﷺ) said (to him), \"Write: 'Not equal are those believers who sit (at home) and those who strive and fight in the Cause of Allah.\" Ibn Um Maktum who was sitting behind the Prophet (ﷺ) then said, \"O Allah's Messenger (ﷺ)! I am a blind man.\" So there was revealed in the place of that Verse, the Verse:--\"Not equal are those of the believers who sit (at home) except those who are disabled (by injury, or are blind or lame etc.) and those who strive and fight in the Cause of Allah.\" (4.95)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ لَمَّا نَزَلَتْ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ ادْعُوا فُلاَنًا ‏\"‏‏.‏ فَجَاءَهُ وَمَعَهُ الدَّوَاةُ وَاللَّوْحُ أَوِ الْكَتِفُ فَقَالَ ‏\"‏ اكْتُبْ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ ‏\"‏‏.‏ وَخَلْفَ النَّبِيِّ صلى الله عليه وسلم ابْنُ أُمِّ مَكْتُومٍ فَقَالَ يَا رَسُولَ اللَّهِ أَنَا ضَرِيرٌ‏.‏ فَنَزَلَتْ مَكَانَهَا ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4635","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4635","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"The Hour will not be established until the sun rises from the West: and when the people see it, then whoever will be living on the surface of the earth will have faith, and that is (the time) when no good will it do to a soul to believe then, if it believed not before.\" (6.158)","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا عَبْدُ الْوَاحِدِ، حَدَّثَنَا عُمَارَةُ، حَدَّثَنَا أَبُو زُرْعَةَ، حَدَّثَنَا أَبُو هُرَيْرَةَ، رضى الله عنه قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ لاَ تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا، فَإِذَا رَآهَا النَّاسُ آمَنَ مَنْ عَلَيْهَا، فَذَاكَ حِينَ لاَ يَنْفَعُ نَفْسًا إِيمَانُهَا، لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4990","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4990","x":"Narrated Al-Bara:\n\nThere was revealed: 'Not equal are those believers who sit (at home) and those who strive and fight in the Cause of Allah.' (4.95) The Prophet (ﷺ) said, \"Call Zaid for me and let him bring the board, the inkpot and the scapula bone (or the scapula bone and the ink pot).\"' Then he said, \"Write: 'Not equal are those Believers who sit..\", and at that time `Amr bin Um Maktum, the blind man was sitting behind the Prophet (ﷺ). He said, \"O Allah's Apostle! What is your order For me (as regards the above Verse) as I am a blind man?\" So, instead of the above Verse, the following Verse was revealed: 'Not equal are those believers who sit (at home) except those who are disabled (by injury or are blind or lame etc.) and those who strive and fight in the cause of Allah.' (4.95)","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ لَمَّا نَزَلَتْ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ‏}‏ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ ادْعُ لِي زَيْدًا وَلْيَجِئْ بِاللَّوْحِ وَالدَّوَاةِ وَالْكَتِفِ ـ أَوِ الْكَتِفِ وَالدَّوَاةِ ـ ثُمَّ قَالَ ‏\"‏ اكْتُبْ لاَ يَسْتَوِي الْقَاعِدُونَ ‏\"‏ وَخَلْفَ ظَهْرِ النَّبِيِّ صلى الله عليه وسلم عَمْرُو بْنُ أُمِّ مَكْتُومٍ الأَعْمَى قَالَ يَا رَسُولَ اللَّهِ فَمَا تَأْمُرُنِي فَإِنِّي رَجُلٌ ضَرِيرُ الْبَصَرِ فَنَزَلَتْ مَكَانَهَا ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ فِي سَبِيلِ اللَّهِ ‏{‏غَيْرُ أُولِي الضَّرَرِ‏}‏‏\"‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1898a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1898a","x":"It has been narrated on the authority of Abu Ishaq, that he heard Bara' talking about the Qur'anic verse:\n\n\" Those who sit (at home) from among the believers and those who go out for Jihad in the way of Allah are not aqual\" (iv. 95). (He said that) the Messenger of Allah (ﷺ) ordered Zaid (to write the verse). He brought a shoulder-blade (of a slaughtered camel) and inscribed it (the verse) thereon. The son of Umm Maktum complained of his blindness to the Prophet (ﷺ). (At this) descended the revelation:\" Those of the believers who sit (at home) without any trouble (illness, incapacity, disability)\" (iv. 95). The tradition has been handed down through two other chains of transmitters.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ بَشَّارٍ، - وَاللَّفْظُ لاِبْنِ الْمُثَنَّى - قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، أَنَّهُ سَمِعَ الْبَرَاءَ، يَقُولُ فِي هَذِهِ الآيَةِ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْدًا فَجَاءَ بِكَتِفٍ يَكْتُبُهَا فَشَكَا إِلَيْهِ ابْنُ أُمِّ مَكْتُومٍ ضَرَارَتَهُ فَنَزَلَتْ ‏{‏ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ‏}‏ قَالَ شُعْبَةُ وَأَخْبَرَنِي سَعْدُ بْنُ إِبْرَاهِيمَ عَنْ رَجُلٍ عَنْ زَيْدِ بْنِ ثَابِتٍ فِي هَذِهِ الآيَةِ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ بِمِثْلِ حَدِيثِ الْبَرَاءِ وَقَالَ ابْنُ بَشَّارٍ فِي رِوَايَتِهِ سَعْدُ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ رَجُلٍ عَنْ زَيْدِ بْنِ ثَابِتٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 21, Hadith 1670","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-21/Hadith-1670","x":"Narrated Al-Bara' bin 'Azib:\n\nThat the Messenger of Allah (ﷺ) said: \"Bring me a shoulder blade or tablet.\" Then he wrote: Not equal are those of believers who sit. 'Amr bin Umm Maktum who was behind him said: \"Is there an exemption for me?\" So the following was revealed: Except those who are disabled. There are narrations on this topic from Ibn 'Abbas, Jabir and Zaid bin Thabit. This Hadith is Hasan Sahih and it is a Hadith that is Gharib from the narration of Sulaiman At-Taimi from Abu Ishaq. And Shu'bah and Ath-Thawri reported this Hadith from Abu Ishaq.","ar":"حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، حَدَّثَنَا الْمُعْتَمِرُ بْنُ سُلَيْمَانَ، عَنْ أَبِيهِ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ ائْتُونِي بِالْكَتِفِ أَوِ اللَّوْحِ ‏\"‏ ‏.‏ فَكَتَبَ ‏:‏ ‏(‏ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ ‏)‏ وَعَمْرُو بْنُ أُمِّ مَكْتُومٍ خَلْفَ ظَهْرِهِ فَقَالَ هَلْ لِي مِنْ رُخْصَةٍ فَنَزَلَتْ ‏:‏ ‏(‏ غَيْرُ أُولِي الضَّرَرِ ‏)‏ ‏.‏ وَفِي الْبَابِ عَنِ ابْنِ عَبَّاسٍ وَجَابِرٍ وَزَيْدِ بْنِ ثَابِتٍ ‏.‏ وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَهُوَ حَدِيثٌ غَرِيبٌ مِنْ حَدِيثِ سُلَيْمَانَ التَّيْمِيِّ عَنْ أَبِي إِسْحَاقَ ‏.‏ وَقَدْ رَوَى شُعْبَةُ وَالثَّوْرِيُّ عَنْ أَبِي إِسْحَاقَ هَذَا الْحَدِيثَ ‏.","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3031","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3031","x":"Narrated Al-Bara bin 'Azib:\n\n\"When the following was revealed: 'Not equal are those of the believers who sit (4:95)' 'Amr bin Umm Maktum came to the Prophet (ﷺ).\" He said: \"He was blind, so he said: 'O Messenger of Allah! What do you order me with? Indeed my vision is disabled.' So Allah [Most High] revealed this Ayah: 'Except those who are disabled.' So the Prophet (ﷺ) said: 'Bring me a shoulder bone and inkwell' - or 'Bring me a tablet and an inkwell.'\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ لَمَّا نَزَلَتْ ‏:‏ ‏(‏لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ ‏)‏ جَاءَ عَمْرُو ابْنُ أُمِّ مَكْتُومٍ إِلَى النَّبِيِّ صلى الله عليه وسلم - قَالَ وَكَانَ ضَرِيرَ الْبَصَرِ فَقَالَ يَا رَسُولَ اللَّهِ مَا تَأْمُرُنِي إِنِّي ضَرِيرُ الْبَصَرِ فَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الآيَةَ ‏:‏ ‏(‏ غَيْرُ أُولِي الضَّرَرِ ‏)‏ الآيَةَ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ ائْتُونِي بِالْكَتِفِ وَالدَّوَاةِ أَوِ اللَّوْحِ وَالدَّوَاةِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَيُقَالُ عَمْرُو ابْنُ أُمِّ مَكْتُومٍ وَيُقَالُ عَبْدُ اللَّهِ ابْنُ أُمِّ مَكْتُومٍ وَهُوَ عَبْدُ اللَّهِ بْنُ زَائِدَةَ وَأُمُّ مَكْتُومٍ أُمُّهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3032","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3032","x":"Narrated Miqsam, the freed slave of 'Abdullah bin Al-Harith:\n\nfrom Ibn 'Abbas that he said the Ayah: Not equal are those of the believers who sit, except those who are disabled... (4:95) is about Badr and those went out for Badr. At the time of the battle of Badr, 'Abdullah bin Jahsh and Ibn Umm Maktum said: 'We are blind O Messenger of Allah! So is there an exemption for us?' So the following was revealed: Not equal are those of the believers who sit except those who are disabled. But Allah has preferred those who strive hard and fight above those who sit (at home) by a huge reward (4:95). So these were the people who sat behind, that were not disabled: But Allah has preferred those who strive hard and fight, above those who sit (at home) by a huge reward - they are of levels above those who sit among the believers who did not have an excuse.\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ مُحَمَّدٍ الزَّعْفَرَانِيُّ، حَدَّثَنَا الْحَجَّاجُ بْنُ مُحَمَّدٍ، عَنِ ابْنِ جُرَيْجٍ، أَخْبَرَنِي عَبْدُ الْكَرِيمِ، سَمِعَ مِقْسَمًا، مَوْلَى عَبْدِ اللَّهِ بْنِ الْحَارِثِ يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ قَالَ ‏:‏ ‏(‏ لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ ‏)‏ عَنْ بَدْرٍ وَالْخَارِجُونَ إِلَى بَدْرٍ لَمَّا نَزَلَتْ غَزْوَةُ بَدْرٍ قَالَ عَبْدُ اللَّهِ بْنُ جَحْشٍ وَابْنُ أُمِّ مَكْتُومٍ إِنَّا أَعْمَيَانِ يَا رَسُولَ اللَّهِ فَهَلْ لَنَا رُخْصَةٌ فَنَزَلَتْ ‏:‏ ‏(‏ لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ ‏)‏ و ‏:‏ ‏‏(‏‏فَضَّلَ اللَّهُ الْمُجَاهِدِينَ عَلََى الْقَاعِدِينَ دَرَجَةً ‏ ‏)‏ فَهَؤُلاَءِ الْقَاعِدُونَ غَيْرُ أُولِي الضَّرَرِ ‏:‏ ‏(‏ وَفَضَّلَ اللَّهُ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ أَجْرًا عَظِيمًا )‏ دَرَجَاتٍ مِنْهُ عَلَى الْقَاعِدِينَ مِنَ الْمُؤْمِنِينَ غَيْرِ أُولِي الضَّرَرِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ ابْنِ عَبَّاسٍ وَمِقْسَمٌ يُقَالُ هُوَ مَوْلَى عَبْدِ اللَّهِ بْنِ الْحَارِثِ وَيُقَالُ هُوَ مَوْلَى عَبْدِ اللَّهِ بْنِ عَبَّاسٍ وَكُنْيَتُهُ أَبُو الْقَاسِمِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3033","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3033","x":"Narrated Sahl bin Sa'd As-Sa'idi:\n\n\"I saw Marwan bin Al-Hakam sitting in the Masjid, so I went over to him until I sat next to him. He informed us that Zaid bin Thabit informed him, that the Prophet (ﷺ) dictated: 'Not equal among the believers are those who sit and the Mujahidin in the cause of Allah.' He said: 'So Ibn Umm Maktum came and he was dictating to me that he said: \"O Messenger of Allah! By Allah! If I were capable of Jihad then I would participate in Jihad.' And he was a blind a man. So Allah revealed to His Messenger (ﷺ) - while his thigh was against my thigh - and it became so heavy that I was worried it was about to fracture my thigh. Then he was relieved of it, so Allah had revealed to him: Except those who are disabled.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ، عَنْ أَبِيهِ، عَنْ صَالِحِ بْنِ كَيْسَانَ، عَنِ ابْنِ شِهَابٍ، حَدَّثَنِي سَهْلُ بْنُ سَعْدٍ، قَالَ رَأَيْتُ مَرْوَانَ بْنَ الْحَكَمِ جَالِسًا فِي الْمَسْجِدِ فَأَقْبَلْتُ حَتَّى جَلَسْتُ إِلَى جَنْبِهِ فَأَخْبَرَنَا أَنَّ زَيْدَ بْنَ ثَابِتٍ أَخْبَرَهُ أَنَّ النَّبِيَّ صلى الله عليه وسلم أَمْلَى عَلَيْهِ لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ قَالَ فَجَاءَهُ ابْنُ أُمِّ مَكْتُومٍ وَهُوَ يُمْلِيهَا عَلَىَّ فَقَالَ يَا رَسُولَ اللَّهِ وَاللَّهِ لَوْ أَسْتَطِيعُ الْجِهَادَ لَجَاهَدْتُ وَكَانَ رَجُلاً أَعْمَى ‏.‏ فَأَنْزَلَ اللَّهُ عَلَى رَسُولِهِ صلى الله عليه وسلم وَفَخِذُهُ عَلَى فَخِذِي فَثَقُلَتْ حَتَّى هَمَّتْ تَرُضُّ فَخِذِي ثُمَّ سُرِّيَ عَنْهُ فَأَنْزَلَ اللَّهُ عَلَيْهِ ‏:‏ ‏(‏ غَيْرُ أُولِي الضَّرَرِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ هَكَذَا رَوَى غَيْرُ وَاحِدٍ عَنِ الزُّهْرِيِّ عَنْ سَهْلِ بْنِ سَعْدٍ نَحْوَ هَذَا ‏.‏ وَرَوَى مَعْمَرٌ عَنِ الزُّهْرِيِّ هَذَا الْحَدِيثَ عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ عَنْ زَيْدِ بْنِ ثَابِتٍ ‏.‏ وَفِي هَذَا الْحَدِيثِ رِوَايَةُ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم عَنْ رَجُلٍ مِنَ التَّابِعِينَ رَوَاهُ سَهْلُ بْنُ سَعْدٍ الأَنْصَارِيُّ عَنْ مَرْوَانَ بْنِ الْحَكَمِ وَمَرْوَانُ لَمْ يَسْمَعْ مِنَ النَّبِيِّ صلى الله عليه وسلم وَهُوَ مِنَ التَّابِعِينَ ‏.‏","v":[]}],"97":[{"c":"Sahih Bukhari","r":"Hadith 4596","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4596","x":"Narrated Muhammad bin `Abdur-Rahman Abu Al-Aswad:\n\nThe people of Medina were forced to prepare an army (to fight against the people of Sham during the caliphate of `Abdullah bin Az-Zubair at Mecca), and I was enlisted in it; Then I met `Ikrima, the freed slave of Ibn `Abbas, and informed him (about it), and he forbade me strongly to do so (i.e. to enlist in that army), and then said, \"Ibn `Abbas informed me that some Muslim people were with the pagans, increasing the number of the pagans against Allah's Messenger (ﷺ). An arrow used to be shot which would hit one of them (the Muslims in the company of the pagans) and kill him, or he would be struck and killed (with a sword).\" Then Allah revealed:-- \"Verily! as for those whom the angels take (in death) while they are wronging themselves (by staying among the disbelievers)\" (4.97) Abu AlAswad also narrated it.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ، حَدَّثَنَا حَيْوَةُ، وَغَيْرُهُ، قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ أَبُو الأَسْوَدِ، قَالَ قُطِعَ عَلَى أَهْلِ الْمَدِينَةِ بَعْثٌ فَاكْتُتِبْتُ فِيهِ، فَلَقِيتُ عِكْرِمَةَ مَوْلَى ابْنِ عَبَّاسٍ فَأَخْبَرْتُهُ، فَنَهَانِي عَنْ ذَلِكَ أَشَدَّ النَّهْىِ، ثُمَّ قَالَ أَخْبَرَنِي ابْنُ عَبَّاسٍ أَنَّ نَاسًا مِنَ الْمُسْلِمِينَ كَانُوا مَعَ الْمُشْرِكِينَ يُكَثِّرُونَ سَوَادَ الْمُشْرِكِينَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم يَأْتِي السَّهْمُ فَيُرْمَى بِهِ، فَيُصِيبُ أَحَدَهُمْ فَيَقْتُلُهُ أَوْ يُضْرَبُ فَيُقْتَلُ، فَأَنْزَلَ اللَّهُ ‏{‏إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلاَئِكَةُ ظَالِمِي أَنْفُسِهِمْ‏}‏ الآيَةَ‏.‏ رَوَاهُ اللَّيْثُ عَنْ أَبِي الأَسْوَدِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7085","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7085","x":"Narrated Abu Al-Aswad:\n\nAn army unit was being recruited from the people of Medina and my name was written among them. Then I met `Ikrima, and when I informed him about it, he discouraged me very strongly and said, \"Ibn `Abbas told me that there were some Muslims who were with the pagans to increase their number against Allah's Messenger (ﷺ) (and the Muslim army) so arrows (from the Muslim army) would hit one of them and kill him or a Muslim would strike him (with his sword) and kill him. So Allah revealed:-- 'Verily! As for those whom the angels take (in death) while they are wronging themselves (by staying among the disbelievers).' (4.97)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَزِيدَ، حَدَّثَنَا حَيْوَةُ، وَغَيْرُهُ، قَالاَ حَدَّثَنَا أَبُو الأَسْوَدِ،‏.‏ وَقَالَ اللَّيْثُ عَنْ أَبِي الأَسْوَدِ، قَالَ قُطِعَ عَلَى أَهْلِ الْمَدِينَةِ بَعْثٌ فَاكْتُتِبْتُ فِيهِ فَلَقِيتُ عِكْرِمَةَ فَأَخْبَرْتُهُ فَنَهَانِي أَشَدَّ النَّهْىِ ثُمَّ قَالَ أَخْبَرَنِي ابْنُ عَبَّاسٍ أَنَّ أُنَاسًا مِنَ الْمُسْلِمِينَ كَانُوا مَعَ الْمُشْرِكِينَ يُكَثِّرُونَ سَوَادَ الْمُشْرِكِينَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَيَأْتِي السَّهْمُ فَيُرْمَى فَيُصِيبُ أَحَدَهُمْ، فَيَقْتُلُهُ أَوْ يَضْرِبُهُ فَيَقْتُلُهُ‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلاَئِكَةُ ظَالِمِي أَنْفُسِهِمْ‏}‏","v":[]}],"98":[{"c":"Sahih Bukhari","r":"Hadith 4588","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4588","x":"Narrated Ibn Abi Mulaika:\n\nIbn `Abbas recited:-- \"Except the weak ones among men women and children,\" (4.98) and said, \"My mother and I were among those whom Allah had excused.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ أَيُّوبَ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، أَنَّ ابْنَ عَبَّاسٍ، تَلاَ ‏{‏ِلاَّ الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ‏}‏ قَالَ كُنْتُ أَنَا وَأُمِّي مِمَّنْ عَذَرَ اللَّهُ‏.‏ وَيُذْكَرُ عَنِ ابْنِ عَبَّاسٍ ‏{‏حَصِرَتْ‏}‏ ضَاقَتْ ‏{‏تَلْوُوا‏}‏ أَلْسِنَتَكُمْ بِالشَّهَادَةِ‏.‏ وَقَالَ غَيْرُهُ الْمُرَاغَمُ الْمُهَاجَرُ‏.‏ رَاغَمْتُ هَاجَرْتُ قَوْمِي‏.‏ ‏{‏مَوْقُوتًا‏}‏ مُوَقَّتًا وَقْتَهُ عَلَيْهِمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4597","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4597","x":"Narrated Ibn `Abbas:\n\n'\"Except the weak ones\" (4.98) and added: My mother was one of those whom Allah excused.","ar":"حَدَّثَنَا أَبُو النُّعْمَانِ، حَدَّثَنَا حَمَّادٌ، عَنْ أَيُّوبَ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏إِلاَّ الْمُسْتَضْعَفِينَ‏}‏ قَالَ كَانَتْ أُمِّي مِمَّنْ عَذَرَ اللَّهُ‏.‏","v":[]}],"101":[{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1065","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1065","x":"It was narrated that Ya’la bin Umayyah said:\n\n\"I asked ‘Umar bin Khattab: ‘Allah says: \"And when you travel in the land, there is no sin on you if you shorten the prayer if you fear that the disbelievers may put you in trial (attack you), verily, the disbelievers are ever to you open enemies,\" [4:101] but now there is security and people are safe.’ He said: ‘I found it strange just as you do, so I asked the Messenger of Allah (ﷺ) about that, and he said: \"It is charity that Allah has bestowed upon you, so accept His charity.\"","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، عَنِ ابْنِ جُرَيْجٍ، عَنِ ابْنِ أَبِي عَمَّارٍ، عَنْ عَبْدِ اللَّهِ بْنِ بَابَيْهِ، عَنْ يَعْلَى بْنِ أُمَيَّةَ، قَالَ سَأَلْتُ عُمَرَ بْنَ الْخَطَّابِ قُلْتُ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلاَةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا وَقَدْ أَمِنَ النَّاسُ فَقَالَ عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ فَسَأَلْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ عَنْ ذَلِكَ فَقَالَ ‏\n\n\"‏ صَدَقَةٌ تَصَدَّقَ اللَّهُ بِهَا عَلَيْكُمْ، فَاقْبَلُوا صَدَقَتَهُ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 686a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-686a","x":"Yahya b. Umayya said:\n\nI told 'Umar b. al-Khattab that Allah had said:\" You may shorten the prayer only if you fear that those who are unbelievers may afflict you\" (Qur'an, iv. 101), whereas the people are now safe. He replied: I wondered about it in the same way as you wonder about it, so I asked the Messenger of Allah (ﷺ) about it and he said: It is an act of charity which Allah has done to you, so accept His charity.","ar":"وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ وَزُهَيْرُ بْنُ حَرْبٍ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ الآخَرُونَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، عَنِ ابْنِ جُرَيْجٍ، عَنِ ابْنِ أَبِي عَمَّارٍ، عَنْ عَبْدِ اللَّهِ بْنِ بَابَيْهِ، عَنْ يَعْلَى بْنِ أُمَيَّةَ، قَالَ قُلْتُ لِعُمَرَ بْنِ الْخَطَّابِ ‏{‏ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا، مِنَ الصَّلاَةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا‏}‏ فَقَدْ أَمِنَ النَّاسُ فَقَالَ عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ فَسَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ ذَلِكَ ‏.‏ فَقَالَ ‏\"‏ صَدَقَةٌ تَصَدَّقَ اللَّهُ بِهَا عَلَيْكُمْ فَاقْبَلُوا صَدَقَتَهُ ‏\"‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3034","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3034","x":"Narrated Ya'la bin Umayyah:\n\n\"I said to 'Umar [bin Al-Khattab]: 'Allah said: That you shorten the Salat if you fear and the people are safe (4:101).' So 'Umar said: 'I wondered about that just as you have wondered. So I mentioned that to the Messenger of Allah (ﷺ), and he said: \"It is charity which Allah has given to you, so accept His charity.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، قَالَ سَمِعْتُ عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي عَمَّارٍ، يُحَدِّثُ عَنْ عَبْدِ اللَّهِ بْنِ بَابَاهُ، عَنْ يَعْلَى بْنِ أُمَيَّةَ، قَالَ قُلْتُ لِعُمَرَ بْنِ الْخَطَّابِ إِنَّمَا قَالَ اللَّهُ ‏:‏ ‏(‏ أَنْ تَقْصُرُوا مِنَ الصَّلاَةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا ‏)‏ وَقَدْ أَمِنَ النَّاسُ ‏.‏ فَقَالَ عُمَرُ عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ صَدَقَةٌ تَصَدَّقَ اللَّهُ بِهَا عَلَيْكُمْ فَاقْبَلُوا صَدَقَتَهُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"102":[{"c":"Sahih Bukhari","r":"Hadith 4599","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4599","x":"Narrated Ibn `Abbas:\n\nRegarding the Verse: \"Because of the inconvenience of rain or because you are ill.\" (4.102) (It was revealed in connection with) `Abdur-Rahman bin `Auf who was wounded.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ مُقَاتِلٍ أَبُو الْحَسَنِ، أَخْبَرَنَا حَجَّاجٌ، عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي يَعْلَى، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏إِنْ كَانَ بِكُمْ أَذًى مِنْ مَطَرٍ أَوْ كُنْتُمْ مَرْضَى‏}‏ قَالَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفِ كَانَ جَرِيحًا‏.‏","v":[]}],"105":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"106":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"107":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"108":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"109":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"110":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"111":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"112":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"113":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"114":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"115":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]}],"116":[{"c":"Sahih Bukhari","r":"Hadith 2766","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2766","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"Avoid the seven great destructive sins.\" The people enquire, \"O Allah's Messenger (ﷺ)! What are they? \"He said, \"To join others in worship along with Allah, to practice sorcery, to kill the life which Allah has forbidden except for a just cause, (according to Islamic law), to eat up Riba (usury), to eat up an orphan's wealth, to give back to the enemy and fleeing from the battlefield at the time of fighting, and to accuse, chaste women, who never even think of anything touching chastity and are good believers.","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ ثَوْرِ بْنِ زَيْدٍ الْمَدَنِيِّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ ‏\"‏‏.‏ قَالُوا يَا رَسُولَ اللَّهِ، وَمَا هُنَّ قَالَ ‏\"‏ الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ ‏\"‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3036","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3036","x":"Narrated Qatadah bin An-Nu'man:\n\n\"There was a household among us called Banu Ubairiq, among whom was a Bishr, a Bushair, and a Mubashshir. Bushair was a hypocrite who would recite poetry reviling the Companions of the Prophet (ﷺ) then he would attribute it to some of the Arabs. Then he would say: 'So-and-so said this and that [So-and-so said this and that].' So when the Companions of the Prophet (ﷺ) would hear that poetry, they would say: 'By Allah! No one but this filthy person said this poetry - or as the man said - and they would say: 'Ibn Al-Ubairiq said it.'\" He said: \"They were a poor and needy household during Jahiliyyah and Islam. The only food the people of Al-Madinah had was dates and barely. When a man was able to, he would import flour from Ash-Sham which he bought and kept for himself. As for his dependants, their only food was dates and barely. So an import arrived from Ash-Sham, and my uncle Rifa'ah bin Zaid bought a load of it, which he put in a storage area he had, where he kept his weapons - his shield and his sword. But it was taken from him from under the house. The storage was broken into and and the food and weapons were taken. In the morning, my uncle Rifa'ah came to me and said: 'O my nephew! We were robbed during the night, our storage was broken into, and our food and weapons are gone.'\" He said: \"They overheard us in the house, and questioned us, and someone said to us, 'We saw Banu Ubairiq cooking during the night, and it looked like they had some of your food.'\" He said: \"Banu Ubairiq were saying - while we were questioning them amidst their dwellings - 'By Allah! We do not think the one you are looking for is other than Labid bin Sahl, a man among us who is righteous and accepted Islam.' When Labid heard that, he brandished his sword and said: 'I stole? By Allah! You either prove this theft, or I take to you with this sword.' They said: 'Leave us O man! You are not the one who has it.' So we continued questioning in the dwellings until we had no doubt that they had taken it. So my uncle said to me: 'O my nephew! You should go to the Messenger of Allah (ﷺ) and tell him about that.'\" Qatadah said: \"So I went to the Messenger of Allah (ﷺ) and said: 'A family among us are ill-mannered, and they conspired against my uncle Rifa'ah bin aid. They broken into his storage and took his weapons and his food. We want them to return our weapons, but we have no need for the food.' So the Prophet (ﷺ) said: 'I will decide about that.' So when Banu Ubairiq heard about that, they brought a man from among them named Usair bin 'Urwah to talk to him about that, and some people form their houses gathered and said: 'O Messenger of Allah! Qatadah bin An-Nu'man and his uncle came came to a family among us who are a people of Islam and righteousness, accusing them of stealing without proof or confirmation.'\" Qatadah said: \"I went to the Messenger of Allah (ﷺ) and spoke to him, and he said: 'You went to a family among them known for their Islam and righteousness, and accused them of stealing without confirmation or proof.'\" He said: \"So I returned wishing that I had lost some of my wealth, and that the Messenger of Allah (ﷺ) had not been spoke to about that. My uncle Rifa'ah came to me and said: 'O my nephew! What did you do?' So I told him what the Messenger of Allah (ﷺ) said to me, so he said: 'It is from Allah, Whom we seek help.' It was not long before the Qur'an was revealed: 'Surely, We have sent down to you the Book in truth, that you might judge between men by that which Allah has shown you, so be not a pelader for the treacherous.' That is Banu Ubairiq. 'And seek forgiveness from Allah.' [That is] from what you said to Qatadah. 'Certainly Allah is Oft-Forgiving, Most Merciful. And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer, sinner. They may hide from men, but they cannot hide from Allah for He is with them up to His saying: 'Most Merciful.' That is: If you seek Allah's forgiveness then He will forgive you. 'And whoever earns sin, he earns it only against himself...' up to His saying: 'A manifest sin.' Their saying about Labid; 'Had it not been for the grace of Allah and His Mercy upon you...' up to His saying: 'We shall give him a great reward.' (4:105-115)\" So when the Qur'an was revealed, the Messenger of Allah (ﷺ) brought the weapon and returned it to Rifa'ah. Qatadah said: \"When the weapon was brought to my uncle - and he was an elderly man with bad sight\" or \"an elderly weak man\" - Abu 'Eisa was in doubt - \"in Jahiliyyah, and I thought that he merely had entered into Islam (without real sincerity) but when I brought it to him, he said: 'O my nephew! It is for Allah's cause.' So I knew that his Islam was genuine. When the Qur'an was revealed, Bushair went with the idolaters, staying with Sulafah bint Sa'd bin Sumayyah. So Allah, Most High, revealed: Whoever contradicts and opposes the Messenger after the right path has been shown clearly to him, and follows other than the believers' way, We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination. Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills. And whoever associates others with Allah, then he has indeed strayed away (4:115-116). \"When he went to stay with Sulafah, Hassan bin Thabit lampooned her with verses of poetry. So she took his saddle, put it on her head, then she left with it to cast into the valley. Then she said: 'You gave me the poetry of Hassan - you did not bring me any good.'\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ أَبُو مُسْلِمٍ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَتَادَةَ بْنِ النُّعْمَانِ قَالَ كَانَ أَهْلُ بَيْتٍ مِنَّا يُقَالُ لَهُمْ بَنُو أُبَيْرِقٍ بِشْرٌ وَبَشِيرٌ وَمُبَشِّرٌ وَكَانَ بَشِيرٌ رَجُلاً مُنَافِقًا يَقُولُ الشِّعْرَ يَهْجُو بِهِ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ يَنْحَلُهُ بَعْضَ الْعَرَبِ ثُمَّ يَقُولُ قَالَ فُلاَنٌ كَذَا وَكَذَا قَالَ فُلاَنٌ كَذَا وَكَذَا فَإِذَا سَمِعَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَلِكَ الشِّعْرَ قَالُوا وَاللَّهِ مَا يَقُولُ هَذَا الشِّعْرَ إِلاَّ هَذَا الْخَبِيثُ أَوْ كَمَا قَالَ الرَّجُلُ وَقَالُوا ابْنُ الأُبَيْرِقِ قَالَهَا قَالَ وَكَانَ أَهْلُ بَيْتِ حَاجَةٍ وَفَاقَةٍ فِي الْجَاهِلِيَّةِ وَالإِسْلاَمِ وَكَانَ النَّاسُ إِنَّمَا طَعَامُهُمْ بِالْمَدِينَةِ التَّمْرُ وَالشَّعِيرُ وَكَانَ الرَّجُلُ إِذَا كَانَ لَهُ يَسَارٌ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ مِنَ الدَّرْمَكِ ابْتَاعَ الرَّجُلُ مِنْهَا فَخَصَّ بِهَا نَفْسَهُ وَأَمَّا الْعِيَالُ فَإِنَّمَا طَعَامُهُمُ التَّمْرُ وَالشَّعِيرُ فَقَدِمَتْ ضَافِطَةٌ مِنَ الشَّامِ فَابْتَاعَ عَمِّي رِفَاعَةُ بْنُ زَيْدٍ حِمْلاً مِنَ الدَّرْمَكِ فَجَعَلَهُ فِي مَشْرَبَةٍ لَهُ وَفِي الْمَشْرَبَةِ سِلاَحٌ وَدِرْعٌ وَسَيْفٌ فَعُدِيَ عَلَيْهِ مِنْ تَحْتِ الْبَيْتِ فَنُقِبَتِ الْمَشْرَبَةُ وَأُخِذَ الطَّعَامُ وَالسِّلاَحُ فَلَمَّا أَصْبَحَ أَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي إِنَّهُ قَدْ عُدِيَ عَلَيْنَا فِي لَيْلَتِنَا هَذِهِ فَنُقِبَتْ مَشْرَبَتُنَا فَذُهِبَ بِطَعَامِنَا وَسِلاَحِنَا ‏.‏ قَالَ فَتَحَسَّسْنَا فِي الدَّارِ وَسَأَلْنَا فَقِيلَ لَنَا قَدْ رَأَيْنَا بَنِي أُبَيْرِقٍ اسْتَوْقَدُوا فِي هَذِهِ اللَّيْلَةِ وَلاَ نُرَى فِيمَا نُرَى إِلاَّ عَلَى بَعْضِ طَعَامِكُمْ ‏.‏ قَالَ وَكَانَ بَنُو أُبَيْرِقٍ قَالُوا وَنَحْنُ نَسْأَلُ فِي الدَّارِ وَاللَّهِ مَا نُرَى صَاحِبَكُمْ إِلاَّ لَبِيدَ بْنَ سَهْلٍ رَجُلٌ مِنَّا لَهُ صَلاَحٌ وَإِسْلاَمٌ فَلَمَّا سَمِعَ لَبِيدٌ اخْتَرَطَ سَيْفَهُ وَقَالَ أَنَا أَسْرِقُ فَوَاللَّهِ لَيُخَالِطَنَّكُمْ هَذَا السَّيْفُ أَوْ لَتُبَيِّنُنَّ هَذِهِ السَّرِقَةَ ‏.‏ قَالُوا إِلَيْكَ عَنْهَا أَيُّهَا الرَّجُلُ فَمَا أَنْتَ بِصَاحِبِهَا ‏.‏ فَسَأَلْنَا فِي الدَّارِ حَتَّى لَمْ نَشُكَّ أَنَّهُمْ أَصْحَابُهَا فَقَالَ لِي عَمِّي يَا ابْنَ أَخِي لَوْ أَتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرْتَ ذَلِكَ لَهُ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أَهْلَ بَيْتٍ مِنَّا أَهْلَ جَفَاءٍ عَمَدُوا إِلَى عَمِّي رِفَاعَةَ بْنِ زَيْدٍ فَنَقَبُوا مَشْرَبَةً لَهُ وَأَخَذُوا سِلاَحَهُ وَطَعَامَهُ فَلْيَرُدُّوا عَلَيْنَا سِلاَحَنَا فَأَمَّا الطَّعَامُ فَلاَ حَاجَةَ لَنَا فِيهِ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ سَآمُرُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَلَمَّا سَمِعَ بَنُو أُبَيْرِقٍ أَتَوْا رَجُلاً مِنْهُمْ يُقَالُ لَهُ أَسِيرُ بْنُ عُرْوَةَ فَكَلَّمُوهُ فِي ذَلِكَ فَاجْتَمَعَ فِي ذَلِكَ نَاسٌ مِنْ أَهْلِ الدَّارِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ قَتَادَةَ بْنَ النُّعْمَانِ وَعَمَّهُ عَمَدَا إِلَى أَهْلِ بَيْتٍ مِنَّا أَهْلِ إِسْلاَمٍ وَصَلاَحٍ يَرْمُونَهُمْ بِالسَّرِقَةِ مِنْ غَيْرِ بَيِّنَةٍ وَلاَ ثَبْتٍ ‏.‏ قَالَ قَتَادَةُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَكَلَّمْتُهُ فَقَالَ ‏\"‏ عَمَدْتَ إِلَى أَهْلِ بَيْتٍ ذُكِرَ مِنْهُمْ إِسْلاَمٌ وَصَلاَحٌ تَرْمِيهِمْ بِالسَّرِقَةِ عَلَى غَيْرِ ثَبْتٍ وَلاَ بَيِّنَةٍ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ وَلَوَدِدْتُ أَنِّي خَرَجْتُ مِنْ بَعْضِ مَالِي وَلَمْ أُكَلِّمْ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي ذَلِكَ فَأَتَانِي عَمِّي رِفَاعَةُ فَقَالَ يَا ابْنَ أَخِي مَا صَنَعْتَ فَأَخْبَرْتُهُ بِمَا قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ اللَّهُ الْمُسْتَعَانُ فَلَمْ يَلْبَثْ أَنْ نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلاَ تَكُنْ لِلْخَائِنِينَ خَصِيمًا ‏)‏ بَنِي أُبَيْرِقٍ ‏:‏ ‏(‏ وَاسْتَغْفِرِ اللَّهَ ‏)‏ أَىْ مِمَّا قُلْتَ لِقَتَادَةَ ‏:‏ ‏(‏ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا * وَلاَ تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لاَ يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا * يَسْتَخْفُونَ مِنَ النَّاسِ وَلاَ يَسْتَخْفُونَ مِنَ اللَّهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ غَفُورًا رَحِيمًا ‏)‏ أَىْ لَوِ اسْتَغْفَرُوا اللَّهَ لَغَفَرَ لَهُمْ ‏:‏ ‏(‏ وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ إِثْمًا مُبِينًا ‏)‏ قَوْلُهُمْ لِلَبِيدٍ ‏:‏ وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا ‏)‏ فَلَمَّا نَزَلَ الْقُرْآنُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالسِّلاَحِ فَرَدَّهُ إِلَى رِفَاعَةَ فَقَالَ قَتَادَةُ لَمَّا أَتَيْتُ عَمِّي بِالسِّلاَحِ وَكَانَ شَيْخًا قَدْ عَسِيَ أَوْ عَشِيَ فِي الْجَاهِلِيَّةِ وَكُنْتُ أُرَى إِسْلاَمَهُ مَدْخُولاً فَلَمَّا أَتَيْتُهُ بِالسِّلاَحِ قَالَ يَا ابْنَ أَخِي هُوَ فِي سَبِيلِ اللَّهِ فَعَرَفْتُ أَنَّ إِسْلاَمَهُ كَانَ صَحِيحًا فَلَمَّا نَزَلَ الْقُرْآنُ لَحِقَ بَشِيرٌ بِالْمُشْرِكِينَ فَنَزَلَ عَلَى سُلاَفَةَ بِنْتِ سَعْدِ ابْنِ سُمَيَّةَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا * إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلاَلاً بَعِيدًا ‏)‏ فَلَمَّا نَزَلَ عَلَى سُلاَفَةَ رَمَاهَا حَسَّانُ بْنُ ثَابِتٍ بِأَبْيَاتٍ مِنْ شِعْرِهِ فَأَخَذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلَى رَأْسِهَا ثُمَّ خَرَجَتْ بِهِ فَرَمَتْ بِهِ فِي الأَبْطَحِ ثُمَّ قَالَتْ أَهْدَيْتَ لِي شِعْرَ حَسَّانَ مَا كُنْتَ تَأْتِينِي بِخَيْرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ مُحَمَّدِ بْنِ سَلَمَةَ الْحَرَّانِيِّ ‏.‏ وَرَوَى يُونُسُ بْنُ بُكَيْرٍ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ مُرْسَلٌ لَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ عَنْ جَدِّهِ وَقَتَادَةُ بْنُ النُّعْمَانِ هُوَ أَخُو أَبِي سَعِيدٍ الْخُدْرِيِّ لأُمِّهِ وَأَبُو سَعِيدٍ الْخُدْرِيُّ اسْمُهُ سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3037","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3037","x":"Narrated Thuwair - Ibn Abi Fakhitah:\n\nfrom his father that 'Ali bin Abi Talib said: \"There is no Ayah in the Qur'an more beloved to me than this Ayah: Verily Allah forgives not associating others with Him, but He forgives what is less than that for whomever He wills (4:116).\"","ar":"حَدَّثَنَا خَلاَّدُ بْنُ أَسْلَمَ الْبَغْدَادِيُّ، حَدَّثَنَا النَّضْرُ بْنُ شُمَيْلٍ، عَنْ إِسْرَائِيلَ، عَنْ ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ، عَنْ أَبِيهِ، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ مَا فِي الْقُرْآنِ آيَةٌ أَحَبُّ إِلَىَّ مِنْ هَذِهِ الآيَةِ ‏:‏ ‏(‏ إِنَّ اللَّهَ لاَ يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ ‏)‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ وَأَبُو فَاخِتَةَ اسْمُهُ سَعِيدُ بْنُ عِلاَقَةَ وَثُوَيْرٌ يُكْنَى أَبَا جَهْمٍ وَهُوَ رَجُلٌ كُوفِيٌّ مِنَ التَّابِعِينَ وَقَدْ سَمِعَ مِنِ ابْنِ عُمَرَ وَابْنِ الزُّبَيْرِ ‏.‏ وَابْنُ مَهْدِيٍّ كَانَ يَغْمِزُهُ قَلِيلاً ‏.‏","v":[]}],"123":[{"c":"Sunan Abu Dawud","r":"Hadith 3099","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3099","x":"The tradition mentioned above has also been transmitted by 'Ali from the Prophet (ﷺ) through a different chain of narrators to the same effect. This version does not mention the word \"garden\" (khartf). Abu Dawud said:\n\nThis tradition has been narrated by Mansur from al-Hakkam as narrated by Shu'bah.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا الأَعْمَشُ، عَنِ الْحَكَمِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمَعْنَاهُ لَمْ يَذْكُرِ الْخَرِيفَ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ مَنْصُورٌ عَنِ الْحَكَمِ أَبِي حَفْصٍ كَمَا رَوَاهُ شُعْبَةُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2991","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2991","x":"Narrated Umayyah:\n\nthat she asked 'Aishah about the saying of Allah, blessed and Most High: And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it (2:284). And about His saying: And whoever does evil, he will be recompensed for it (4:123). She said: \"No one has asked me about it since I asked the Messenger of Allah (ﷺ), he said: 'This is Allah's admonition for His slave regarding whatever he is stricken with, of fever and problems, even the item that he has in the pocket of his shirt which he loses and worries about, until the slave's sins are removed, just as the red ore is removed from the bellows.'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، وَرَوْحُ بْنُ عُبَادَةَ، عَنْ حَمَّادِ بْنِ سَلَمَةَ، عَنْ عَلِيِّ بْنِ زَيْدٍ، عَنْ أُمَيَّةَ، أَنَّهَا سَأَلَتْ عَائِشَةَ عَنْ قَوْلِ اللَّهِ تَعَالَى ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ‏)‏ وَعَنْ قَوْلِهِ ‏:‏ ‏(‏مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ ‏)‏ فَقَالَتْ مَا سَأَلَنِي عَنْهَا أَحَدٌ مُنْذُ سَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ هَذِهِ مُعَاتَبَةُ اللَّهِ الْعَبْدَ فِيمَا يُصِيبُهُ مِنَ الْحُمَّى وَالنَّكْبَةِ حَتَّى الْبِضَاعَةُ يَضَعُهَا فِي كُمِّ قَمِيصِهِ فَيَفْقِدُهَا فَيَفْزَعُ لَهَا حَتَّى إِنَّ الْعَبْدَ لَيَخْرُجُ مِنْ ذُنُوبِهِ كَمَا يَخْرُجُ التِّبْرُ الأَحْمَرُ مِنَ الْكِيرِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ حَدِيثِ عَائِشَةَ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3038","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3038","x":"Narrated Abu Hurairah:\n\n\"When the following was revealed: 'Whoever works evil will have the recompense of it... (4:123)' That worried the Muslims, so they complained about that to the Messenger of Allah (ﷺ) and he said: \"Seek closeness and be steadfast, and in all that afflicts the believer there is atonement, even a thorn that pricks him, and the hardship he suffers.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ أَبِي عُمَرَ، وَعَبْدُ اللَّهِ بْنُ أَبِي زِيَادٍ الْمَعْنَى، وَاحِدٌ، قَالاَ حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ ابْنِ مُحَيْصِنٍ، عَنْ مُحَمَّدِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا نَزَلَتْْ ‏:‏ ‏(‏مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ ‏)‏ شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَشَكَوْا ذَلِكَ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\n\n\"‏ قَارِبُوا وَسَدِّدُوا وَفِي كُلِّ مَا يُصِيبُ الْمُؤْمِنَ كَفَّارَةٌ حَتَّى الشَّوْكَةِ يُشَاكُهَا أَوِ النَّكْبَةِ يُنْكَبُهَا ‏\"\n\n‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ ابْنُ مُحَيْصِنٍ هُوَ عُمَرُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُحَيْصِنٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3039","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3039","x":"Narrated Abu Bakr As-Siddiq:\n\n\"I was with the Prophet (ﷺ) when this Ayah was revealed to him: Whoever works evil will have the recompense of it (4:123). So the Messenger of Allah (ﷺ) said: 'O Abu Bakr! Shall I recite to you an Ayah revealed to me?' I said: 'Of course O Messenger of Allah!' So he recited it to me, and I do not know except that I found it as a fatal blow, but I repressed it. So the Messenger of Allah (ﷺ) said: 'What is bothering you O Abu Bakr?' I said: 'O Messenger of Allah! May my father and my mother be your ransom! Which of us has not done evil - and yet we shall be recompensed for what we have done?' So the Messenger of Allah (ﷺ) said: 'As for you O Abu Bakr, and the believers, they will be recompensed for that in the world until they meet Allah and they have no sins. As for the others, then that will be collected for them until they are recompensed for it on the Day of Judgement.'\"","ar":"حَدَّثَنَا يَحْيَى بْنُ مُوسَى، وَعَبْدُ بْنُ حُمَيْدٍ، قَالاَ حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، عَنْ مُوسَى بْنِ عُبَيْدَةَ، أَخْبَرَنِي مَوْلَى ابْنِ سَبَّاعٍ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ، يُحَدِّثُ عَنْ أَبِي بَكْرٍ الصِّدِّيقِ، قَالَ كُنْتُ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأُنْزِلَتْ عَلَيْهِ هَذِهِ الآيَةُ ‏:‏ ‏(‏ مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ وَلاَ يَجِدْ لَهُ مِنْ دُونِ اللَّهِ وَلِيًّا وَلاَ نَصِيرًا ‏)‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَبَا بَكْرٍ أَلاَ أُقْرِئُكَ آيَةً أُنْزِلَتْ عَلَىَّ ‏\"‏ ‏.‏ قُلْتُ بَلَى يَا رَسُولَ اللَّهِ ‏.‏ قَالَ فَأَقْرَأَنِيهَا فَلاَ أَعْلَمُ إِلاَّ أَنِّي قَدْ كُنْتُ وَجَدْتُ انْقِصَامًا فِي ظَهْرِي فَتَمَطَّأْتُ لَهَا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا شَأْنُكَ يَا أَبَا بَكْرٍ ‏\"‏ ‏.‏ قُلْتُ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي وَأَيُّنَا لَمْ يَعْمَلْ سُوءًا وَإِنَّا لَمَجْزِيُّونَ بِمَا عَمِلْنَا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَمَّا أَنْتَ يَا أَبَا بَكْرٍ وَالْمُؤْمِنُونَ فَتُجْزَوْنَ بِذَلِكَ فِي الدُّنْيَا حَتَّى تَلْقَوُا اللَّهَ وَلَيْسَ لَكُمْ ذُنُوبٌ وَأَمَّا الآخَرُونَ فَيُجْمَعُ ذَلِكَ لَهُمْ حَتَّى يُجْزَوْا بِهِ يَوْمَ الْقِيَامَةِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ وَفِي إِسْنَادِهِ مَقَالٌ ‏.‏ مُوسَى بْنُ عُبَيْدَةَ يُضَعَّفُ فِي الْحَدِيثِ ضَعَّفَهُ يَحْيَى بْنُ سَعِيدٍ وَأَحْمَدُ بْنُ حَنْبَلٍ وَمَوْلَى ابْنِ سَبَّاعٍ مَجْهُولٌ ‏.‏ وَقَدْ رُوِيَ هَذَا الْحَدِيثُ مِنْ غَيْرِ هَذَا الْوَجْهِ عَنْ أَبِي بَكْرٍ وَلَيْسَ لَهُ إِسْنَادٌ صَحِيحٌ أَيْضًا ‏.‏ وَفِي الْبَابِ عَنْ عَائِشَةَ ‏.‏","v":[]}],"126":[{"c":"Sahih Muslim","r":"Hadith 3018a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3018a","x":"'Urwa b. Zubair reported that he asked 'A'isha about the words of Allah:\n\n\" If you fear that you will not be able to maintain equity amongst the orphan girls, then marry (those) you like from amongst the women two, three or four.\" She said: O, the son of my sister, the orphan girl is one who is under the patronage of her guardian and she shares with him in his property and her property and beauty fascinate him and her guardian makes up his mind to marry her without giving her due share of the wedding money and is not prepared (to pay so much amount) which anyone else is prepared to pay and so Allah has forbidden to marry these girls but in case when equity is observed as regards the wedding money and they are prepared to pay them the full amount of the wedding money and Allah commanded to marry other women besides them according to the liking of their heart. 'Urwa reported that 'A'isha said that people began to seek verdict from Allah's Messenger (ﷺ) after the revelation of this verse about them (orphan girls) and Allah, the Exalted and Glorious, revealed this verse:\" They asked thee verdict about women; say: Allah gives verdict to you in regard to them and what is recited to you in the Book about orphan woman, whom you give not what is ordained for them while you like to marry them\" (iv. 126). She said: The wording of Allah\" what is recited to you\" in the Book means the first verse, i. e.\" if you fear that you may not be able to observe equity in case of an orphan woman, marry what you like in case of woman\" (iv. 3). 'A'isha said: (And as for this verse [iv. 126], i. e. and you intend\" to marry one of them from amongst the orphan girls\" it pertains to one who is in charge (of orphans) having small amount of wealth and less beauty and they have been forbidden that they should marry what they like of her wealth and beauty out of the orphan girls, but with equity, because of their disliking for them.","ar":"حَدَّثَنِي أَبُو الطَّاهِرِ، أَحْمَدُ بْنُ عَمْرِو بْنِ سَرْحٍ وَحَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ - قَالَ أَبُو الطَّاهِرِ حَدَّثَنَا وَقَالَ، حَرْمَلَةُ أَخْبَرَنَا - ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِ اللَّهِ، ‏{‏ وَإِنْ خِفْتُمْ أَنْ لاَ، تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاَثَ وَرُبَاعَ‏}‏ قَالَتْ يَا ابْنَ أُخْتِي هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا تُشَارِكُهُ فِي مَالِهِ فَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا فَيُعْطِيَهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ وَيَبْلُغُوا بِهِنَّ أَعْلَى سُنَّتِهِنَّ مِنَ الصَّدَاقِ وَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ ثُمَّ إِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فِيهِنَّ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ فِي يَتَامَى النِّسَاءِ اللاَّتِي لاَ تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ ‏.‏ قَالَتْ وَالَّذِي ذَكَرَ اللَّهُ تَعَالَى أَنَّهُ يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ الآيَةُ الأُولَى الَّتِي قَالَ اللَّهُ فِيهَا ‏{‏ وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ ‏.‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ فِي الآيَةِ الأُخْرَى ‏{‏ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ رَغْبَةَ أَحَدِكُمْ عَنِ الْيَتِيمَةِ الَّتِي تَكُونُ فِي حَجْرِهِ حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ فَنُهُوا أَنْ يَنْكِحُوا مَا رَغِبُوا فِي مَالِهَا وَجَمَالِهَا مِنْ يَتَامَى النِّسَاءِ إِلاَّ بِالْقِسْطِ مِنْ أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3018e","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3018e","x":"Hisham reported that 'A'isha said in connection with the words of Allah:\n\n\" They ask thee the religious verdict about women, say: Allah gives you the verdict about them\" (iv. 126), that these relate to an orphan girl who is in charge of the person and she shares with him in his property (as a heir) even in the date-palm trees and he is reluctant to give her hand in marriage to any other person lest he (her husband) should partake of his property, and thus keep her in a lingering state.","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو أُسَامَةَ، أَخْبَرَنَا هِشَامٌ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، فِي قَوْلِهِ ‏{‏ ويَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ الآيَةَ قَالَتْ هِيَ الْيَتِيمَةُ الَّتِي تَكُونُ عِنْدَ الرَّجُلِ لَعَلَّهَا أَنْ تَكُونَ قَدْ شَرِكَتْهُ فِي مَالِهِ حَتَّى فِي الْعَذْقِ فَيَرْغَبُ يَعْنِي أَنْ يَنْكِحَهَا وَيَكْرَهُ أَنْ يُنْكِحَهَا رَجُلاً فَيَشْرَكُهُ فِي مَالِهِ فَيَعْضِلُهَا ‏.‏","v":[]}],"127":[{"c":"Sunan Abu Dawud","r":"Hadith 2073","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2073","x":"Rabi' b. Saburah reported on the authority of his father:\n\nThe Messenger of Allah (ﷺ) prohibited temporary marriage with women.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ رَبِيعِ بْنِ سَبْرَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم حَرَّمَ مُتْعَةَ النِّسَاءِ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2494","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2494","x":"Narrated `Urwa bin Az-Zubair:\n\nThat he had asked `Aisha about the meaning of the Statement of Allah: \"If you fear that you shall not Be able to deal justly With the orphan girls, then Marry (Other) women of your choice Two or three or four.\" (4.3) She said, \"O my nephew! This is about the orphan girl who lives with her guardian and shares his property. Her wealth and beauty may tempt him to marry her without giving her an adequate Mahr (bridal-money) which might have been given by another suitor. So, such guardians were forbidden to marry such orphan girls unless they treated them justly and gave them the most suitable Mahr; otherwise they were ordered to marry any other woman.\" `Aisha further said, \"After that verse the people again asked the Prophet (about the marriage with orphan 'girls), so Allah revealed the following verses:-- 'They ask your instruction Concerning the women. Say: Allah Instructs you about them And about what is Recited unto you In the Book, concerning The orphan girls to whom You give not the prescribed portions and yet whom you Desire to marry...\" (4.127) What is meant by Allah's Saying:-- 'And about what is Recited unto you is the former verse which goes:-- 'If you fear that you shall not Be able to deal justly With the orphan girls, then Marry (other) women of your choice.' (4.3) `Aisha said, \"Allah's saying in the other verse:--'Yet whom you desire to marry' (4.127) means the desire of the guardian to marry an orphan girl under his supervision when she has not much property or beauty (in which case he should treat her justly). The guardians were forbidden to marry their orphan girls possessing property and beauty without being just to them, as they generally refrain from marrying them (when they are neither beautiful nor wealthy).","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ الْعَامِرِيُّ الأُوَيْسِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ وَقَالَ اللَّيْثُ حَدَّثَنِي يُونُسُ عَنِ ابْنِ شِهَابٍ قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ عَنْ قَوْلِ اللَّهِ تَعَالَى ‏{‏وَإِنْ خِفْتُمْ‏}‏ إِلَى ‏{‏وَرُبَاعَ‏}‏‏.‏ فَقَالَتْ يَا ابْنَ أُخْتِي هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا تُشَارِكُهُ فِي مَالِهِ، فَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا، فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا، فَيُعْطِيهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ، فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ وَيَبْلُغُوا بِهِنَّ أَعْلَى سُنَّتِهِنَّ مِنَ الصَّدَاقِ، وَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ ثُمَّ إِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى قَوْلِهِ ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ وَالَّذِي ذَكَرَ اللَّهُ أَنَّهُ يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ الآيَةُ الأُولَى الَّتِي قَالَ فِيهَا ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ فِي الآيَةِ الأُخْرَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ يَعْنِي هِيَ رَغْبَةُ أَحَدِكُمْ لِيَتِيمَتِهِ الَّتِي تَكُونُ فِي حَجْرِهِ، حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ، فَنُهُوا أَنْ يَنْكِحُوا مَا رَغِبُوا فِي مَالِهَا وَجَمَالِهَا مِنْ يَتَامَى النِّسَاءِ إِلاَّ بِالْقِسْطِ مِنْ، أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2763","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2763","x":"Narrated Az-Zuhri:\n\n`Urwa bin Az-Zubair said that he asked `Aisha about the meaning of the Qur'anic Verse:-- \"And if you fear that you will not deal fairly with the orphan girls then marry (other) women of your choice.\" (4.2-3) Aisha said, \"It is about a female orphan under the guardianship of her guardian who is inclined towards her because of her beauty and wealth, and likes to marry her with a Mahr less than what is given to women of her standard. So they (i.e. guardians) were forbidden to marry the orphans unless they paid them a full appropriate Mahr (otherwise) they were ordered to marry other women instead of them. Later on the people asked Allah's Messenger (ﷺ) about it. So Allah revealed the following Verse:-- \"They ask your instruction (O Muhammad!) regarding women. Say: Allah instructs you regarding them...\" (4.127) and in this Verse Allah indicated that if the orphan girl was beautiful and wealthy, her guardian would have the desire to marry her without giving her an appropriate Mahr equal to what her peers could get, but if she was undesirable for lack of beauty or wealth, then he would not marry her, but seek to marry some other woman instead of her. So, since he did not marry her when he had no inclination towards her, he had not the right to marry her when he had an interest in her, unless he treated her justly by giving her a full Mahr and securing all her rights.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ كَانَ عُرْوَةُ بْنُ الزُّبَيْرِ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏ قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ قَالَتْ عَائِشَةُ ثُمَّ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ قَالَتْ فَبَيَّنَ اللَّهُ فِي هَذِهِ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ جَمَالٍ وَمَالٍ رَغِبُوا فِي نِكَاحِهَا، وَلَمْ يُلْحِقُوهَا بِسُنَّتِهَا بِإِكْمَالِ الصَّدَاقِ، فَإِذَا كَانَتْ مَرْغُوبَةً عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ تَرَكُوهَا وَالْتَمَسُوا غَيْرَهَا مِنَ النِّسَاءِ، قَالَ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا إِلاَّ أَنْ يُقْسِطُوا لَهَا الأَوْفَى مِنَ الصَّدَاقِ وَيُعْطُوهَا حَقَّهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4574","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4574","x":"Narrated `Urwa bin Az-Zubair:\n\nThat he asked `Aisha regarding the Statement of Allah: \"If you fear that you shall not be able to deal justly with the orphan girls...\" (4.3) She said, \"O son of my sister! An Orphan girl used to be under the care of a guardian with whom she shared property. Her guardian, being attracted by her wealth and beauty, would intend to marry her without giving her a just Mahr, i.e. the same Mahr as any other person might give her (in case he married her). So such guardians were forbidden to do that unless they did justice to their female wards and gave them the highest Mahr their peers might get. They were ordered (by Allah, to marry women of their choice other than those orphan girls.\" `Aisha added,\" The people asked Allah's Messenger (ﷺ) his instructions after the revelation of this Divine Verse whereupon Allah revealed: \"They ask your instruction regarding women \" (4.127) `Aisha further said, \"And the Statement of Allah: \"And yet whom you desire to marry.\" (4.127) as anyone of you refrains from marrying an orphan girl (under his guardianship) when she is lacking in property and beauty.\" `Aisha added, \"So they were forbidden to marry those orphan girls for whose wealth and beauty they had a desire unless with justice, and that was because they would refrain from marrying them if they were lacking in property and beauty.\"","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحِ بْنِ كَيْسَانَ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِ اللَّهِ، تَعَالَى ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏‏.‏ فَقَالَتْ يَا ابْنَ أُخْتِي، هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، تَشْرَكُهُ فِي مَالِهِ وَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا، فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا، بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا، فَيُعْطِيَهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ، فَنُهُوا عَنْ أَنْ يَنْكِحُوهُنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ، وَيَبْلُغُوا لَهُنَّ أَعْلَى سُنَّتِهِنَّ فِي الصَّدَاقِ، فَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ‏.‏ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ وَإِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ هَذِهِ الآيَةِ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ قَالَتْ عَائِشَةُ وَقَوْلُ اللَّهِ تَعَالَى فِي آيَةٍ أُخْرَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ رَغْبَةُ أَحَدِكُمْ عَنْ يَتِيمَتِهِ حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ قَالَتْ فَنُهُوا أَنْ يَنْكِحُوا عَنْ مَنْ رَغِبُوا فِي مَالِهِ وَجَمَالِهِ فِي يَتَامَى النِّسَاءِ، إِلاَّ بِالْقِسْطِ، مِنْ أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ إِذَا كُنَّ قَلِيلاَتِ الْمَالِ وَالْجَمَالِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4600","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4600","x":"Narrated `Aisha:\n\nRegarding the Verse:--\"They ask your instruction concerning the women. Say: Allah instructs you about them and yet whom you desire to marry.\" (4.127) (has been revealed regarding the case of) a man who has an orphan girl, and he is her guardian and her heir. The girl shares with him all his property, even a date-palm (garden), but he dislikes to marry her and dislikes to give her in marriage to somebody else who would share with him the property she is sharing with him, and for this reason that guardian prevents that orphan girl from marrying. So, this Verse was revealed: (And Allah's statement:) \"If a woman fears cruelty or desertion on her husband's part.\" (4.128)","ar":"حَدَّثَنَا عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ إِلَى قَوْلِهِ ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏‏.‏ قَالَتْ هُوَ الرَّجُلُ تَكُونُ عِنْدَهُ الْيَتِيمَةُ، هُوَ وَلِيُّهَا وَوَارِثُهَا، فَأَشْرَكَتْهُ فِي مَالِهِ حَتَّى فِي الْعِذْقِ، فَيَرْغَبُ أَنْ يَنْكِحَهَا، وَيَكْرَهُ أَنْ يُزَوِّجَهَا رَجُلاً، فَيَشْرَكُهُ فِي مَالِهِ بِمَا شَرِكَتْهُ فَيَعْضُلَهَا فَنَزَلَتْ هَذِهِ الآيَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5092","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5092","x":"Narrated 'Urwa:\n\nthat he asked `Aisha regarding the Verse: 'If you fear that you shall not be able to deal justly with the orphans (4.3) She said, \"O my nephew! This Verse refers to the orphan girl who is under the guardianship of her guardian who likes her beauty and wealth and wishes to (marry her and) curtails her Mahr. Such guardians have been forbidden to marry them unless they do justice by giving them their full Mahr, and they have been ordered to marry other than them. The people asked for the verdict of Allah's Messenger (ﷺ) after that, so Allah revealed: 'They ask your instruction concerning the women... whom you desire to marry.' (4.127) So Allah revealed to them that if the orphan girl had beauty and wealth, they desired to marry her and for her family status. They can only marry them if they give them their full Mahr. And if they had no desire to marry them because of their lack of wealth and beauty, they would leave them and marry other women. So, as they used to leave them, when they had no interest, in them, they were forbidden to marry them when they had such interest, unless they treated them justly and gave them their full Mahr Apostle said, 'If at all there is evil omen, it is in the horse, the woman and the house.\" a lady is to be warded off. And the Statement of Allah: 'Truly, among your wives and your children, there are enemies for you (i.e may stop you from the obedience of Allah)' (64.14)","ar":"حَدَّثَنِي يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُرْوَةُ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏ قَالَتْ يَا ابْنَ أُخْتِي هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَنْتَقِصَ صَدَاقَهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ إِلاَّ أَنْ يُقْسِطُوا فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ، قَالَتْ وَاسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ ذَلِكَ، فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏ فَأَنْزَلَ اللَّهُ لَهُمْ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ جَمَالٍ وَمَالٍ رَغِبُوا فِي نِكَاحِهَا وَنَسَبِهَا فِي إِكْمَالِ الصَّدَاقِ، وَإِذَا كَانَتْ مَرْغُوبَةً عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ تَرَكُوهَا وَأَخَذُوا غَيْرَهَا مِنَ النِّسَاءِ، قَالَتْ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا إِلاَّ أَنْ يُقْسِطُوا لَهَا وَيُعْطُوهَا حَقَّهَا الأَوْفَى فِي الصَّدَاقِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5128","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5128","x":"Narrated `Aisha:\n\n(as regards the Verse): 'And about what is recited unto you in the Book, concerning orphan girls to whom you give not the prescribed portions and yet, whom you desire to marry.' (4.127) This Verse is about the female orphan who is under the guardianship of a man with whom she shares her property and he has more right over her (than anybody else) but does not like to marry her, so he prevents her, from marrying somebody else, lest he should share the property with him.","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، ‏{‏وَمَا يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ فِي يَتَامَى النِّسَاءِ اللاَّتِي لاَ تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏‏.‏ قَالَتْ هَذَا فِي الْيَتِيمَةِ الَّتِي تَكُونُ عِنْدَ الرَّجُلِ، لَعَلَّهَا أَنْ تَكُونَ شَرِيكَتَهُ فِي مَالِهِ، وَهْوَ أَوْلَى بِهَا، فَيَرْغَبُ أَنْ يَنْكِحَهَا، فَيَعْضُلَهَا لِمَالِهَا، وَلاَ يُنْكِحَهَا غَيْرَهُ، كَرَاهِيَةَ أَنْ يَشْرَكَهُ أَحَدٌ فِي مَالِهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5131","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5131","x":"Narrated `Aisha:\n\n(regarding His Statement): 'They ask your instruction concerning the women. Say: Allah instructs you about them...' (4.127) It is about the female orphan who is under the guardianship of a man with whom she shares her property and he does not want to marry her and dislikes that someone else should marry her, lest he should share the property with him, so he prevents her from marrying. So Allah forbade such a guardian to do so (i.e. to prevent her from marrying).","ar":"حَدَّثَنَا ابْنُ سَلاَمٍ، أَخْبَرَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا هِشَامٌ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ فِي قَوْلِهِ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ إِلَى آخِرِ الآيَةِ، قَالَتْ هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ الرَّجُلِ، قَدْ شَرِكَتْهُ فِي مَالِهِ، فَيَرْغَبُ عَنْهَا أَنْ يَتَزَوَّجَهَا، وَيَكْرَهُ أَنْ يُزَوِّجَهَا غَيْرَهُ، فَيَدْخُلَ عَلَيْهِ فِي مَالِهِ، فَيَحْبِسُهَا، فَنَهَاهُمُ اللَّهُ عَنْ ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5140","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5140","x":"Narrated 'Urwa bin Az-Zubair:\n\nthat he asked `Aisha, saying to her, \"O Mother! (In what connection was this Verse revealed): 'If you fear that you shall not be able to deal justly with orphan girls (to the end of the verse) that your right hands possess?\" (4.3) Aisha said, \"O my nephew! It was about the female orphan under the protection of her guardian who was interested in her beauty and wealth and wanted to marry her with a little or reduced Mahr. So such guardians were forbidden to marry female orphans unless they deal with them justly and give their full Mahr; and they were ordered to marry women other than them.\"`Aisha added, \"(Later) the people asked Allah's Messenger (ﷺ), for instructions, and then Allah revealed: 'They ask your instruction concerning the women... And yet whom you desire to marry.' (4.127) So Allah revealed to them in this Verse that-if a female orphan had wealth and beauty, they desired to marry her and were interested in her noble descent and the reduction of her Mahr; but if she was not desired by them because of her lack in fortune and beauty they left her and married some other woman. So, as they used to leave her when they had no interest in her, they had no right to marry her if they had the desire to do so, unless they deal justly with her and gave her a full amount of Mahr.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ،‏.‏ وَقَالَ اللَّيْثُ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّهُ سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ قَالَ لَهَا يَا أُمَّتَاهْ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى‏}‏ إِلَى ‏{‏مَا مَلَكَتْ أَيْمَانُكُمْ‏}‏ قَالَتْ عَائِشَةُ يَا ابْنَ أُخْتِي هَذِهِ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَنْتَقِصَ مِنْ صَدَاقِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ‏.‏ إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ، قَالَتْ عَائِشَةُ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدَ ذَلِكَ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ إِلَى ‏{‏وَتَرْغَبُونَ‏}‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ لَهُمْ فِي هَذِهِ الآيَةِ أَنَّ الْيَتِيمَةَ إِذَا كَانَتْ ذَاتَ مَالٍ وَجَمَالٍ، رَغِبُوا فِي نِكَاحِهَا وَنَسَبِهَا وَالصَّدَاقِ، وَإِذَا كَانَتْ مَرْغُوبًا عَنْهَا فِي قِلَّةِ الْمَالِ وَالْجَمَالِ، تَرَكُوهَا وَأَخَذُوا غَيْرَهَا مِنَ النِّسَاءِ ـ قَالَتْ ـ فَكَمَا يَتْرُكُونَهَا حِينَ يَرْغَبُونَ عَنْهَا، فَلَيْسَ لَهُمْ أَنْ يَنْكِحُوهَا إِذَا رَغِبُوا فِيهَا، إِلاَّ أَنْ يُقْسِطُوا لَهَا وَيُعْطُوهَا حَقَّهَا الأَوْفَى مِنَ الصَّدَاقِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6965","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6965","x":"Narrated `Urwa:\n\nThat he asked `Aisha regarding the Verse: 'If you fear that you shall not be able to deal justly with the orphan girls, marry (other) women of your choice.' (4.3) `Aisha said, \"It is about an orphan girl under the custody of her guardian who being attracted by her wealth and beauty wants to marry her with Mahr less than other women of her status. So such guardians were forbidden to marry them unless they treat them justly by giving them their full Mahr. Then the people sought the verdict of Allah's Apostle for such cases, whereupon Allah revealed: 'They ask your instruction concerning women..' (4.127) (The sub-narrator then mentioned the Hadith.)","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، حَدَّثَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ كَانَ عُرْوَةُ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ ‏{‏وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ‏}‏‏.‏ قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي مَالِهَا وَجَمَالِهَا، فَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، ثُمَّ اسْتَفْتَى النَّاسُ رَسُولَ اللَّهِ صلى الله عليه وسلم بَعْدُ فَأَنْزَلَ اللَّهُ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ‏}‏ فَذَكَرَ الْحَدِيثَ‏.‏","v":[]}],"128":[{"c":"Sunan Abu Dawud","r":"Hadith 2135","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2135","x":"Narrated Hisham b. 'Urwah:\n\nOn the authority of his father that 'Aishah said: O my nephew, the Messenger of Allah (ﷺ) did not prefer one of us to the other in respect of his division of the time of his staying with us. It was very rare that he did not visit us any day (i.e. he visited all of us every day). He would come near each of his wives without having intercourse with her until he reached the one who had her day and passed his night with her. When Saudah daughter of Zam'ah became old and feared that the Messenger of Allah (ﷺ) would divorce her, she said: Messenger of Allah, I give to 'Aishah the day you visit me. The Messenger of Allah (ﷺ) accepted it from her. She said: We think that Allah, the Exalted, revealed about this or similar matter the Qur'anic verse: \"If a wife fears cruelty or desertion on her husband's part....\" [4:128]","ar":"حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، - يَعْنِي ابْنَ أَبِي الزِّنَادِ - عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، قَالَ قَالَتْ عَائِشَةُ يَا ابْنَ أُخْتِي كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم لاَ يُفَضِّلُ بَعْضَنَا عَلَى بَعْضٍ فِي الْقَسْمِ مِنْ مُكْثِهِ عِنْدَنَا وَكَانَ قَلَّ يَوْمٌ إِلاَّ وَهُوَ يَطُوفُ عَلَيْنَا جَمِيعًا فَيَدْنُو مِنْ كُلِّ امْرَأَةٍ مِنْ غَيْرِ مَسِيسٍ حَتَّى يَبْلُغَ إِلَى الَّتِي هُوَ يَوْمُهَا فَيَبِيتُ عِنْدَهَا وَلْقَدْ قَالَتْ سَوْدَةُ بِنْتُ زَمْعَةَ حِينَ أَسَنَّتْ وَفَرِقَتْ أَنْ يُفَارِقَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم يَا رَسُولَ اللَّهِ يَوْمِي لِعَائِشَةَ ‏.‏ فَقَبِلَ ذَلِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنْهَا قَالَتْ نَقُولُ فِي ذَلِكَ أَنْزَلَ اللَّهُ تَعَالَى وَفِي أَشْبَاهِهَا أُرَاهُ قَالَ ‏{‏ وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا ‏}‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2140","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2140","x":"Narrated Qays ibn Sa'd:\n\nI went to al-Hirah and saw them (the people) prostrating themselves before a satrap of theirs, so I said: The Messenger of Allah (ﷺ) has most right to have prostration made before him. When I came to the Prophet (ﷺ), I said: I went to al-Hirah and saw them prostrating themselves before a satrap of theirs, but you have most right, Messenger of Allah, to have (people) prostrating themselves before you. He said: Tell me, if you were to pass my grave, would you prostrate yourself before it? I said: No. He then said: Do not do so. If I were to command anyone to make prostration before another I would command women to prostrate themselves before their husbands, because of the special right over them given to husbands by Allah.","ar":"حَدَّثَنَا عَمْرُو بْنُ عَوْنٍ، أَخْبَرَنَا إِسْحَاقُ بْنُ يُوسُفَ، عَنْ شَرِيكٍ، عَنْ حُصَيْنٍ، عَنِ الشَّعْبِيِّ، عَنْ قَيْسِ بْنِ سَعْدٍ، قَالَ أَتَيْتُ الْحِيرَةَ فَرَأَيْتُهُمْ يَسْجُدُونَ لِمَرْزُبَانٍ لَهُمْ فَقُلْتُ رَسُولُ اللَّهِ أَحَقُّ أَنْ يُسْجَدَ لَهُ قَالَ فَأَتَيْتُ النَّبِيَّ صلى الله عليه وسلم فَقُلْتُ إِنِّي أَتَيْتُ الْحِيرَةَ فَرَأَيْتُهُمْ يَسْجُدُونَ لِمَرْزُبَانٍ لَهُمْ فَأَنْتَ يَا رَسُولَ اللَّهِ أَحَقُّ أَنْ نَسْجُدَ لَكَ ‏.‏ قَالَ ‏\"‏ أَرَأَيْتَ لَوْ مَرَرْتَ بِقَبْرِي أَكُنْتَ تَسْجُدُ لَهُ ‏\"‏ ‏.‏ قَالَ قُلْتُ لاَ ‏.‏ قَالَ ‏\"‏ فَلاَ تَفْعَلُوا لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لأَحَدٍ لأَمَرْتُ النِّسَاءَ أَنْ يَسْجُدْنَ لأَزْوَاجِهِنَّ لِمَا جَعَلَ اللَّهُ لَهُمْ عَلَيْهِنَّ مِنَ الْحَقِّ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2450","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2450","x":"Narrated Aisha:\n\nRegarding the explanation of the following verse:-- \"If a wife fears Cruelty or desertion On her husband's part.\" (4.128) A man may dislike his wife and intend to divorce her, so she says to him, \"I give up my rights, so do not divorce me.\" The above verse was revealed concerning such a case.","ar":"حَدَّثَنَا مُحَمَّدٌ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏ قَالَتِ الرَّجُلُ تَكُونُ عِنْدَهُ الْمَرْأَةُ، لَيْسَ بِمُسْتَكْثِرٍ مِنْهَا، يُرِيدُ أَنْ يُفَارِقَهَا، فَتَقُولُ أَجْعَلُكَ مِنْ شَأْنِي فِي حِلٍّ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2694","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2694","x":"Narrated Aisha:\n\nThe following Verse: If a woman fears cruelty or desertion on her husband's part (i.e. the husband notices something unpleasant about his wife, such as old age or the like, and wants to divorce her, but she asks him to keep her and provide for her as he wishes). (4.128) \"There is no blame on them if they reconcile on such basis.\"","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا سُفْيَانُ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها – ‏{‏وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏ قَالَتْ هُوَ الرَّجُلُ يَرَى مِنِ امْرَأَتِهِ مَا لاَ يُعْجِبُهُ، كِبَرًا أَوْ غَيْرَهُ، فَيُرِيدُ فِرَاقَهَا فَتَقُولُ أَمْسِكْنِي، وَاقْسِمْ لِي مَا شِئْتَ‏.‏ قَالَتْ فَلاَ بَأْسَ إِذَا تَرَاضَيَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4600","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4600","x":"Narrated `Aisha:\n\nRegarding the Verse:--\"They ask your instruction concerning the women. Say: Allah instructs you about them and yet whom you desire to marry.\" (4.127) (has been revealed regarding the case of) a man who has an orphan girl, and he is her guardian and her heir. The girl shares with him all his property, even a date-palm (garden), but he dislikes to marry her and dislikes to give her in marriage to somebody else who would share with him the property she is sharing with him, and for this reason that guardian prevents that orphan girl from marrying. So, this Verse was revealed: (And Allah's statement:) \"If a woman fears cruelty or desertion on her husband's part.\" (4.128)","ar":"حَدَّثَنَا عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ‏}‏ إِلَى قَوْلِهِ ‏{‏وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ‏}‏‏.‏ قَالَتْ هُوَ الرَّجُلُ تَكُونُ عِنْدَهُ الْيَتِيمَةُ، هُوَ وَلِيُّهَا وَوَارِثُهَا، فَأَشْرَكَتْهُ فِي مَالِهِ حَتَّى فِي الْعِذْقِ، فَيَرْغَبُ أَنْ يَنْكِحَهَا، وَيَكْرَهُ أَنْ يُزَوِّجَهَا رَجُلاً، فَيَشْرَكُهُ فِي مَالِهِ بِمَا شَرِكَتْهُ فَيَعْضُلَهَا فَنَزَلَتْ هَذِهِ الآيَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4601","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4601","x":"Narrated `Aisha:\n\nRegarding the Verse:--\"If a woman fears cruelty or desertion on her husband's part.\" (4.128) It is about a man who has a woman (wife) and he does not like her and wants to divorce her but she says to him, \"I make you free as regards myself.\" So this Verse was revealed in this connection.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ مُقَاتِلٍ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏‏.‏ قَالَتِ الرَّجُلُ تَكُونُ عِنْدَهُ الْمَرْأَةُ لَيْسَ بِمُسْتَكْثِرٍ مِنْهَا يُرِيدُ أَنْ يُفَارِقَهَا فَتَقُولُ أَجْعَلُكَ مِنْ شَأْنِي فِي حِلٍّ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ فِي ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5206","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5206","x":"Narrated Aisha:\n\nregarding the Verse: 'If a wife fears cruelty or desertion on her husband's part...') (4.128) It concerns the woman whose husband does not want to keep her with him any longer, but wants to divorce her and marry some other lady, so she says to him: 'Keep me and do not divorce me, and then marry another woman, and you may neither spend on me, nor sleep with me.' This is indicated by the Statement of Allah: 'There is no blame on them if they arrange an amicable settlement between them both, and (such) settlement is better.\" (4.128)","ar":"حَدَّثَنَا ابْنُ سَلاَمٍ، أَخْبَرَنَا أَبُو مُعَاوِيَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ ‏{‏وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏ قَالَتْ هِيَ الْمَرْأَةُ تَكُونُ عِنْدَ الرَّجُلِ، لاَ يَسْتَكْثِرُ مِنْهَا فَيُرِيدُ طَلاَقَهَا، وَيَتَزَوَّجُ غَيْرَهَا، تَقُولُ لَهُ أَمْسِكْنِي وَلاَ تُطَلِّقْنِي، ثُمَّ تَزَوَّجْ غَيْرِي، فَأَنْتَ فِي حِلٍّ مِنَ النَّفَقَةِ عَلَىَّ وَالْقِسْمَةِ لِي، فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏فَلاَ جُنَاحَ عَلَيْهِمَا أَنْ يَصَّالَحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3021a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3021a","x":"'A'isha said in connection with the verse:\n\n\" And if a woman has reason to fear ill-treatment from her husband or that he might turn away from her\" (iv. 128) that it was revealed in case of a woman who had long association with a person (as his wife) and now he intends to divorce her and she says: Do not divorce me, but retain me (as wife in your house) and you are permitted to live with another wife. It is in this context that this verse was revealed.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، حَدَّثَنَا هِشَامٌ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، ‏{‏ وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا‏}‏ الآيَةَ قَالَتْ أُنْزِلَتْ فِي الْمَرْأَةِ تَكُونُ عِنْدَ الرَّجُلِ فَتَطُولُ صُحْبَتُهَا فَيُرِيدُ طَلاَقَهَا فَتَقُولُ لاَ تُطَلِّقْنِي وَأَمْسِكْنِي وَأَنْتَ فِي حِلٍّ مِنِّي ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3040","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3040","x":"Narrated Ibn 'Abbas:\n\n\"Sawdah feared that the Prophet (ﷺ) was going to divorce her, so she said: 'Do not divorce me, but keep me and give my day to 'Aishah.' So he (ﷺ) did so, and the following was revealed: Then there is no sin on them both if they make terms of peace between themselves, and making peace is better (4:128). So whatever they agree to make peace in something then it is permissible.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا أَبُو دَاوُدَ الطَّيَالِسِيُّ، حَدَّثَنَا سُلَيْمَانُ بْنُ مُعَاذٍ، عَنْ سِمَاكٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ خَشِيَتْ سَوْدَةُ أَنْ يُطَلِّقَهَا، النَّبِيُّ صلى الله عليه وسلم فَقَالَتْ لاَ تُطَلِّقْنِي وَأَمْسِكْنِي وَاجْعَلْ يَوْمِي لِعَائِشَةَ فَفَعَلَ فَنَزَلَتْ ‏:‏ ‏(‏ فَلاَ جُنَاحَ عَلَيْهِمَا أَنْ يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ ‏)‏ ‏.‏ فَمَا اصْطَلَحَا عَلَيْهِ مِنْ شَيْءٍ فَهُوَ جَائِزٌ كَأَنَّهُ مِنْ قَوْلِ ابْنِ عَبَّاسٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏.‏","v":[]}],"129":[{"c":"Sahih Bukhari","r":"Hadith 2581","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2581","x":"Narrated `Urwa from `Aisha:\n\nThe wives of Allah's Messenger (ﷺ) were in two groups. One group consisted of `Aisha, Hafsa, Safiyya and Sauda; and the other group consisted of Um Salama and the other wives of Allah's Messenger (ﷺ). The Muslims knew that Allah's Messenger (ﷺ) loved `Aisha, so if any of them had a gift and wished to give to Allah's Messenger (ﷺ), he would delay it, till Allah's Messenger (ﷺ) had come to `Aisha's home and then he would send his gift to Allah's Messenger (ﷺ) in her home. The group of Um Salama discussed the matter together and decided that Um Salama should request Allah's Messenger (ﷺ) to tell the people to send their gifts to him in whatever wife's house he was. Um Salama told Allah's Messenger (ﷺ) of what they had said, but he did not reply. Then they (those wives) asked Um Salama about it. She said, \"He did not say anything to me.\" They asked her to talk to him again. She talked to him again when she met him on her day, but he gave no reply. When they asked her, she replied that he had given no reply. They said to her, \"Talk to him till he gives you a reply.\" When it was her turn, she talked to him again. He then said to her, \"Do not hurt me regarding Aisha, as the Divine Inspirations do not come to me on any of the beds except that of Aisha.\" On that Um Salama said, \"I repent to Allah for hurting you.\" Then the group of Um Salama called Fatima, the daughter of Allah's Messenger (ﷺ) and sent her to Allah's Messenger (ﷺ) to say to him, \"Your wives request to treat them and the daughter of Abu Bakr on equal terms.\" Then Fatima conveyed the message to him. The Prophet (ﷺ) said, \"O my daughter! Don't you love whom I love?\" She replied in the affirmative and returned and told them of the situation. They requested her to go to him again but she refused. They then sent Zainab bint Jahsh who went to him and used harsh words saying, \"Your wives request you to treat them and the daughter of Ibn Abu Quhafa on equal terms.\" On that she raised her voice and abused `Aisha to her face so much so that Allah's Messenger (ﷺ) looked at `Aisha to see whether she would retort. `Aisha started replying to Zainab till she silenced her. The Prophet (ﷺ) then looked at `Aisha and said, \"She is really the daughter of Abu Bakr.\"","ar":"حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ نِسَاءَ، رَسُولِ اللَّهِ صلى الله عليه وسلم كُنَّ حِزْبَيْنِ فَحِزْبٌ فِيهِ عَائِشَةُ وَحَفْصَةُ وَصَفِيَّةُ وَسَوْدَةُ، وَالْحِزْبُ الآخَرُ أُمُّ سَلَمَةَ وَسَائِرُ نِسَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَكَانَ الْمُسْلِمُونَ قَدْ عَلِمُوا حُبَّ رَسُولِ اللَّهِ صلى الله عليه وسلم عَائِشَةَ، فَإِذَا كَانَتْ عِنْدَ أَحَدِهِمْ هَدِيَّةٌ يُرِيدُ أَنْ يُهْدِيَهَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم أَخَّرَهَا، حَتَّى إِذَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي بَيْتِ عَائِشَةَ بَعَثَ صَاحِبُ الْهَدِيَّةِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فِي بَيْتِ عَائِشَةَ، فَكَلَّمَ حِزْبُ أُمِّ سَلَمَةَ، فَقُلْنَ لَهَا كَلِّمِي رَسُولَ اللَّهِ صلى الله عليه وسلم يُكَلِّمُ النَّاسَ، فَيَقُولُ مَنْ أَرَادَ أَنْ يُهْدِيَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم هَدِيَّةً فَلْيُهْدِهِ إِلَيْهِ حَيْثُ كَانَ مِنْ بُيُوتِ نِسَائِهِ، فَكَلَّمَتْهُ أُمُّ سَلَمَةَ بِمَا قُلْنَ، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا‏.‏ فَقَالَتْ مَا قَالَ لِي شَيْئًا‏.‏ فَقُلْنَ لَهَا فَكَلِّمِيهِ‏.‏ قَالَتْ فَكَلَّمَتْهُ حِينَ دَارَ إِلَيْهَا أَيْضًا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا‏.‏ فَقَالَتْ مَا قَالَ لِي شَيْئًا‏.‏ فَقُلْنَ لَهَا كَلِّمِيهِ حَتَّى يُكَلِّمَكِ‏.‏ فَدَارَ إِلَيْهَا فَكَلَّمَتْهُ‏.‏ فَقَالَ لَهَا ‏\"‏ لاَ تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّ الْوَحْىَ لَمْ يَأْتِنِي، وَأَنَا فِي ثَوْبِ امْرَأَةٍ إِلاَّ عَائِشَةَ ‏\"‏‏.‏ قَالَتْ فَقَالَتْ أَتُوبُ إِلَى اللَّهِ مِنْ أَذَاكَ يَا رَسُولَ اللَّهِ‏.‏ ثُمَّ إِنَّهُنَّ دَعَوْنَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَرْسَلْنَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم تَقُولُ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ أَبِي بَكْرٍ‏.‏ فَكَلَّمَتْهُ‏.‏ فَقَالَ ‏\"‏ يَا بُنَيَّةُ، أَلاَ تُحِبِّينَ مَا أُحِبُّ ‏\"‏‏.‏ قَالَتْ بَلَى‏.‏ فَرَجَعَتْ إِلَيْهِنَّ، فَأَخْبَرَتْهُنَّ‏.‏ فَقُلْنَ ارْجِعِي إِلَيْهِ‏.‏ فَأَبَتْ أَنْ تَرْجِعَ، فَأَرْسَلْنَ زَيْنَبَ بِنْتَ جَحْشٍ، فَأَتَتْهُ فَأَغْلَظَتْ، وَقَالَتْ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ ابْنِ أَبِي قُحَافَةَ‏.‏ فَرَفَعَتْ صَوْتَهَا، حَتَّى تَنَاوَلَتْ عَائِشَةَ‏.‏ وَهْىَ قَاعِدَةٌ، فَسَبَّتْهَا حَتَّى إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَيَنْظُرُ إِلَى عَائِشَةَ هَلْ تَكَلَّمُ قَالَ فَتَكَلَّمَتْ عَائِشَةُ تَرُدُّ عَلَى زَيْنَبَ، حَتَّى أَسْكَتَتْهَا‏.‏ قَالَتْ فَنَظَرَ النَّبِيُّ صلى الله عليه وسلم إِلَى عَائِشَةَ، وَقَالَ ‏\"‏ إِنَّهَا بِنْتُ أَبِي بَكْرٍ ‏\"‏‏.‏ قَالَ الْبُخَارِيُّ الْكَلاَمُ الأَخِيرُ قِصَّةُ فَاطِمَةَ يُذْكَرُ عَنْ هِشَامِ بْنِ عُرْوَةَ عَنْ رَجُلٍ عَنِ الزُّهْرِيِّ عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ‏.‏ وَقَالَ أَبُو مَرْوَانَ عَنْ هِشَامٍ عَنْ عُرْوَةَ كَانَ النَّاسُ يَتَحَرَّوْنَ بِهَدَايَاهُمْ يَوْمَ عَائِشَةَ‏.‏ وَعَنْ هِشَامٍ عَنْ رَجُلٍ مِنْ قُرَيْشٍ، وَرَجُلٍ مِنَ الْمَوَالِي، عَنِ الزُّهْرِيِّ عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ قَالَتْ عَائِشَةُ كُنْتُ عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَاسْتَأْذَنَتْ فَاطِمَةُ‏.‏","v":[]}],"145":[{"c":"Sahih Bukhari","r":"Hadith 4602","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4602","x":"Narrated Al-Aswad:\n\nWhile we were sitting in a circle in `Abdullah's gathering, Hudhaifa came and stopped before us, and greeted us and then said, \"People better than you became hypocrites.\" Al-Aswad said: I testify the uniqueness of Allah! Allah says: \"Verily! The hypocrites will be in the lowest depths of the Fire.\" (4.145) On that `Abdullah smiled and Hudhaifa sat somewhere in the Mosque. `Abdullah then got up and his companions (sitting around him) dispersed. Hudhaifa then threw a pebble at me (to attract my attention). I went to him and he said, \"I was surprised at `Abdullah's smile though he understood what I said. Verily, people better than you became hypocrite and then repented and Allah forgave them.\"","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، قَالَ حَدَّثَنِي إِبْرَاهِيمُ، عَنِ الأَسْوَدِ، قَالَ كُنَّا فِي حَلْقَةِ عَبْدِ اللَّهِ فَجَاءَ حُذَيْفَةُ حَتَّى قَامَ عَلَيْنَا، فَسَلَّمَ ثُمَّ قَالَ لَقَدْ أُنْزِلَ النِّفَاقُ عَلَى قَوْمٍ خَيْرٍ مِنْكُمْ‏.‏ قَالَ الأَسْوَدُ سُبْحَانَ اللَّهِ، إِنَّ اللَّهَ يَقُولُ ‏{‏إِنَّ الْمُنَافِقِينَ فِي الدَّرَكِ الأَسْفَلِ مِنَ النَّارِ‏}‏ فَتَبَسَّمَ عَبْدُ اللَّهِ، وَجَلَسَ حُذَيْفَةُ فِي نَاحِيَةِ الْمَسْجِدِ، فَقَامَ عَبْدُ اللَّهِ فَتَفَرَّقَ أَصْحَابُهُ، فَرَمَانِي بِالْحَصَا، فَأَتَيْتُهُ فَقَالَ حُذَيْفَةُ عَجِبْتُ مِنْ ضَحِكِهِ، وَقَدْ عَرَفَ مَا قُلْتُ، لَقَدْ أُنْزِلَ النِّفَاقُ عَلَى قَوْمٍ كَانُوا خَيْرًا مِنْكُمْ، ثُمَّ تَابُوا فَتَابَ اللَّهُ عَلَيْهِمْ‏.‏","v":[]}],"159":[{"c":"Sahih Bukhari","r":"Hadith 3448","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3448","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"By Him in Whose Hands my soul is, surely (Jesus,) the son of Mary will soon descend amongst you and will judge mankind justly (as a Just Ruler); he will break the Cross and kill the pigs and there will be no Jizya (i.e. taxation taken from non Muslims). Money will be in abundance so that nobody will accept it, and a single prostration to Allah (in prayer) will be better than the whole world and whatever is in it.\" Abu Huraira added \"If you wish, you can recite (this verse of the Holy Book): -- 'And there is none Of the people of the Scriptures (Jews and Christians) But must believe in him (i.e Jesus as an Apostle of Allah and a human being) Before his death. And on the Day of Judgment He will be a witness Against them.\" (4.159) (See Fath-ul-Bari, Page 302 Vol 7)","ar":"حَدَّثَنَا إِسْحَاقُ، أَخْبَرَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا أَبِي، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، أَنَّ سَعِيدَ بْنَ الْمُسَيَّبِ، سَمِعَ أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ، لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمُ ابْنُ مَرْيَمَ حَكَمًا عَدْلاً، فَيَكْسِرَ الصَّلِيبَ، وَيَقْتُلَ الْخِنْزِيرَ، وَيَضَعَ الْجِزْيَةَ، وَيَفِيضَ الْمَالُ حَتَّى لاَ يَقْبَلَهُ أَحَدٌ، حَتَّى تَكُونَ السَّجْدَةُ الْوَاحِدَةُ خَيْرًا مِنَ الدُّنْيَا وَمَا فِيهَا ‏\"‏‏.‏ ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ وَاقْرَءُوا إِنْ شِئْتُمْ ‏{‏وَإِنْ مِنْ أَهْلِ الْكِتَابِ إِلاَّ لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ وَيَوْمَ الْقِيَامَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا‏}‏‏.‏","v":[]}],"176":[{"c":"Sunan Abu Dawud","r":"Hadith 2892","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2892","x":"Narrated Jabir bin ‘Abdullah :\n\nThe wife of Sa'd b. al-Rabi said: Messenger of Allah, Sa'd died and left two daughters. He then narrated the rest of the tradition in a similar way. Abu Dawud said: This is the most correct tradition.","ar":"حَدَّثَنَا ابْنُ السَّرْحِ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي دَاوُدُ بْنُ قَيْسٍ، وَغَيْرُهُ، مِنْ أَهْلِ الْعِلْمِ عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ امْرَأَةَ، سَعْدِ بْنِ الرَّبِيعِ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ سَعْدًا هَلَكَ وَتَرَكَ ابْنَتَيْنِ ‏.‏ وَسَاقَ نَحْوَهُ قَالَ أَبُو دَاوُدَ وَهَذَا هُوَ الصَّوَابُ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2893","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2893","x":"Narrated Al-Aswad b. Yazid:\n\nMu'adh b. Jabal gave shares of inheritance to a sister and a daughter. He gave each of them half. He was at Yemen while the Prophet (ﷺ) was alive.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، حَدَّثَنَا قَتَادَةُ، حَدَّثَنِي أَبُو حَسَّانَ، عَنِ الأَسْوَدِ بْنِ يَزِيدَ، أَنَّ مُعَاذَ بْنَ جَبَلٍ، وَرَّثَ أُخْتًا وَابْنَةً فَجَعَلَ لِكُلِّ وَاحِدَةٍ مِنْهُمَا النِّصْفَ وَهُوَ بِالْيَمَنِ وَنَبِيُّ اللَّهِ صلى الله عليه وسلم يَوْمَئِذٍ حَىٌّ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2894","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2894","x":"Narrated Qabisah ibn Dhuwayb:\n\nA grandmother came to AbuBakr asking him for her share of inheritance. He said: There is nothing prescribed for you in Allah's Book, nor do I know anything for you in the Sunnah of the Prophet of Allah (ﷺ) Go home till I question the people. He then questioned the people, and al-Mughirah ibn Shu'bah said: I had been present with the Messenger of Allah (ﷺ) when he gave grandmother a sixth. AbuBakr said: Is there anyone with you? Muhammad ibn Maslamah stood and said the same as al-Mughirah ibn Shu'bah had said. So AbuBakr made it apply to her. Another grandmother came to Umar ibn al-Khattab asking him for her share of inheritance. He said: Nothing has been prescribed for you in Allah's Book. The decision made before you was made for a grandmother other than you. I am not going to add in the shares of inheritance; but it is that sixth. If there are two of you, it is shared between you, but whichever of you is the only one left gets it all.","ar":"حَدَّثَنَا الْقَعْنَبِيُّ، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُثْمَانَ بْنِ إِسْحَاقَ بْنِ خَرَشَةَ، عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ، أَنَّهُ قَالَ جَاءَتِ الْجَدَّةُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ تَسْأَلُهُ مِيرَاثَهَا فَقَالَ مَا لَكِ فِي كِتَابِ اللَّهِ تَعَالَى شَىْءٌ وَمَا عَلِمْتُ لَكِ فِي سُنَّةِ نَبِيِّ اللَّهِ صلى الله عليه وسلم شَيْئًا فَارْجِعِي حَتَّى أَسْأَلَ النَّاسَ ‏.‏ فَسَأَلَ النَّاسَ فَقَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ حَضَرْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم أَعْطَاهَا السُّدُسَ ‏.‏ فَقَالَ أَبُو بَكْرٍ هَلْ مَعَكَ غَيْرُكَ فَقَامَ مُحَمَّدُ بْنُ مَسْلَمَةَ فَقَالَ مِثْلَ مَا قَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ فَأَنْفَذَهُ لَهَا أَبُو بَكْرٍ ثُمَّ جَاءَتِ الْجَدَّةُ الأُخْرَى إِلَى عُمَرَ بْنِ الْخَطَّابِ رضى الله عنه تَسْأَلُهُ مِيرَاثَهَا فَقَالَ مَا لَكِ فِي كِتَابِ اللَّهِ تَعَالَى شَىْءٌ وَمَا كَانَ الْقَضَاءُ الَّذِي قُضِيَ بِهِ إِلاَّ لِغَيْرِكِ وَمَا أَنَا بِزَائِدٍ فِي الْفَرَائِضِ وَلَكِنْ هُوَ ذَلِكَ السُّدُسُ فَإِنِ اجْتَمَعْتُمَا فِيهِ فَهُوَ بَيْنَكُمَا وَأَيَّتُكُمَا خَلَتْ بِهِ فَهُوَ لَهَا ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2895","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2895","x":"Narrated Buraydah:\n\nThe Prophet (ﷺ) appointed a sixth to a grandmother if no mother is left to inherit before her.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الْعَزِيزِ بْنِ أَبِي رِزْمَةَ، أَخْبَرَنِي أَبِي، حَدَّثَنَا عُبَيْدُ اللَّهِ أَبُو الْمُنِيبِ الْعَتَكِيُّ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم جَعَلَ لِلْجَدَّةِ السُّدُسَ إِذَا لَمْ تَكُنْ دُونَهَا أُمٌّ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2747","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2747","x":"Narrated Ibn `Abbas:\n\nThe custom (in old days) was that the property of the deceased would be inherited by his offspring; as for the parents (of the deceased), they would inherit by the will of the deceased. Then Allah cancelled from that custom whatever He wished and fixed for the male double the amount inherited by the female, and for each parent a sixth (of the whole legacy) and for the wife an eighth or a fourth and for the husband a half or a fourth.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، عَنْ وَرْقَاءَ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَ الْمَالُ لِلْوَلَدِ، وَكَانَتِ الْوَصِيَّةُ لِلْوَالِدَيْنِ، فَنَسَخَ اللَّهُ مِنْ ذَلِكَ مَا أَحَبَّ، فَجَعَلَ لِلذَّكَرِ مِثْلَ حَظِّ الأُنْثَيَيْنِ، وَجَعَلَ لِلأَبَوَيْنِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسَ، وَجَعَلَ لِلْمَرْأَةِ الثُّمُنَ وَالرُّبْعَ، وَلِلزَّوْجِ الشَّطْرَ وَالرُّبُعَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4364","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4364","x":"Narrated Al-Bara:\n\nThe last Sura which was revealed in full was Baraa (i.e. Sura-at-Tauba), and the last Sura (i.e. part of a Sura) which was revealed was the last Verses of Sura-an-Nisa':-- \"They ask you for a legal decision. Say: Allah directs (thus) About those who have No descendants or ascendants As heirs.\" (4.176)","ar":"حَدَّثَنِي عَبْدُ اللَّهِ بْنُ رَجَاءٍ، حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ ـ رضى الله عنه ـ قَالَ آخِرُ سُورَةٍ نَزَلَتْ كَامِلَةً بَرَاءَةٌ، وَآخِرُ سُورَةٍ نَزَلَتْ خَاتِمَةُ سُورَةِ النِّسَاءِ ‏{‏يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4605","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4605","x":"Narrated Al-Bara:\n\nThe last Sura that was revealed was Bara'a, and the last Verse that was revealed was: \"They ask you for a legal verdict, Say: Allah's directs (thus) about those who leave no descendants or ascendants as heirs.\" (4.176)","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ قَالَ آخِرُ سُورَةٍ نَزَلَتْ بَرَاءَةَ، وَآخِرُ آيَةٍ نَزَلَتْ ‏{‏يَسْتَفْتُونَكَ ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6744","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6744","x":"Narrated Al-Bara:\n\nThe last Qur'anic Verse that was revealed (to the Prophet) was the final Verse of Surat-an-Nisa, i.e., 'They ask you for a legal verdict Say: Allah directs (thus) About those who leave No descendants or ascendants as heirs....' (4.176)","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ ـ رضى الله عنه ـ قَالَ آخِرُ آيَةٍ نَزَلَتْ خَاتِمَةُ سُورَةِ النِّسَاءِ ‏{‏يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ‏}‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 23, Hadith 2728","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-23/Hadith-2728","x":"It was narrated from Muhammad bin Munkadir that he heard Jabir bin ‘Abdullah say:\n\n\"I fell sick and the Messenger of Allah (ﷺ) came to visit me, he and Abu Bakr with him, and they came walking. I had lost consciousness, so the Messenger of Allah (ﷺ) performed ablution and poured some of the water of his ablution over me. I said: ‘O Messenger of Allah, what should I do? How should I decide about my wealth?’ Until the Verse of inheritance was revealed at the end of An-Nisa’: \"If the man or woman whose inheritance is in question has left neither ascendants or descendents.\" [4:12] And: \"They ask you for a legal verdict. Say: ‘Allah directs (thus) about those who leave neither descendants nor ascendants as heirs.’\" [4:176]","ar":"حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا سُفْيَانُ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي هُوَ وَأَبُو بَكْرٍ مَعَهُ وَهُمَا مَاشِيَانِ وَقَدْ أُغْمِيَ عَلَىَّ فَتَوَضَّأَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَصَبَّ عَلَىَّ مِنْ وَضُوئِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَصْنَعُ كَيْفَ أَقْضِي فِي مَالِي حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ فِي آخِرِ النِّسَاءِ ‏{وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلاَلَةً‏}‏ الآيَةَ وَ ‏{يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ}‏ الآيَةَ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 27, Hadith 1083","u":"https://quranx.com/Hadith/Malik/In-Book/Book-27/Hadith-1083","x":"Yahya related to me from Malik from Zayd ibn Aslam that Umar ibn al-Khattab asked the Messenger of Allah, may Allah bless him and grant him peace, about someone who died without parents or offspring, and the Messenger of Allah, may Allah bless him and grant him peace, said to him, \"The ayat which was sent down in the summer at the end of the Surat an-Nisa (Sura 4) is enoughfor you.\" Malik said, \"The generally agreed on way of doing things among us, in which there is no dispute, and which I saw the people of knowledge in our city doing, is that the person who leaves neither parent or offspring can be of two types. As for the kind described in the ayat which was sent down at the beginning of the Surat an-Nisa in which Allah, the Blessed, the Exalted! said, 'If a man or a woman has no direct heir, but has a brother or a sister by the mother, each of the two has a sixth. If there are more than that, they share equally in a third.' (Sura 4 ayat 12) This heirless one does not have heirs among his mother's siblings since there are no children or parents. As for the other kind described in the ayat which comes at the end of the Surat an-Nisa, Allah, the Blessed, the Exalted, said in it, 'They will ask you for a decision. Say, \"Allah gives you a decision about the indirect heirs. If a man perishes having no children, but he has a sister, she shall receive a half of what he leaves, and he is her heir if she has no children. If there are two sisters, they shall receive two-thirds of what he leaves. If there are brothers and sisters, the male shall receive the portion of two females. Allah makes clear to you that you might not go astray. Allah has knowledge of everything\" ' \" (Sura 4 ayat 176). Malik said, \"If this person without direct heirs (parents) or children has siblings by the father, they inherit with the grandfather from the person without direct heirs. The grandfather inherits with the siblings because he is more entitled to the inheritance than them. That is because he inherits a sixth with the male children of the deceased when the siblings do not inherit anything with the male children of the deceased. How can he not be like one of them when he takes a sixth with the children of the deceased? How can he not take a third with the siblings while the brother's sons take a third with them? The grandfather is the one who overshadows the half-siblings by the mother and keeps them from inheriting. He is more entitled to what they have because they are omitted for his sake. If the grandfather did not take that third, the half-siblings by the mother would take it and would take what does not return to the half-siblings by the father. The half-siblings by the mother are more entitled to that third than the half-siblings by the father while the grandfather is more entitled to that than the half- siblings by the mother.\"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنِ الْكَلاَلَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ يَكْفِيكَ مِنْ ذَلِكَ الآيَةُ الَّتِي أُنْزِلَتْ فِي الصَّيْفِ آخِرَ سُورَةِ النِّسَاءِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1616a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1616a","x":"Jabir b. 'Abdullah (Allah be pleased with them) reported:\n\nI fell sick and there came to me on foot Allah's Messenger (ﷺ) and Abu Bakr for inquiring after my health. I fainted. He (the Holy Prophet) performed ablution and then sprinkled over me the water of his ablution. I felt some relief and said: Allah's Messenger, how should I decide about my property? He said nothing to me in response until this verse pertaining to the law of inheritance was revealed:\" They ask you for a decision; say: Allah gives you a decision concerning the person who has neither parents nor children\" (iv. 176).","ar":"حَدَّثَنَا عَمْرُو بْنُ مُحَمَّدِ بْنِ بُكَيْرٍ النَّاقِدُ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ مُحَمَّدِ بْنِ، الْمُنْكَدِرِ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، قَالَ مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ يَعُودَانِي مَاشِيَيْنِ فَأُغْمِيَ عَلَىَّ فَتَوَضَّأَ ثُمَّ صَبَّ عَلَىَّ مِنْ وَضُوئِهِ فَأَفَقْتُ قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَقْضِي فِي مَالِي فَلَمْ يَرُدَّ عَلَىَّ شَيْئًا حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ ‏{‏ يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1616c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1616c","x":"Jabir b. 'Abdullah (Allah be pleased with them) reported:\n\nWhile I had been ill Allah's Messenger (ﷺ) visited me and Abu akr (Allah be pleased with him) was with him, and they both came walking on foot. He (the Holy Prophet) found me unconscious. Allahs Messenger (ﷺ) performed ablution and then sprinkled over me the water of his ablution. I felt relieved regained my consciousness) and found Allah's Messenger (ﷺ) there. I said: Allah's Messenger, what should I do with my property? He gave me no reply until the verse (iv. 176) relating to the law of inheritance was revealed.","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، - يَعْنِي ابْنَ مَهْدِيٍّ - حَدَّثَنَا سُفْيَانُ، قَالَ سَمِعْتُ مُحَمَّدَ بْنَ الْمُنْكَدِرِ، قَالَ سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ عَادَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا مَرِيضٌ وَمَعَهُ أَبُو بَكْرٍ مَاشِيَيْنِ فَوَجَدَنِي قَدْ أُغْمِيَ عَلَىَّ فَتَوَضَّأَ رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ صَبَّ عَلَىَّ مِنْ وَضُوئِهِ فَأَفَقْتُ فَإِذَا رَسُولُ اللَّهِ صلى الله عليه وسلم فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَصْنَعُ فِي مَالِي فَلَمْ يَرُدَّ عَلَىَّ شَيْئًا حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1616d","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1616d","x":"Jabir b. Abdullah (Allah be pleased with him) reported:\n\nWhilo I was ill Allah's Messenger (ﷺ) came to me and found me unconscious. He (the Holy Prophet) performed ablution, and sprinkled over me the water of his ablution. I regained my consciousness and said: Allah's Messenger, my case of inheritance is that of Kalala. Then the verse pertaining to the inheritance ( of Kalala) was revealed. I (one of the narrators) said: I said to Muhammad b. Munkadir: (Do you mean this verse)\" They ask you; say: Allah gives you decision in regard to Kalala\" (iv. 176)? He said: Yes, it was thus revealed.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، حَدَّثَنَا بَهْزٌ، حَدَّثَنَا شُعْبَةُ، أَخْبَرَنِي مُحَمَّدُ بْنُ الْمُنْكَدِرِ، قَالَ سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا مَرِيضٌ لاَ أَعْقِلُ فَتَوَضَّأَ فَصَبُّوا عَلَىَّ مِنْ وَضُوئِهِ فَعَقَلْتُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا يَرِثُنِي كَلاَلَةٌ ‏.‏ فَنَزَلَتْ آيَةُ الْمِيرَاثِ ‏.‏ فَقُلْتُ لِمُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏{‏ يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ‏}‏ قَالَ هَكَذَا أُنْزِلَتْ.","v":[]},{"c":"Sahih Muslim","r":"Hadith 1618e","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1618e","x":"Al-Bara' (Allah be pleased with him) reported that the last verse revealed was:\n\n\" They ask of thee religious verdict..\" (iv. 176).","ar":"حَدَّثَنَا عَمْرٌو النَّاقِدُ، حَدَّثَنَا أَبُو أَحْمَدَ الزُّبَيْرِيُّ، حَدَّثَنَا مَالِكُ بْنُ مِغْوَلٍ، عَنْ أَبِي، السَّفَرِ عَنِ الْبَرَاءِ، قَالَ آخِرُ آيَةٍ أُنْزِلَتْ يَسْتَفْتُونَكَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 4, Book 27, Hadith 2092","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-4/Book-27/Hadith-2092","x":"Jabir bin 'Abdullah said:\n\n\"The wife of Sa'd bin Ar-Rabi came with her two daughters from Sa'd to he Messenger of Allah(S.A.W)and said; O Messenger of Allah(S.A.W)! these two are daughters of Sa'd bin Ar-Rabi who fought along with you on the day of Uhud and was martyred. Their uncle took their wealth, without leaving any wealth for them, and they will not be married unless they have wealth.' He said: 'Allah will decide on that matter.' The ayah about inheritance was revealed, so the Messenger of Allah(S.A.W) sent (word) to their Uncle saying: Give the two daughters of Sa'd two thirds, and give their mother one eighth, and whatever remains, then it is for you.'","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قال حَدَّثَنِي زَكَرِيَّاءُ بْنُ عَدِيٍّ، أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ عَمْرٍو، عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ جَاءَتِ امْرَأَةُ سَعْدِ بْنِ الرَّبِيعِ بِابْنَتَيْهَا مِنْ سَعْدٍ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَتْ يَا رَسُولَ اللَّهِ هَاتَانِ ابْنَتَا سَعْدِ بْنِ الرَّبِيعِ قُتِلَ أَبُوهُمَا مَعَكَ يَوْمَ أُحُدٍ شَهِيدًا وَإِنَّ عَمَّهُمَا أَخَذَ مَالَهُمَا فَلَمْ يَدَعْ لَهُمَا مَالاً وَلاَ تُنْكَحَانِ إِلاَّ وَلَهُمَا مَالٌ ‏.‏ قَالَ ‏\"‏ يَقْضِي اللَّهُ فِي ذَلِكَ ‏\"‏ ‏.‏ فَنَزَلَتْ آيَةُ الْمِيرَاثِ فَبَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى عَمِّهِمَا فَقَالَ ‏\"‏ أَعْطِ ابْنَتَىْ سَعْدٍ الثُّلُثَيْنِ وَأَعْطِ أُمَّهُمَا الثُّمُنَ وَمَا بَقِيَ فَهُوَ لَكَ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ وَقَدْ رَوَاهُ شَرِيكٌ أَيْضًا عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 4, Book 27, Hadith 2096","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-4/Book-27/Hadith-2096","x":"Jabir bin 'Abdullah said:\n\n\"The Messenger of Allah(S.A.W) came to visit me while I was ill at Banu Salamah. I said : 'O Prophet of Allah(S.A.W)! How shall I divide my wealth among my children?' But he did not say anything to me, until the following was revealed: Allah commands you regarding your children's (inheritance): to the male, a portion equal to that of two females.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قال حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ سَعْدٍ، أَخْبَرَنَا عَمْرُو بْنُ أَبِي قَيْسٍ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ جَاءَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي وَأَنَا مَرِيضٌ فِي بَنِي سَلِمَةَ فَقُلْتُ يَا نَبِيَّ اللَّهِ كَيْفَ أَقْسِمُ مَالِي بَيْنَ وَلَدِي فَلَمْ يَرُدَّ عَلَىَّ شَيْئًا فَنَزَلَتْ ‏:‏ ‏(‏يُوصِيكُمُ اللَّهُ فِي أَوْلاَدِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنْثَيَيْنِ ‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَاهُ شُعْبَةُ وَابْنُ عُيَيْنَةَ وَغَيْرُهُ عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ عَنْ جَابِرٍ.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 4, Book 27, Hadith 2097","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-4/Book-27/Hadith-2097","x":"Jabir bin 'Abdullah said:\n\n\"I was ill, so the Messenger of Allah(S.A.W)came to visit me and found me unconscious. He came walking while Abu Bakr and 'Umar were with him. The Messenger of Allah(S.A.W) performed Wudu, then poured the remaining water on me, so I came to my senses. I said: 'O Messenger of Allah(S.A.W)! how shall I dispose of my wealth?' - or - 'What shall I do with my wealth?' He did not reply anything to me\" -and he had nine sisters- \"until the Ayah about the inheritance was revealed: they ask you for a legal verdict. Say: \"Allah directs (thus) about Al-Kalalah.\" Jabir said: \"It was revealed regarding me.\"","ar":"حَدَّثَنَا الْفَضْلُ بْنُ الصَّبَّاحِ الْبَغْدَادِيُّ، قال أَخْبَرَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، قال أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُنْكَدِرِ، سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي فَوَجَدَنِي قَدْ أُغْمِيَ عَلَىَّ فَأَتَى وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ وَهُمَا مَاشِيَانِ فَتَوَضَّأَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَصَبَّ عَلَىَّ مِنْ وَضُوئِهِ فَأَفَقْتُ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَقْضِي فِي مَالِي أَوْ كَيْفَ أَصْنَعُ فِي مَالِي فَلَمْ يُجِبْنِي شَيْئًا وَكَانَ لَهُ تِسْعُ أَخَوَاتٍ حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ ‏:‏ ‏(‏يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ ‏)‏ الآيَةَ ‏.‏ قَالَ جَابِرٌ فِيَّ نَزَلَتْ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3041","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3041","x":"Narrated Al-Bara:\n\n\"The last Ayah revealed\" or, \"The last thing revealed was: They ask you about a legal verdict. Say: 'Allah directs (thus) regarding Al-Kalalah (4:176).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا مَالِكُ بْنُ مِغْوَلٍ، عَنْ أَبِي السَّفَرِ، عَنِ الْبَرَاءِ، قَالَ آخِرُ آيَةٍ أُنْزِلَتْ أَوْ آخِرُ شَيْءٍ نَزَلَ ‏:‏ ‏(‏ يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ وَأَبُو السَّفَرِ اسْمُهُ سَعِيدُ بْنُ أَحْمَدَ الثَّوْرِيُّ وَيُقَالُ ابْنُ يُحْمِدَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3042","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3042","x":"Narrated Al-Bara:\n\n\"A man came to the Messenger of Allah (ﷺ) and said: 'O Messenger of Allah! They ask you about a legal verdict. Say: \"Allah directs (thus) regarding Al-Kalalah (4:176).\" So the Prophet (ﷺ) said to him: \"You should be sufficed with the Ayah of summer.\" (Meaning this Ayah, while in An-Nisa number 12, is mention of the topic, and it was revealed in the winter, this Ayah, revealed in the summer - the last revealed about it - explains it)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، عَنْ أَبِي بَكْرِ بْنِ عَيَّاشٍ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ ‏:‏ ‏(‏ يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ ‏)‏ فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ تُجْزِيكَ آيَةُ الصَّيْفِ ‏\"‏ ‏.‏","v":[]}]};